QT_ISI(12,{"1479":["(Dan tidak ada) huruf min di sini zaidah (suatu binatang melata pun di bumi) yaitu hewan yang melata di atas bumi (melainkan Allahlah yang memberi rezekinya) Dialah yang menanggung rezekinya sebagai karunia daripada-Nya (dan Dia mengetahui tempat berdiam binatang itu) tempat hidupnya di dunia atau pada tulang sulbi (dan tempat penyimpanannya) sesudah mati atau di dalam rahim. (Semuanya) yang telah disebutkan itu (tertulis dalam kitab yang nyata) kitab yang jelas, yaitu Lohmahfuz.",[["۞ وَمَا","And not"],["مِن","any"],["دَآبَّةٍۢ","moving creature"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["إِلَّا","but"],["عَلَى","on"],["ٱللَّهِ","Allah"],["رِزْقُهَا","(is) its provision"],["وَيَعْلَمُ","And He knows"],["مُسْتَقَرَّهَا","its dwelling place"],["وَمُسْتَوْدَعَهَا ۚ","and its place of storage"],["كُلٌّۭ","All"],["فِى","(is) in"],["كِتَـٰبٍۢ","a Record"],["مُّبِينٍۢ","clear"]]],"1480":["(Dan Dialah yang menciptakan langit dan bumi dalam enam hari) yang permulaannya adalah hari Ahad dan berakhir pada hari Jumat (dan adalah Arasy-Nya) sebelum diciptakan langit dan bumi (di atas air) yaitu berada di atas angin (agar Dia menguji kalian) lafal liyabluwakum berta'alluq kepada lafal khalaqa artinya, Allah menciptakan langit dan bumi beserta isinya yaitu berupa manfaat-manfaat dan maslahat-maslahat bagi kalian untuk menguji kalian (siapakah di antara kalian yang lebih baik amalnya) artinya yang lebih taat kepada Allah (dan jika kamu berkata) hai Muhammad, kepada penduduk Mekah (\"Sesungguhnya kalian akan dibangkitkan sesudah mati,\" niscaya orang-orang yang kafir itu akan berkata, \"Tiada lain) tidak lain (ini) yakni Alquran yang menceritakan adanya hari berbangkit seperti yang telah engkau katakan itu (hanyalah sihir yang nyata\") sihir yang jelas. Menurut qiraat dibaca saahirun bukannya sihrun; sedangkan yang diisyaratkan oleh musyar ilaih adalah Nabi Muhammad saw. bukannya Alquran.",[["وَهُوَ","And He"],["ٱلَّذِى","(is) the One Who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["فِى","in"],["سِتَّةِ","six"],["أَيَّامٍۢ","epochs"],["وَكَانَ","and His throne was"],["عَرْشُهُۥ","and His throne was"],["عَلَى","on"],["ٱلْمَآءِ","the water"],["لِيَبْلُوَكُمْ","that He might test [you]"],["أَيُّكُمْ","which of you"],["أَحْسَنُ","(is) best"],["عَمَلًۭا ۗ","(in) deed"],["وَلَئِن","But if"],["قُلْتَ","you say"],["إِنَّكُم","Indeed, you"],["مَّبْعُوثُونَ","(will be) resurrected"],["مِنۢ","after"],["بَعْدِ","after"],["ٱلْمَوْتِ","[the] death"],["لَيَقُولَنَّ","surely would say"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieved"],["إِنْ","This is not"],["هَـٰذَآ","This is not"],["إِلَّا","but"],["سِحْرٌۭ","a magic"],["مُّبِينٌۭ","clear"]]],"1481":["(Dan sesungguhnya jika Kami undurkan azab dari mereka sampai pada) datangnya (suatu waktu) beberapa waktu (yang ditentukan, niscaya mereka akan berkata) yang dimaksud dari keterangan ini adalah cemoohan (\"Apakah yang menghalanginya?\") apakah gerangan yang mencegah turunnya azab. Sebagai sanggahannya Allah berfirman: (Ingatlah, di waktu azab itu datang kepada mereka tidaklah dapat dipalingkan) tidak dapat ditahan lagi (dari mereka dan mereka diliputi) dikepung (oleh azab yang dahulunya mereka selalu memperolok-olokkannya) yang dimaksud adalah mereka memperolok-olokkan azab itu sebelumnya.",[["وَلَئِنْ","And if"],["أَخَّرْنَا","We delay"],["عَنْهُمُ","from them"],["ٱلْعَذَابَ","the punishment"],["إِلَىٰٓ","for"],["أُمَّةٍۢ","a time"],["مَّعْدُودَةٍۢ","determined"],["لَّيَقُولُنَّ","they will surely say"],["مَا","What"],["يَحْبِسُهُۥٓ ۗ","detains it"],["أَلَا","No doubt"],["يَوْمَ","(On) the Day"],["يَأْتِيهِمْ","it comes to them"],["لَيْسَ","not"],["مَصْرُوفًا","(will be) averted"],["عَنْهُمْ","from them"],["وَحَاقَ","and will surround"],["بِهِم","them"],["مَّا","what"],["كَانُوا۟","they used (to)"],["بِهِۦ","mock at [it]"],["يَسْتَهْزِءُونَ","mock at [it]"]]],"1482":["(Dan jika Kami rasakan kepada manusia) yang kafir (suatu rahmat dari Kami) yaitu berupa kekayaan dan kesehatan (kemudian rahmat itu Kami cabut daripadanya pastilah dia menjadi putus asa) merasa putus asa dari rahmat Allah (lagi tidak berterima kasih) sangat mengingkari-Nya.",[["وَلَئِنْ","And if"],["أَذَقْنَا","We give man a taste"],["ٱلْإِنسَـٰنَ","We give man a taste"],["مِنَّا","(of) Mercy from Us"],["رَحْمَةًۭ","(of) Mercy from Us"],["ثُمَّ","then"],["نَزَعْنَـٰهَا","We withdraw it"],["مِنْهُ","from him"],["إِنَّهُۥ","indeed, he"],["لَيَـُٔوسٌۭ","(is) despairing"],["كَفُورٌۭ","(and) ungrateful"]]],"1483":["(Dan jika kami rasakan kepadanya kebahagiaan sesudah bencana) kemiskinan dan kesengsaraan (yang menimpanya, niscaya dia akan berkata, \"Telah hilang keburukan-keburukan itu) yaitu bencana-bencana tersebut (dariku.\") akan tetapi ia tidak mempunyai perasaan bahwa kebahagiaan itu bakal lenyap darinya dan pula ia tidak mensyukurinya (Sesungguhnya dia sangat gembira) meluap (lagi bangga) terhadap manusia atas apa yang diberikan kepadanya.",[["وَلَئِنْ","But if"],["أَذَقْنَـٰهُ","We give him a taste"],["نَعْمَآءَ","(of) favor"],["بَعْدَ","after"],["ضَرَّآءَ","hardship"],["مَسَّتْهُ","(has) touched him"],["لَيَقُولَنَّ","surely, he will say"],["ذَهَبَ","Have gone"],["ٱلسَّيِّـَٔاتُ","the evils"],["عَنِّىٓ ۚ","from me"],["إِنَّهُۥ","Indeed, he"],["لَفَرِحٌۭ","(is) exultant"],["فَخُورٌ","(and) boastful"]]],"1484":["(Kecuali) tetapi (orang-orang yang sabar) terhadap bencana (dan mengerjakan amal-amal saleh) sewaktu diberi kebahagiaan (mereka itu beroleh ampunan dan pahala yang besar) yaitu surga.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["صَبَرُوا۟","(are) patient"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","the good deeds"],["أُو۟لَـٰٓئِكَ","those"],["لَهُم","for them"],["مَّغْفِرَةٌۭ","(will be) forgiveness"],["وَأَجْرٌۭ","and a reward"],["كَبِيرٌۭ","great"]]],"1485":["(Maka boleh jadi kamu) hai Muhammad (meninggalkan sebagian dari apa yang diwahyukan kepadamu) sehingga kamu tidak menyampaikannya kepada mereka karena mereka menganggap remeh terhadapnya (dan sempit karenanya dadamu) sewaktu engkau membacakannya kepada mereka, karena khawatir bahwa (mereka akan mengatakan, \"Mengapa tidak) bagaimana tidak (diturunkan kepadanya perbendaharaan atau datang bersama-sama dengan dia satu malaikat?\") yang membenarkannya sesuai dengan apa yang kami minta. (Sesungguhnya kamu hanyalah seorang pemberi peringatan) tugasmu hanyalah menyampaikan bukannya mendatangkan apa yang mereka kehendaki. (Dan Allah Pemelihara segala sesuatu) yakni Dia hafal kesemuanya, maka Dia membalas mereka karenanya.",[["فَلَعَلَّكَ","Then possibly you"],["تَارِكٌۢ","(may) give up"],["بَعْضَ","a part"],["مَا","(of) what"],["يُوحَىٰٓ","is revealed"],["إِلَيْكَ","to you"],["وَضَآئِقٌۢ","and straitened"],["بِهِۦ","by it"],["صَدْرُكَ","your breast"],["أَن","because"],["يَقُولُوا۟","they say"],["لَوْلَآ","Why not"],["أُنزِلَ","is sent down"],["عَلَيْهِ","for him"],["كَنزٌ","a treasure"],["أَوْ","or"],["جَآءَ","has come"],["مَعَهُۥ","with him"],["مَلَكٌ ۚ","an Angel"],["إِنَّمَآ","Only"],["أَنتَ","you"],["نَذِيرٌۭ ۚ","(are) a warner"],["وَٱللَّهُ","And Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["وَكِيلٌ","a Guardian"]]],"1486":["(Bahkan) akan tetapi apakah (mereka mengatakan, \"Muhammad telah membuat-buatnya\") yakni Alquran itu (Katakanlah, \"Kalau demikian, maka datangkanlah sepuluh surah-surah semisal dengannya) dalam masalah kefasihan bahasa dan ketinggian paramasastranya (yang dibuat-buat) karena sesungguhnya kalian sama denganku adalah orang-orang Arab yang fasih dalam berbahasa. Allah swt. menantang mereka untuk pertama kalinya supaya mereka mendatangkan sepuluh surah, kemudian pada tantangan yang berikutnya cukup hanya dengan satu surah saja (dan panggillah orang-orang yang kalian sanggup memanggilnya selain Allah) selain dari Allah (jika kalian memang orang-orang yang benar.\") di dalam tuduhan kalian yang menyatakan, bahwa Alquran itu hanyalah buat-buatan belaka.",[["أَمْ","Or"],["يَقُولُونَ","they say"],["افْتَرَاهُ ۖ","He has fabricated it"],["قُلْ","Say"],["فَأْتُوا۟","Then bring"],["بِعَشْرِ","ten"],["سُوَرٍۢ","Surahs"],["مِّثْلِهِۦ","like it"],["مُفْتَرَيَـٰتٍۢ","fabricated"],["وَٱدْعُوا۟","and call"],["مَنِ","whoever"],["ٱسْتَطَعْتُم","you can"],["مِّن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"1487":["(Jika) bila (mereka yang kalian seru tidak menerima seruan/ajakan kalian) yaitu orang-orang yang kalian ajak untuk membantu kalian (maka ketahuilah) khithab atau pembicaraan ditujukan kepada orang-orang musyrik (sesungguhnya Alquran itu diturunkan) berdasarkan (ilmu Allah) dan bukannya buat-buatan yang dilakukan terhadap-Nya (dan bahwasanya) an di sini adalah bentuk takhfif daripada anna (tidak ada Tuhan selain Dia, maka maukah kalian berserah diri kepada-Nya) sesudah adanya hujah-hujah yang pasti ini. Makna yang dimaksud ialah hendaknya kalian masuk Islam.",[["فَإِلَّمْ","Then if not"],["يَسْتَجِيبُوا۟","they respond"],["لَكُمْ","to you"],["فَٱعْلَمُوٓا۟","then know"],["أَنَّمَآ","that"],["أُنزِلَ","it was sent down"],["بِعِلْمِ","with the knowledge of Allah"],["ٱللَّهِ","with the knowledge of Allah"],["وَأَن","and that"],["لَّآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","Him"],["فَهَلْ","Then, would"],["أَنتُم","you"],["مُّسْلِمُونَ","(be) Muslims"]]],"1488":["(Barang siapa yang menghendaki kehidupan dunia dan perhiasannya) seumpamanya ia tetap bersikeras dalam kemusyrikannya. Menurut suatu pendapat ayat ini ditujukan kepada orang-orang yang berbuat ria atau pamer (niscaya Kami berikan kepada mereka balasan pekerjaannya dengan sempurna) pembalasan dari amal baik yang telah dikerjakannya, seperti sedekah dan bersilaturahmi (di dunia) umpamanya Kami meluaskan lapangan rezeki mereka (dan mereka di dalamnya) yakni di dunia (tidak dirugikan) artinya tidak akan dikurangi sedikit pun balasannya.",[["مَن","Whoever [is]"],["كَانَ","Whoever [is]"],["يُرِيدُ","desires"],["ٱلْحَيَوٰةَ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَزِينَتَهَا","and its adornments"],["نُوَفِّ","We will repay in full"],["إِلَيْهِمْ","to them"],["أَعْمَـٰلَهُمْ","(for) their deeds"],["فِيهَا","therein"],["وَهُمْ","and they"],["فِيهَا","in it"],["لَا","will not be lessened"],["يُبْخَسُونَ","will not be lessened"]]],"1489":["(Itulah orang-orang yang tidak memperoleh di akhirat kecuali neraka dan lenyaplah) dileburlah (apa yang telah mereka usahakan) itu (di akhirat nanti) sehingga mereka tidak mempunyai pahala lagi (dan sia-sialah apa yang telah mereka kerjakan.)",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones who "],["لَيْسَ","(is) not"],["لَهُمْ","for them"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["إِلَّا","except"],["ٱلنَّارُ ۖ","the Fire"],["وَحَبِطَ","And (has) gone in vain"],["مَا","what"],["صَنَعُوا۟","they did"],["فِيهَا","therein"],["وَبَـٰطِلٌۭ","and (is) worthless"],["مَّا","what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1490":["(Apakah orang yang mempunyai bukti) penjelasan (dari Rabbnya) yaitu Nabi saw. atau orang-orang mukmin yang dimaksud dengan bukti adalah Alquran (dan diikuti pula) dipanuti (oleh saksi) baginya yang membenarkannya (dari-Nya) yaitu dari Allah, yang dimaksud adalah malaikat Jibril (dan sebelumnya) sebelum Alquran (telah ada kitab Musa) yaitu kitab Taurat yang menyaksikan kebenaran Alquran pula (yang menjadi pedoman dan rahmat?) menjadi kata keterangan dari Alquran. Apakah keadaannya sama dengan orang-orang yang tidak demikian keadaannya? Tentu saja tidak (mereka itu) yakni orang-orang yang mempunyai bukti (beriman kepadanya) kepada Alquran, maka bagi mereka surga. (Dan barang siapa di antara golongan yang bersekutu ingkar kepada Alquran) semua orang-orang kafir (maka nerakalah tempat yang diancamkan baginya, karena itu janganlah kamu ragu-ragu) menaruh syak (kepadanya) kepada Alquran (Sesungguhnya Alquran itu benar-benar dari Rabbmu tetapi kebanyakan manusia) penduduk Mekah (tidak beriman).",[["أَفَمَن","Then is he who"],["كَانَ","is"],["عَلَىٰ","on"],["بَيِّنَةٍۢ","a clear proof"],["مِّن","from"],["رَّبِّهِۦ","his Lord"],["وَيَتْلُوهُ","and recites it"],["شَاهِدٌۭ","a witness"],["مِّنْهُ","from Him"],["وَمِن","and before it"],["قَبْلِهِۦ","and before it"],["كِتَـٰبُ","(was) a Book"],["مُوسَىٰٓ","(of) Musa"],["إِمَامًۭا","(as) a guide"],["وَرَحْمَةً ۚ","and (as) mercy"],["أُو۟لَـٰٓئِكَ","Those"],["يُؤْمِنُونَ","believe"],["بِهِۦ ۚ","in it"],["وَمَن","But whoever"],["يَكْفُرْ","disbelieves"],["بِهِۦ","in it"],["مِنَ","among"],["ٱلْأَحْزَابِ","the sects"],["فَٱلنَّارُ","then the Fire"],["مَوْعِدُهُۥ ۚ","(will be) his promised (meeting) place"],["فَلَا","So (do) not"],["تَكُ","be"],["فِى","in"],["مِرْيَةٍۢ","doubt"],["مِّنْهُ ۚ","about it"],["إِنَّهُ","Indeed, it"],["ٱلْحَقُّ","(is) the truth"],["مِن","from"],["رَّبِّكَ","your Lord"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"]]],"1491":["(Dan siapakah) tidak ada seorang pun (yang lebih lalim daripada orang yang membuat-buat dusta terhadap Allah?) dengan menisbatkan sekutu terhadap-Nya dan menganggapnya mempunyai anak. (Mereka itu akan dihadapkan kepada Rabb mereka) kelak di hari kiamat di antara semua makhluk-Nya (dan para saksi akan berkata) lafal asyhaad adalah bentuk jamak dari lafal syahiid yang artinya saksi. Mereka adalah para malaikat; mereka memberikan kesaksian, bahwa para rasul telah menyampaikan risalahnya, adapun orang-orang kafir mereka cap sebagai pendusta (\"Orang-orang inilah yang telah berdusta terhadap Rabb mereka.\" Ingatlah, kutukan Allah dilimpahkan atas orang-orang yang lalim) yaitu orang-orang musyrik.",[["وَمَنْ","And who"],["أَظْلَمُ","(is) more unjust"],["مِمَّنِ","than (he) who"],["ٱفْتَرَىٰ","invents"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًا ۚ","a lie"],["أُو۟لَـٰٓئِكَ","Those"],["يُعْرَضُونَ","will be presented"],["عَلَىٰ","before"],["رَبِّهِمْ","their Lord"],["وَيَقُولُ","and will say"],["ٱلْأَشْهَـٰدُ","the witnesses"],["هَـٰٓؤُلَآءِ","These (are)"],["ٱلَّذِينَ","those who"],["كَذَبُوا۟","lied"],["عَلَىٰ","against"],["رَبِّهِمْ ۚ","their Lord"],["أَلَا","No doubt"],["لَعْنَةُ","(The) curse of Allah"],["ٱللَّهِ","(The) curse of Allah"],["عَلَى","(is) on"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1492":["(Yaitu orang-orang yang menghalangi manusia dari jalan Allah) dari agama Islam (dan menghendaki supaya jalan itu) (bengkok) tidak lurus (Dan mereka terhadap hari kemudian adalah) lafal hum kedua mengukuhkan makna lafal hum pertama (orang-orang yang tidak percaya).",[["ٱلَّذِينَ","Those who"],["يَصُدُّونَ","hinder"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["وَيَبْغُونَهَا","and seek (in) it"],["عِوَجًۭا","crookedness"],["وَهُم","while they"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["هُمْ","[they]"],["كَـٰفِرُونَ","(are) disbelievers"]]],"1493":["(Orang-orang itu tidak mampu menghalang-halangi) Allah (di bumi ini dan sekali-kali tidak adalah bagi mereka selain Allah) selain-Nya (yang menolong mereka) maksudnya para penolong yang dapat mencegah azab Allah terhadap mereka. (Siksaan itu dilipatgandakan kepada mereka) karena mereka menyesatkan orang lain. (Mereka selalu tidak dapat mendengar) kebenaran (dan mereka selalu tidak melihat) kebenaran itu karena kebencian mereka yang sangat terhadap kebenaran itu sehingga digambarkan seolah-olah mereka tidak mampu untuk mendengar dan melihatnya.",[["أُو۟لَـٰٓئِكَ","Those"],["لَمْ","not"],["يَكُونُوا۟","will be"],["مُعْجِزِينَ","(able to) escape"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَمَا","and not"],["كَانَ","is"],["لَهُم","for them"],["مِّن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["مِنْ","any"],["أَوْلِيَآءَ ۘ","protectors"],["يُضَـٰعَفُ","And will be doubled"],["لَهُمُ","for them"],["ٱلْعَذَابُ ۚ","the punishment"],["مَا","Not"],["كَانُوا۟","they were"],["يَسْتَطِيعُونَ","able"],["ٱلسَّمْعَ","(to) hear"],["وَمَا","and not"],["كَانُوا۟","they used (to)"],["يُبْصِرُونَ","see"]]],"1494":["(Mereka itulah orang-orang yang merugikan dirinya sendiri) karena mereka menjerumuskan dirinya ke dalam neraka yang abadi (dan lenyaplah) terhapuslah (dari mereka apa yang selalu mereka ada-adakan) terhadap Allah, yaitu tuduhan mereka yang menyekutukan Allah.",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones who"],["خَسِرُوٓا۟","(have) lost"],["أَنفُسَهُمْ","their souls"],["وَضَلَّ","and lost"],["عَنْهُم","from them"],["مَّا","(is) what"],["كَانُوا۟","they used"],["يَفْتَرُونَ","(to) invent"]]],"1495":["(Pasti) sungguh (mereka itu di akhirat menjadi orang-orang yang paling merugi).",[["لَا","No"],["جَرَمَ","doubt"],["أَنَّهُمْ","that they"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["هُمُ","[they]"],["ٱلْأَخْسَرُونَ","(will be) the greatest losers"]]],"1496":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh dan merendahkan diri) merasa tenang dan aman, atau kembali (kepada Rabb mereka, mereka itu adalah penghuni-penghuni surga; mereka kekal di dalamnya).",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","good deeds"],["وَأَخْبَتُوٓا۟","and humble themselves"],["إِلَىٰ","before"],["رَبِّهِمْ","their Lord"],["أُو۟لَـٰٓئِكَ","those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَنَّةِ ۖ","(of) Paradise"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"1497":["(Perumpamaan) gambaran (kedua golongan itu) yakni orang-orang kafir dan orang-orang mukmin (seperti orang buta dan tuli) ini perumpamaan orang kafir (dengan orang yang dapat melihat dan dapat mendengar) ini perumpamaan orang mukmin. (Adakah kedua golongan itu sama keadaan dan sifatnya?) Tentu saja tidak. (Maka tidakkah kalian mengambil pelajaran) lafal tadzakkaruuna asalnya tatadzakkaruuna, kemudian huruf ta asal diidgamkan kepada huruf dzal sehingga jadilah tadzakkaruuna, artinya sama dengan lafal tatta'izhuuna, yaitu mengambil pelajaran.",[["۞ مَثَلُ","(The) example"],["ٱلْفَرِيقَيْنِ","(of) the two parties"],["كَٱلْأَعْمَىٰ","(is) like the blind"],["وَٱلْأَصَمِّ","and the deaf"],["وَٱلْبَصِيرِ","and the seer"],["وَٱلسَّمِيعِ ۚ","and the hearer"],["هَلْ","Are"],["يَسْتَوِيَانِ","they equal"],["مَثَلًا ۚ","(in) comparison"],["أَفَلَا","Then, will not"],["تَذَكَّرُونَ","you take heed"]]],"1498":["(Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, ia berkata, \"Sesungguhnya aku) bahwa aku. Menurut suatu qiraat lafal innii dengan memperkirakan adanya makna al-qaul yang artinya, dia berkata (adalah pemberi peringatan yang nyata bagi kalian) yakni jelas peringatannya.",[["وَلَقَدْ","And verily"],["أَرْسَلْنَا","We sent"],["نُوحًا","Nuh"],["إِلَىٰ","to"],["قَوْمِهِۦٓ","his people"],["إِنِّى","Indeed, I am"],["لَكُمْ","to you"],["نَذِيرٌۭ","a warner"],["مُّبِينٌ","clear"]]],"1499":["(Agar) supaya (kalian jangan menyembah selain Allah. Sesungguhnya aku takut kalian) jika kalian menyembah selain-Nya (akan ditimpa azab pada hari yang sangat menyakitkan.\") azab yang menyakitkan di dunia dan di akhirat.",[["أَن","That"],["لَّا","(do) not"],["تَعْبُدُوٓا۟","worship"],["إِلَّا","except"],["ٱللَّهَ ۖ","Allah"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["عَلَيْكُمْ","for you"],["عَذَابَ","(the) punishment"],["يَوْمٍ","(of) a Day"],["أَلِيمٍۢ","painful"]]],"1500":["(Maka berkatalah pemimpin-pemimpin yang kafir dari kaumnya,) mereka adalah terdiri dari orang-orang terhormat kaumnya (\"Kami tidak melihat kamu melainkan sebagai manusia biasa seperti kami) tidak ada kelebihan bagimu atas diri kami (dan kami tidak melihat orang-orang yang mengikuti kamu, melainkan orang-orang yang hina-dina di antara kami) yaitu orang-orang yang rendah di antara kami, seperti tukang tambal pakaian dan tukang sol sepatu (yang lekas percaya saja) dapat dibaca baadiya dan baadia yang artinya, mereka lekas percaya kepadamu tanpa berpikir lebih matang lagi. Lafal ini dinashabkan karena menjadi zharaf yang artinya, mereka terus percaya dengan begitu saja (dan kami tidak melihat kalian memiliki suatu kelebihan apa pun atas kami) sehingga karena kelebihan itulah kalian berhak untuk diikuti daripada kami (bahkan kami yakin bahwa kalian adalah orang-orang yang dusta\") dalam pengakuan risalah yang kalian bawa. Dalam hal ini mereka mengikut sertakan sebutan Nabi Nuh beserta kaum yang mengikutinya.",[["فَقَالَ","So said"],["ٱلْمَلَأُ","the chiefs"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["مِن","from"],["قَوْمِهِۦ","his people"],["مَا","Not"],["نَرَىٰكَ","we see you"],["إِلَّا","but"],["بَشَرًۭا","a man"],["مِّثْلَنَا","like us"],["وَمَا","and not"],["نَرَىٰكَ","we see you"],["ٱتَّبَعَكَ","followed [you]"],["إِلَّا","except"],["ٱلَّذِينَ","those who"],["هُمْ","[they]"],["أَرَاذِلُنَا","(are) the lowest of us"],["بَادِىَ","immature in opinion"],["ٱلرَّأْىِ","immature in opinion"],["وَمَا","And not"],["نَرَىٰ","we see"],["لَكُمْ","in you"],["عَلَيْنَا","over us"],["مِن","any"],["فَضْلٍۭ","merit"],["بَلْ","nay"],["نَظُنُّكُمْ","we think you"],["كَـٰذِبِينَ","(are) liars"]]],"1501":["(Berkata Nuh, \"Hai kaumku! Bagaimana pikiranmu) coba katakan kepadaku (jika aku ada mempunyai bukti yang nyata) penjelasan yang nyata (dari Rabbku dan diberi-Nya aku rahmat) kenabian (dari sisi-Nya tetapi rahmat itu disamarkan) disembunyikan (bagi kalian) dan menurut suatu qiraat dibaca fa`amiyat (apa akan kami paksakan kalian menerimanya) artinya apakah kami harus memaksakan kalian untuk menerimanya (padahal kalian tiada menyukainya?\") tidak mampu untuk melakukan hal tersebut.",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["أَرَءَيْتُمْ","Do you see"],["إِن","if"],["كُنتُ","I was"],["عَلَىٰ","on"],["بَيِّنَةٍۢ","(the) clear proof"],["مِّن","from"],["رَّبِّى","my Lord"],["وَءَاتَىٰنِى","while He has given me"],["رَحْمَةًۭ","mercy"],["مِّنْ","from"],["عِندِهِۦ","Himself"],["فَعُمِّيَتْ","but (it) has been obscured"],["عَلَيْكُمْ","from you"],["أَنُلْزِمُكُمُوهَا","should We compel you (to accept) it"],["وَأَنتُمْ","while you (are)"],["لَهَا","averse to it"],["كَـٰرِهُونَ","averse to it"]]],"1502":["(Dan dia berkata, \"Hai kaumku! Aku tiada meminta kepada kalian sebagai upah bagi seruanku) di dalam menyampaikan risalahku (harta benda) yang kalian berikan kepadaku sebagai imbalannya (tiada lain) (upahku) pahalaku (hanyalah dari Allah dan aku sekali-kali tidak akan mengusir orang-orang yang telah beriman) seperti apa yang kalian perintahkan supaya aku melakukannya. (Sesungguhnya mereka pasti akan bertemu dengan Rabbnya) melalui hari berbangkit kemudian Allah membalas mereka dan menghukum orang-orang yang menyakiti dan mengusir orang-orang yang beriman (tetapi aku memandang kalian suatu kaum yang tidak mengetahui.\") akibat dari perbuatan kalian yang demikian itu.",[["وَيَـٰقَوْمِ","And O my people"],["لَآ","not"],["أَسْـَٔلُكُمْ","I ask (of) you"],["عَلَيْهِ","for it"],["مَالًا ۖ","any wealth"],["إِنْ","Not"],["أَجْرِىَ","(is) my reward"],["إِلَّا","except"],["عَلَى","from"],["ٱللَّهِ ۚ","Allah"],["وَمَآ","And not"],["أَنَا۠","I am"],["بِطَارِدِ","going to drive away"],["ٱلَّذِينَ","those who"],["ءَامَنُوٓا۟ ۚ","believed"],["إِنَّهُم","Indeed, they"],["مُّلَـٰقُوا۟","(will) be meeting"],["رَبِّهِمْ","their Lord"],["وَلَـٰكِنِّىٓ","but I"],["أَرَىٰكُمْ","see you"],["قَوْمًۭا","(are) a people"],["تَجْهَلُونَ","ignorant"]]],"1503":["(Dan dia berkata, \"Hai kaumku! Siapakah yang akan menolongku) yang dapat membentengi diriku (dari Allah) dari azab-Nya (jika aku mengusir mereka) orang-orang yang beriman kepadaku, tentu saja tidak ada seorang penolong pun. (Maka tidakkah) mengapa tidak (kalian mengambil pelajaran) lafal tadzakkaruuna asalnya adalah tatadzakkaruuna, kemudian huruf ta asal diidgamkan kepada dzal sehingga jadilah tadzdzakkaruuna, artinya sama dengan tatta`izhuuna, yaitu mengambil pelajaran.",[["وَيَـٰقَوْمِ","And O my people"],["مَن","Who"],["يَنصُرُنِى","would help me"],["مِنَ","against"],["ٱللَّهِ","Allah"],["إِن","if"],["طَرَدتُّهُمْ ۚ","I drove them away"],["أَفَلَا","Then, will not"],["تَذَكَّرُونَ","you take heed"]]],"1504":["(Dan aku tidak mengatakan kepada kalian, bahwa, 'Aku mempunyai gudang-gudang rezeki dan kekayaan dari Allah dan tiada pula) aku (mengetahui yang gaib dan tidak pula aku mengatakan bahwa sesungguhnya aku adalah malaikat.') akan tetapi sesungguhnya aku adalah manusia biasa sama dengan kalian (dan tidak juga aku mengatakan kepada orang-orang yang dipandang hina) dipandang remeh (oleh penglihatan kalian, \"Sekali-kali Allah tidak akan mendatangkan kebaikan kepada mereka.\" Allah lebih mengetahui apa yang ada pada diri mereka) yang terpendam di dalam kalbu mereka (sesungguhnya aku kalau begitu) maksudnya jika aku mengatakan demikian (benar-benar termasuk orang-orang yang lalim).",[["وَلَآ","And not"],["أَقُولُ","I say"],["لَكُمْ","to you"],["عِندِى","(that) with me"],["خَزَآئِنُ","(are the) treasures"],["ٱللَّهِ","(of) Allah"],["وَلَآ","and not"],["أَعْلَمُ","I know"],["ٱلْغَيْبَ","the unseen"],["وَلَآ","and not"],["أَقُولُ","I say"],["إِنِّى","that I am"],["مَلَكٌۭ","an Angel"],["وَلَآ","and not"],["أَقُولُ","I say"],["لِلَّذِينَ","for those whom"],["تَزْدَرِىٓ","look down upon"],["أَعْيُنُكُمْ","your eyes"],["لَن","never"],["يُؤْتِيَهُمُ","will Allah give them"],["ٱللَّهُ","will Allah give them"],["خَيْرًا ۖ","any good"],["ٱللَّهُ","Allah"],["أَعْلَمُ","knows best"],["بِمَا","what"],["فِىٓ","(is) in"],["أَنفُسِهِمْ  ۖ","their souls"],["إِنِّىٓ","Indeed, I"],["إِذًۭا","then"],["لَّمِنَ","(will be) surely of"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1505":["(Mereka berkata, \"Hai Nuh! Sesungguhnya kamu telah berbantah dengan kami) telah memusuhi kami (dan kamu memperpanjang bantahanmu terhadap kami, maka datangkanlah kepada kami apa yang kamu ancamkan kepada kami) yaitu azab (jika kamu termasuk orang-orang yang benar\") di dalam ancaman yang kamu katakan itu.",[["قَالُوا۟","They said"],["يَـٰنُوحُ","O Nuh"],["قَدْ","Indeed"],["جَـٰدَلْتَنَا","you disputed with us"],["فَأَكْثَرْتَ","and you (have been) frequent"],["جِدَٰلَنَا","(in) dispute with us"],["فَأْتِنَا","So bring us"],["بِمَا","what"],["تَعِدُنَآ","you threaten us (with)"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1506":["(Nuh menjawab, \"Hanyalah Allah yang akan mendatangkan azab itu kepada kalian jika Dia menghendaki) supaya azab itu disegerakan terhadap kalian karena sesungguhnya urusan penurunan azab itu kembali kepada-Nya (dan kalian sekali-kali tidak dapat melepaskan diri) dari azab-Nya.",[["قَالَ","He said"],["إِنَّمَا","Only"],["يَأْتِيكُم","will bring it (on) you"],["بِهِ","will bring it (on) you"],["ٱللَّهُ","Allah"],["إِن","if"],["شَآءَ","He wills"],["وَمَآ","and not"],["أَنتُم","you (are)"],["بِمُعْجِزِينَ","one who (can) escape (it)"]]],"1507":["(Dan tidaklah bermanfaat kepada kalian nasihatku jika aku hendak memberi nasihat kepada kalian sekiranya Allah hendak menyesatkan kalian) artinya berkehendak untuk membuat kalian sesat. Jawab syarat tersirat dari makna yang terkandung di dalam kalimat, 'Dan tidaklah bermanfaat kepada kalian nasihatku.' (Dia adalah Rabb kalian dan kepada-Nyalah kalian dikembalikan\"). Selanjutnya Allah swt. berfirman:",[["وَلَا","And (will) not"],["يَنفَعُكُمْ","benefit you"],["نُصْحِىٓ","my advice"],["إِنْ","(even) if"],["أَرَدتُّ","I wish"],["أَنْ","to"],["أَنصَحَ","[I] advise"],["لَكُمْ","[to] you"],["إِن","if"],["كَانَ","it was Allah's"],["ٱللَّهُ","it was Allah's"],["يُرِيدُ","will"],["أَن","to"],["يُغْوِيَكُمْ ۚ","let you go astray"],["هُوَ","He (is)"],["رَبُّكُمْ","your Lord"],["وَإِلَيْهِ","and to Him"],["تُرْجَعُونَ","you will be returned"]]],"1508":["(Bahkan) malahan (mereka mengatakan) yang dimaksud adalah orang-orang kafir Mekah (\"Dia cuma membuat-buatnya saja.\") artinya Muhammad hanya membuat-buat Alquran saja (Katakanlah, \"Jika aku membuat-buatnya, maka hanya akulah yang memikul dosanya) azab sebagai akibat dari perbuatan itu (dan aku berlepas diri dari dosa yang kalian lakukan.\") yaitu dosa tuduhan kalian yang mencap diriku sebagai pembuat Alquran.",[["أَمْ","Or"],["يَقُولُونَ","(do) they say"],["ٱفْتَرَىٰهُ ۖ","He has invented it"],["قُلْ","Say"],["إِنِ","If"],["ٱفْتَرَيْتُهُۥ","I have invented it"],["فَعَلَىَّ","then on me"],["إِجْرَامِى","(is) my crime"],["وَأَنَا۠","but I am"],["بَرِىٓءٌۭ","innocent"],["مِّمَّا","of what"],["تُجْرِمُونَ","crimes you commit"]]],"1509":["(Dan diwahyukan kepada Nuh, bahwasanya sekali-kali tidak akan beriman di antara kaummu kecuali orang yang telah beriman saja, karena itu janganlah kamu bersedih hati) merasa susah (tentang apa yang selalu mereka kerjakan) yaitu perbuatan syirik. Maka Nabi Nuh mendoakan kebinasaan bagi mereka yang tidak beriman, yaitu yang disitir oleh firman-Nya, \"Wahai Rabbku! Janganlah Engkau biarkan di atas muka bumi ini...\" (Nuh 26) kemudian Allah mengabulkan doanya seraya berfirman:",[["وَأُوحِىَ","And it was revealed"],["إِلَىٰ","to"],["نُوحٍ","Nuh"],["أَنَّهُۥ","That"],["لَن","will never"],["يُؤْمِنَ","believe"],["مِن","from"],["قَوْمِكَ","your people"],["إِلَّا","except"],["مَن","(those) who"],["قَدْ","have already"],["ءَامَنَ","believed"],["فَلَا","So (do) not"],["تَبْتَئِسْ","(be) distressed"],["بِمَا","by what"],["كَانُوا۟","they have been"],["يَفْعَلُونَ","doing"]]],"1510":["(Dan buatlah bahtera) perahu (dengan pengawasan Kami) dengan pengawasan dan pemeliharaan Kami (dan petunjuk wahyu Kami) yakni perintah Kami (dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang lalim itu) orang-orang kafir itu, biarkanlah mereka binasa (sesungguhnya mereka itu akan ditenggelamkan).",[["وَٱصْنَعِ","And construct"],["ٱلْفُلْكَ","the ship"],["بِأَعْيُنِنَا","under Our Eyes"],["وَوَحْيِنَا","and Our inspiration"],["وَلَا","and (do) not"],["تُخَـٰطِبْنِى","address Me"],["فِى","concerning"],["ٱلَّذِينَ","those who"],["ظَلَمُوٓا۟ ۚ","wronged"],["إِنَّهُم","indeed, they (are)"],["مُّغْرَقُونَ","the ones (to be) drowned"]]],"1511":["(Dan mulailah Nuh membuat bahtera) dimaksud menceritakan keadaan masa lampau (Dan setiap kali lewat kepada Nuh segolongan) sebagian (dari kaumnya, mereka mengejeknya) mereka memperolok-olokkannya. (Berkatalah Nuh, \"Jika kalian mengejek kami, maka sesungguhnya kami pun akan mengejek kalian sebagaimana kalian mengejek kami) jika kami selamat dan kalian tenggelam nanti.",[["وَيَصْنَعُ","And he was constructing"],["ٱلْفُلْكَ","the ship"],["وَكُلَّمَا","and every time"],["مَرَّ","passed"],["عَلَيْهِ","by him"],["مَلَأٌۭ","(the) chiefs"],["مِّن","of"],["قَوْمِهِۦ","his people"],["سَخِرُوا۟","they ridiculed"],["مِنْهُ ۚ","[of] him"],["قَالَ","He said"],["إِن","If"],["تَسْخَرُوا۟","you ridicule"],["مِنَّا","us"],["فَإِنَّا","then we"],["نَسْخَرُ","can ridicule"],["مِنكُمْ","you"],["كَمَا","as"],["تَسْخَرُونَ","you ridicule"]]],"1512":["(Kelak kalian akan mengetahui siapa) lafal man di sini maushul atau kata sambung, kedudukannya menjadi maf`ul atau objek dari lafal ta`lamuuna (yang akan ditimpa oleh azab yang menghinakannya dan yang akan ditimpa) akan dikenakan (kepadanya azab yang kekal.\")",[["فَسَوْفَ","And soon"],["تَعْلَمُونَ","you will know"],["مَن","(on) whom"],["يَأْتِيهِ","will come"],["عَذَابٌۭ","a punishment"],["يُخْزِيهِ","(that) will disgrace him"],["وَيَحِلُّ","and will descend"],["عَلَيْهِ","on him"],["عَذَابٌۭ","a punishment"],["مُّقِيمٌ","lasting"]]],"1513":["(Hingga) mengisahkan batas pembuatan bahtera (apabila perintah Kami datang) yang membinasakan mereka (dan dapur telah memancarkan air) yang dimaksud adalah dapur pemanggangan roti, hal itu merupakan pertanda bagi Nabi Nuh. (Kami berfirman, \"Muatkanlah ke dalam bahtera itu) ke dalam perahu itu (dari masing-masing binatang sepasang) yaitu jenis jantan dan betina dari semua jenis binatang (yaitu sejodoh) jantan dan betina. Lafal itsnain ini berkedudukan menjadi maf'ul atau objek. Dan disebutkan di dalam kisah Nabi Nuh, bahwasanya Allah swt. mengumpulkan kepada Nabi Nuh semua binatang buas dan semua jenis unggas atau burung. Kemudian Nabi Nuh a.s. memukulkan tangannya kepada setiap jenis binatang itu; maka tangan kanannya mengenai jenis jantan sedangkan tangan kirinya mengenai jenis betina, lalu ia memuatkannya ke dalam perahu (dan keluargamu) yaitu istri dan anak-anaknya (kecuali orang yang telah terdahulu ketetapan terhadapnya) di antara keluargamu yang sudah dipastikan akan binasa, yaitu anaknya yang bernama Kan'an dan istrinya. Sedangkan Sam, Ham, dan Yafits dibawa oleh Nabi Nuh ke dalam bahtera berikut istri-istri mereka yang berjumlah tiga orang (dan muatkan pula orang-orang yang beriman.\" Dan tidak beriman terhadap Nabi Nuh itu melainkan sedikit). Dikatakan, bahwa jumlah mereka yang beriman itu hanya ada enam orang lelaki dan istri-istri mereka. Menurut pendapat yang lain dikatakan, bahwa jumlah orang-orang yang termuat di dalam bahtera itu ada delapan puluh orang; separuh di antara mereka terdiri dari kaum laki-laki sedangkan separuh yang lainnya terdiri dari kaum wanita.",[["حَتَّىٰٓ","Till"],["إِذَا","when"],["جَآءَ","came"],["أَمْرُنَا","Our command"],["وَفَارَ","and overflowed"],["ٱلتَّنُّورُ","the oven"],["قُلْنَا","We said"],["ٱحْمِلْ","Load"],["فِيهَا","in it"],["مِن","of"],["كُلٍّۢ","every kind"],["زَوْجَيْنِ","a pair"],["ٱثْنَيْنِ","two"],["وَأَهْلَكَ","and your family"],["إِلَّا","except"],["مَن","who"],["سَبَقَ","has preceded"],["عَلَيْهِ","against him"],["ٱلْقَوْلُ","the word"],["وَمَنْ","and whoever"],["ءَامَنَ ۚ","believed"],["وَمَآ","And not"],["ءَامَنَ","believed"],["مَعَهُۥٓ","with him"],["إِلَّا","except"],["قَلِيلٌۭ","a few"]]],"1514":["(Dan ia berkata) yakni Nabi Nuh (\"Naiklah kamu sekalian ke dalamnya dengan menyebut nama Allah di waktu berlayar dan berlabuhnya.\") artinya sewaktu berlayar dan sewaktu berlabuh. (Sesungguhnya Rabbku benar-benar Maha Pengampun lagi Maha Penyayang) di mana Dia tidak membinasakan kami.",[["۞ وَقَالَ","And he said"],["ٱرْكَبُوا۟","Embark"],["فِيهَا","in it"],["بِسْمِ","in the name"],["ٱللَّهِ","of Allah"],["مَجْر۪ىٰهَا","(is) its course"],["وَمُرْسَىٰهَآ ۚ","and its anchorage"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["لَغَفُورٌۭ","(is) certainly Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"1515":["(Dan bahtera itu berlayar membawa mereka dalam gelombang laksana gunung) menggambarkan tentang tinggi dan besarnya gelombang. (Dan Nuh memanggil anaknya) yaitu Kan`an (sedangkan anaknya itu berada di tempat yang jauh) dari bahtera (\"Hai anakku! Naiklah bersama kami dan janganlah kamu berada bersama orang-orang yang kafir.\")",[["وَهِىَ","And it"],["تَجْرِى","sailed"],["بِهِمْ","with them"],["فِى","on"],["مَوْجٍۢ","the waves"],["كَٱلْجِبَالِ","like mountains"],["وَنَادَىٰ","and Nuh called out"],["نُوحٌ","and Nuh called out"],["ٱبْنَهُۥ","(to) his son"],["وَكَانَ","and he was"],["فِى","[in]"],["مَعْزِلٍۢ","apart"],["يَـٰبُنَىَّ","O my son"],["ٱرْكَب","Embark"],["مَّعَنَا","with us"],["وَلَا","and (do) not"],["تَكُن","be"],["مَّعَ","with"],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"1516":["(Anaknya menjawab, \"Aku akan mencari perlindungan ke gunung yang dapat memelihara diriku) yang dapat menyelamatkan diriku (dari air bah ini.\" Nuh berkata, \"Tidak ada yang melindungi hari ini dari azab Allah) dari siksaan-Nya (selain) kecuali hanya (Zat Yang Maha Penyayang.\") yaitu Allah sendiri, hanya Dialah yang dapat menolong. Selanjutnya Allah berfirman mengisahkan kelanjutannya. (Dan gelombang menjadi penghalang antara keduanya, maka jadilah anak itu termasuk orang-orang yang ditenggelamkan.)",[["قَالَ","He said"],["سَـَٔاوِىٓ","I will betake myself"],["إِلَىٰ","to"],["جَبَلٍۢ","a mountain"],["يَعْصِمُنِى","(that) will save me"],["مِنَ","from"],["ٱلْمَآءِ ۚ","the water"],["قَالَ","He said"],["لَا","(There is) no"],["عَاصِمَ","protector"],["ٱلْيَوْمَ","today"],["مِنْ","from"],["أَمْرِ","the Command of Allah"],["ٱللَّهِ","the Command of Allah"],["إِلَّا","except"],["مَن","(on) whom"],["رَّحِمَ ۚ","He has mercy"],["وَحَالَ","And came"],["بَيْنَهُمَا","(in) between them"],["ٱلْمَوْجُ","the waves"],["فَكَانَ","so he was"],["مِنَ","among"],["ٱلْمُغْرَقِينَ","the drowned"]]],"1517":["(Dan difirmankan, \"Hai bumi! Telanlah airmu) yang bersumberkan darimu, maka langsung bumi menelan airnya akan tetapi yang turun dari langit masih tetap, sehingga jadilah sungai-sungai dan laut-laut (dan hai hujan berhentilah.\") hentikanlah air hujanmu, maka seketika itu juga hujan berhenti (dan surutlah) berkuranglah (air itu hingga selesailah perintah Allah) kaum Nabi Nuh telah selesai dibinasakan (dan bahtera itu berlabuh) bahtera Nabi Nuh berhenti (di atas bukit Al-Judi) nama sebuah bukit yang terletak di suatu pulau dekat dengan negeri Maushul (dan dikatakan, \"Binasalah) hancurlah (orang-orang yang lalim.\") yaitu orang-orang yang kafir.",[["وَقِيلَ","And it was said"],["يَـٰٓأَرْضُ","O earth"],["ٱبْلَعِى","Swallow"],["مَآءَكِ","your water"],["وَيَـٰسَمَآءُ","and O sky"],["أَقْلِعِى","Withhold"],["وَغِيضَ","And subsided"],["ٱلْمَآءُ","the water"],["وَقُضِىَ","and was fulfilled"],["ٱلْأَمْرُ","the Command"],["وَٱسْتَوَتْ","And it rested"],["عَلَى","on"],["ٱلْجُودِىِّ ۖ","the Judi"],["وَقِيلَ","And it was said"],["بُعْدًۭا","Away"],["لِّلْقَوْمِ","with the people"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1518":["(Dan Nuh berseru kepada Rabbnya seraya berkata, \"Ya Rabbku! Sesungguhnya anakku) yaitu Kan'an (termasuk keluargaku) sedangkan Engkau telah menjanjikan kepadaku akan menyelamatkan mereka (dan sesungguhnya janji Engkau itulah yang benar) janji yang tidak akan diingkari. (Dan Engkau adalah hakim yang seadil-adilnya.\") paling mengetahui masalah kehakiman dan paling adil.",[["وَنَادَىٰ","And Nuh called"],["نُوحٌۭ","And Nuh called"],["رَّبَّهُۥ","(to) his Lord"],["فَقَالَ","and said"],["رَبِّ","O my Lord"],["إِنَّ","Indeed"],["ٱبْنِى","my son"],["مِنْ","(is) of"],["أَهْلِى","my family"],["وَإِنَّ","and indeed"],["وَعْدَكَ","Your promise"],["ٱلْحَقُّ","(is) true"],["وَأَنتَ","and You"],["أَحْكَمُ","(are) the Most Just"],["ٱلْحَـٰكِمِينَ","(of) the judges"]]],"1519":["(Dan berfirmanlah) Allah swt. (\"Hai Nuh! Sesungguhnya dia bukan termasuk keluargamu) yang dijanjikan akan diselamatkan, atau dia bukan termasuk pemeluk agamamu (sesungguhnya) permintaanmu kepada-Ku yang memohon supaya dia diselamatkan (perbuatan yang tidak baik) karena sesungguhnya dia adalah orang kafir, dan tidak ada keselamatan bagi orang-orang kafir. Menurut qiraat lain dibaca `amila sedangkan lafal ghairu dibaca ghaira dan dhamir kembali kepada anaknya Nabi Nuh, artinya sesungguhnya dia telah mengerjakan perbuatan yang tidak baik (sebab itu janganlah kamu memohon kepada-Ku) dapat dibaca tas-alanna dan tas-alan (sesuatu yang kamu tidak mengetahuinya) yaitu memohon supaya anakmu diselamatkan. (Sesungguhnya Aku memperingatkan kepadamu supaya kamu jangan termasuk orang-orang yang tidak berpengetahuan\") yang menyebabkan kamu meminta kepada-Ku apa-apa yang kamu tidak ketahui hakikatnya.",[["قَالَ","He said"],["يَـٰنُوحُ","O Nuh"],["إِنَّهُۥ","Indeed, he"],["لَيْسَ","(is) not"],["مِنْ","of"],["أَهْلِكَ ۖ","your family"],["إِنَّهُۥ","indeed, [he]"],["عَمَلٌ","(his) deed"],["غَيْرُ","(is) other than"],["صَـٰلِحٍۢ ۖ","righteous"],["فَلَا","so (do) not"],["تَسْـَٔلْنِ","ask Me"],["مَا","(about) what"],["لَيْسَ","not"],["لَكَ","you have"],["بِهِۦ","of it"],["عِلْمٌ ۖ","any knowledge"],["إِنِّىٓ","Indeed, I"],["أَعِظُكَ","admonish you"],["أَن","lest"],["تَكُونَ","you be"],["مِنَ","among"],["ٱلْجَـٰهِلِينَ","the ignorant"]]],"1520":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya aku berlindung kepada Engkau) daripada perbuatan (memohon kepada Engkau sesuatu yang aku tiada mengetahui hakikatnya. Dan sekiranya Engkau tidak memberi ampun kepadaku) atas apa yang aku telah terlanjur melakukannya (dan tidak menaruh belas kasihan kepadaku, niscaya aku akan termasuk orang-orang yang merugi\")",[["قَالَ","He said"],["رَبِّ","O my Lord"],["إِنِّىٓ","Indeed, I"],["أَعُوذُ","seek refuge"],["بِكَ","in You"],["أَنْ","that"],["أَسْـَٔلَكَ","I (should) ask You"],["مَا","what"],["لَيْسَ","not"],["لِى","I have"],["بِهِۦ","of it"],["عِلْمٌۭ ۖ","knowledge"],["وَإِلَّا","And unless"],["تَغْفِرْ","You forgive"],["لِى","me"],["وَتَرْحَمْنِىٓ","and You have mercy on me"],["أَكُن","I will be"],["مِّنَ","among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"1521":["(Difirmankan, \"Hai Nuh! Turunlah) turunlah dari bahtera (dengan selamat) dengan selamat atau dengan hormat (dari Kami dan penuh keberkahan) penuh kebaikan (atasmu dan atas umat-umat yang mukmin dan orang-orang yang bersamamu\") di dalam bahtera, yang dimaksud adalah anak cucu dan keturunannya, yaitu orang-orang yang beriman (Dan ada pula umat-umat) dibaca rafa` yaitu umamun, makna yang dimaksud adalah umat-umat yang bersamamu (yang Kami beri kesenangan pada mereka) di dunia (kemudian mereka akan ditimpa azab yang pedih dari Kami) di akhirat kelak; mereka adalah orang-orang kafir.",[["قِيلَ","It was said"],["يَـٰنُوحُ","O Nuh"],["ٱهْبِطْ","Go down"],["بِسَلَـٰمٍۢ","with peace"],["مِّنَّا","from Us"],["وَبَرَكَـٰتٍ","and blessings"],["عَلَيْكَ","on you"],["وَعَلَىٰٓ","and on"],["أُمَمٍۢ","the nations"],["مِّمَّن","from those"],["مَّعَكَ ۚ","with you"],["وَأُمَمٌۭ","But (to other) nations"],["سَنُمَتِّعُهُمْ","We will grant enjoyment"],["ثُمَّ","then"],["يَمَسُّهُم","will touch them"],["مِّنَّا","from Us"],["عَذَابٌ","a punishment"],["أَلِيمٌۭ","painful"]]],"1522":["(Itu adalah) ayat-ayat yang mengandung kisah Nabi Nuh (di antara berita-berita penting yang gaib) berita-berita yang belum engkau ketahui (yang Kami wahyukan kepadamu) hai Muhammad (tidak pernah kamu mengetahuinya dan tidak pula kaummu sebelum ini) sebelum diturunkannya Alquran ini. (Maka bersabarlah) di dalam menyampaikan risalah dan menghadapi perlakuan kaummu yang menyakitkan itu, sebagaimana Nabi Nuh bersabar (sesungguhnya kesudahan yang baik) yang terpuji (adalah bagi orang-orang yang bertakwa).",[["تِلْكَ","This"],["مِنْ","(is) from"],["أَنۢبَآءِ","the news"],["ٱلْغَيْبِ","(of) the unseen"],["نُوحِيهَآ","(which) We reveal"],["إِلَيْكَ ۖ","to you"],["مَا","Not"],["كُنتَ","you were"],["تَعْلَمُهَآ","knowing it"],["أَنتَ","you"],["وَلَا","and not"],["قَوْمُكَ","your people"],["مِن","from"],["قَبْلِ","before"],["هَـٰذَا ۖ","this"],["فَٱصْبِرْ ۖ","So be patient"],["إِنَّ","indeed"],["ٱلْعَـٰقِبَةَ","the end"],["لِلْمُتَّقِينَ","(is) for the God fearing"]]],"1523":["(Dan) Kami utuskan (kepada kaum Ad saudara mereka) dari kabilah mereka sendiri (Hud. Ia berkata, \"Hai kaumku! Sembahlah Allah) artinya esakanlah Allah (sekali-kali tidak ada bagi kalian) huruf min di sini zaidah (Tuhan selain Dia, tiada lain) (kalian) yang dimaksud adalah penyembahan kalian terhadap berhala-berhala itu (hanyalah mengada-adakan saja) kalian berdusta terhadap Allah.",[["وَإِلَىٰ","And to"],["عَادٍ","Aad"],["أَخَاهُمْ","(We sent) their brother"],["هُودًۭا ۚ","Hud"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","(is) for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥٓ ۖ","other than Him"],["إِنْ","Not"],["أَنتُمْ","you"],["إِلَّا","(are) but"],["مُفْتَرُونَ","inventors"]]],"1524":["(Hai kaumku! Aku tidak meminta kepada kalian atas hal ini) yakni menganjurkan mentauhidkan Allah (upah. Tiada lain) (upahku hanyalah dari Allah yang telah menciptakanku) yang telah menjadikan aku (Maka tidakkah kalian memikirkannya?\")",[["يَـٰقَوْمِ","O my people"],["لَآ","Not"],["أَسْـَٔلُكُمْ","I ask you"],["عَلَيْهِ","for it"],["أَجْرًا ۖ","any reward"],["إِنْ","Not"],["أَجْرِىَ","(is) my reward"],["إِلَّا","except"],["عَلَى","from"],["ٱلَّذِى","the One Who"],["فَطَرَنِىٓ ۚ","created me"],["أَفَلَا","Then will not"],["تَعْقِلُونَ","you use reason"]]],"1525":["(Dan dia berkata, \"Hai kaumku! Mohonlah ampun kepada Rabb kalian) dari kemusyrikan (lalu bertobatlah kalian) kembalilah kalian (kepada-Nya) dengan menjalankan ketaatan (niscaya Dia menurunkan hujan) air hujan yang sebelumnya mereka kekeringan (kepada kalian dengan derasnya) sangat deras (dan Dia akan menambahkan kekuatan kepada) bersama dengan (kekuatanmu) yaitu berupa harta benda dan anak-anak (dan janganlah kalian berpaling dengan berbuat dosa.\") yakni berbuat kemusyrikan.",[["وَيَـٰقَوْمِ","And O my people"],["ٱسْتَغْفِرُوا۟","Ask forgiveness"],["رَبَّكُمْ","(of) your Lord"],["ثُمَّ","then"],["تُوبُوٓا۟","turn in repentance"],["إِلَيْهِ","to Him"],["يُرْسِلِ","He will send"],["ٱلسَّمَآءَ","(from) the sky (rain)"],["عَلَيْكُم","upon you"],["مِّدْرَارًۭا","(in) abundance"],["وَيَزِدْكُمْ","and increase you"],["قُوَّةً","(in) strength"],["إِلَىٰ","(added) to"],["قُوَّتِكُمْ","your strength"],["وَلَا","And (do) not"],["تَتَوَلَّوْا۟","turn away"],["مُجْرِمِينَ","(as) criminals"]]],"1526":["(Kaum Ad berkata, \"Hai Hud! Kamu tidak mendatangkan kepada kami suatu bukti yang nyata) yang menunjukkan kebenaran perkataanmu itu (dan kami sekali-kali tidak akan meninggalkan sembahan-sembahan kami karena perkataanmu) hanya karena ucapanmu itu (dan kami sekali-kali tidak akan mempercayai kamu).",[["قَالُوا۟","They said"],["يَـٰهُودُ","O Hud"],["مَا","You have not brought us"],["جِئْتَنَا","You have not brought us"],["بِبَيِّنَةٍۢ","clear proofs"],["وَمَا","and not"],["نَحْنُ","we"],["بِتَارِكِىٓ","(will) leave"],["ءَالِهَتِنَا","our gods"],["عَن","on"],["قَوْلِكَ","your saying"],["وَمَا","and not"],["نَحْنُ","we (are)"],["لَكَ","in you"],["بِمُؤْمِنِينَ","believers"]]],"1527":["(Tidaklah) tiadalah (kami mengatakan) perihal dirimu (melainkan, akan menimpamu) kamu akan tertimpa (penyakit gila karena sebagian sembahan kami\") karena sesembahan kami itu akan menyerapah kamu hingga menjadi orang gila, sebab kamu mencacinya, setelah itu kamu akan mengigau sendirian. (Hud menjawab, \"Sesungguhnya aku bersaksi kepada Allah) atas diriku sendiri (dan saksikanlah olehmu sekalian, bahwa sesungguhnya aku berlepas diri dari apa yang kalian persekutukan) itu terhadap Allah.",[["إِن","Not"],["نَّقُولُ","we say"],["إِلَّا","except (that)"],["ٱعْتَرَىٰكَ","have seized you"],["بَعْضُ","some"],["ءَالِهَتِنَا","(of) our gods"],["بِسُوٓءٍۢ ۗ","with evil"],["قَالَ","He said"],["إِنِّىٓ","Indeed, I"],["أُشْهِدُ","[I] call Allah to witness"],["ٱللَّهَ","[I] call Allah to witness"],["وَٱشْهَدُوٓا۟","and (you) bear witness"],["أَنِّى","that I am"],["بَرِىٓءٌۭ","innocent"],["مِّمَّا","of what"],["تُشْرِكُونَ","you associate"]]],"1528":["(Dari selain-Nya, sebab itu jalankanlah tipu daya terhadapku) lancarkanlah tipu daya untuk membinasakan diriku (oleh kalian semuanya) oleh kalian dan berhala-berhala sesembahan kalian itu (dan janganlah kalian memberi tangguh kepadaku) janganlah kalian menangguh-nangguhkannya.",[["مِن","Other than Him"],["دُونِهِۦ ۖ","Other than Him"],["فَكِيدُونِى","So plot against me"],["جَمِيعًۭا","all together"],["ثُمَّ","then"],["لَا","(do) not"],["تُنظِرُونِ","give me respite"]]],"1529":["(Sesungguhnya aku bertawakal kepada Allah, Rabbku dan Rabb kalian. Tidak ada) huruf min di sini adalah zaidah (suatu binatang) makhluk yang melata di bumi (melainkan Dialah yang memegang ubun-ubunnya) artinya, Dialah yang menguasai dan yang memaksakannya, maka tidak dapat memberikan manfaat dan tidak pula mudarat melainkan seizin-Nya. Dalam ayat ini disebutkan lafal an-naashiyah secara khusus, yang artinya ubun-ubun, karena seseorang yang dipegang ubun-ubunnya berarti sangat hina. Ini menggambarkan hinanya makhluk dibandingkan dengan Allah. (Sesungguhnya Rabbku di atas jalan yang lurus) yaitu jalan kebenaran dan keadilan.",[["إِنِّى","Indeed, I"],["تَوَكَّلْتُ","[I] put my trust"],["عَلَى","upon"],["ٱللَّهِ","Allah"],["رَبِّى","my Lord"],["وَرَبِّكُم ۚ","and your Lord"],["مَّا","(There is) not"],["مِن","of a moving creature"],["دَآبَّةٍ","of a moving creature"],["إِلَّا","but"],["هُوَ","He"],["ءَاخِذٌۢ","has grasp"],["بِنَاصِيَتِهَآ ۚ","of its forelock"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["عَلَىٰ","(is) on"],["صِرَٰطٍۢ","a path"],["مُّسْتَقِيمٍۢ","straight"]]],"1530":["(Jika kalian berpaling) asalnya ialah tatawallau, kemudian salah satu dari huruf ta dibuang sehingga jadilah tawallau, artinya berpaling (maka sesungguhnya aku telah menyampaikan kepada kalian apa/amanat yang aku diutus untuk menyampaikannya kepada kalian. Dan Rabbku akan mengganti kalian dengan kaum yang lain dari kalian; dan kalian tidak dapat membuat mudarat kepada-Nya sedikit pun) oleh sebab kemusyrikan kalian. (Sesungguhnya Rabbku adalah Maha Pemelihara segala sesuatu\") yang mengawasinya.",[["فَإِن","So if"],["تَوَلَّوْا۟","you turn away"],["فَقَدْ","then verily"],["أَبْلَغْتُكُم","I have conveyed to you"],["مَّآ","what"],["أُرْسِلْتُ","I was sent"],["بِهِۦٓ","with [it]"],["إِلَيْكُمْ ۚ","to you"],["وَيَسْتَخْلِفُ","And my Lord will give succession"],["رَبِّى","And my Lord will give succession"],["قَوْمًا","(to) a people"],["غَيْرَكُمْ","other than you"],["وَلَا","and not"],["تَضُرُّونَهُۥ","you will harm Him"],["شَيْـًٔا ۚ","(in) anything"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["عَلَىٰ","(is) on"],["كُلِّ","all"],["شَىْءٍ","things"],["حَفِيظٌۭ","a Guardian"]]],"1531":["(Dan tatkala datang perintah Kami) azab Kami (Kami selamatkan Hud dan orang-orang yang beriman bersama dia dengan rahmat) yakni petunjuk (dari Kami; dan Kami selamatkan pula mereka dari azab yang berat) dari siksaan yang keras di akhirat.",[["وَلَمَّا","And when"],["جَآءَ","came"],["أَمْرُنَا","Our command"],["نَجَّيْنَا","We saved"],["هُودًۭا","Hud"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believed"],["مَعَهُۥ","with him"],["بِرَحْمَةٍۢ","by a Mercy"],["مِّنَّا","from Us"],["وَنَجَّيْنَـٰهُم","and We saved them"],["مِّنْ","from"],["عَذَابٍ","a punishment"],["غَلِيظٍۢ","severe"]]],"1532":["(Dan itulah kisah kaum Ad) ini mengisyaratkan kepada peninggalan-peninggalan mereka. Makna yang dimaksud ialah berjalanlah kalian di muka bumi ini dan lihatlah bekas-bekas peninggalan mereka. Kemudian Allah swt. menggambarkan keadaan mereka, untuk itu Dia berfirman: (Mereka mengingkari tanda-tanda kekuasaan Rabb mereka dan mendurhakai rasul-rasul Allah) ungkapan di sini memakai bentuk jamak, dimaksud karena orang yang mendurhakai seorang rasul berarti sama saja dengan mendurhakai semua rasul. Karena pada apa yang didatangkan oleh para rasul itu hakikatnya bersumberkan dari asal yang sama, yaitu dari ajaran tauhid (dan mereka menuruti) artinya orang-orang yang rendah (perintah semua penguasa yang sewenang-wenang lagi menentang kebenaran) yakni selalu menentang perkara yang hak, yang dimaksud adalah para pemimpinnya.",[["وَتِلْكَ","And this"],["عَادٌۭ ۖ","(was) Aad"],["جَحَدُوا۟","they rejected"],["بِـَٔايَـٰتِ","(the) Signs"],["رَبِّهِمْ","(of) their Lord"],["وَعَصَوْا۟","and disobeyed"],["رُسُلَهُۥ","His Messengers"],["وَٱتَّبَعُوٓا۟","and followed"],["أَمْرَ","(the) command"],["كُلِّ","(of) every"],["جَبَّارٍ","tyrant"],["عَنِيدٍۢ","obstinate"]]],"1533":["(Dan mereka selalu diikuti dengan kutukan di dunia ini) dari manusia (dan begitu pula di hari kiamat) mereka akan dikutuk di hadapan makhluk semuanya. (Ingatlah sesungguhnya kaum Ad itu kafir) mereka ingkar (terhadap Rabb mereka. Ingatlah, sesungguhnya amat jauh) dari rahmat Allah (bagi kaum Ad yaitu kaumnya Hud).",[["وَأُتْبِعُوا۟","And they were followed"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلدُّنْيَا","world"],["لَعْنَةًۭ","(with) a curse"],["وَيَوْمَ","and (on the) Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) the Resurrection"],["أَلَآ","No doubt"],["إِنَّ","Indeed"],["عَادًۭا","Aad"],["كَفَرُوا۟","disbelieved"],["رَبَّهُمْ ۗ","their Lord"],["أَلَا","So"],["بُعْدًۭا","away"],["لِّعَادٍۢ","with Aad"],["قَوْمِ","(the) people"],["هُودٍۢ","(of) Hud"]]],"1534":["(Dan) Kami utus (kepada Tsamud saudara mereka) yang satu kabilah (Saleh. Saleh berkata, \"Hai kaumku! Sembahlah Allah) artinya esakanlah Dia (sekali-kali tidak ada bagi kalian Tuhan selain Dia. Dia telah menciptakan kalian) Dialah yang mula-mula menciptakan kalian (dari bumi) yaitu dengan menciptakan bapak moyang kalian, Adam, dari tanah (dan menjadikan kalian pemakmurnya) Dia menjadikan kalian sebagai para penghuni bumi (karena itu mohonlah ampunan-Nya) dari kemusyrikan (kemudian bertobatlah) kembali kalian (kepada-Nya) dengan menjalankan ketaatan. (Sesungguhnya Rabbku amat dekat) kepada makhluk-Nya melalui pengetahuan-Nya (lagi memperkenankan.\") doa orang yang meminta kepada-Nya.",[["۞ وَإِلَىٰ","And to"],["ثَمُودَ","Thamud"],["أَخَاهُمْ","(We sent) their brother"],["صَـٰلِحًۭا ۚ","Salih"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","you have"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥ ۖ","other than Him"],["هُوَ","He"],["أَنشَأَكُم","produced you"],["مِّنَ","from"],["ٱلْأَرْضِ","the earth"],["وَٱسْتَعْمَرَكُمْ","and settled you"],["فِيهَا","in it"],["فَٱسْتَغْفِرُوهُ","So ask forgiveness of Him"],["ثُمَّ","then"],["تُوبُوٓا۟","turn in repentance"],["إِلَيْهِ ۚ","to Him"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["قَرِيبٌۭ","(is) near"],["مُّجِيبٌۭ","All-Responsive"]]],"1535":["(Kaum Tsamud berkata, \"Hai Saleh! Sesungguhnya engkau adalah seorang di antara kami yang kami harapkan) kami mengharapkan semoga engkau menjadi penghulu dan pemimpin kami (sebelum ini) sebelum apa yang kamu lakukan itu (apakah kamu melarang kami untuk menyembah apa yang disembah oleh bapak-bapak kami) yaitu berhala-berhala (dan sesungguhnya kami betul-betul dalam keraguan terhadap agama yang kamu serukan kepada kami) yaitu agama tauhid (lagi sangat gelisah.\") maksudnya yang diserukannya itu amat meresahkan.",[["قَالُوا۟","They said"],["يَـٰصَـٰلِحُ","O Salih"],["قَدْ","Verily"],["كُنتَ","you were"],["فِينَا","among us"],["مَرْجُوًّۭا","the one in whom hope was placed"],["قَبْلَ","before"],["هَـٰذَآ ۖ","this"],["أَتَنْهَىٰنَآ","Do you forbid us"],["أَن","that"],["نَّعْبُدَ","we worship"],["مَا","what"],["يَعْبُدُ","our forefathers worshipped"],["ءَابَآؤُنَا","our forefathers worshipped"],["وَإِنَّنَا","And indeed we"],["لَفِى","surely (are) in"],["شَكٍّۢ","doubt"],["مِّمَّا","about what"],["تَدْعُونَآ","you call us"],["إِلَيْهِ","to it"],["مُرِيبٍۢ","suspicious"]]],"1536":["(Saleh berkata, \"Hai kaumku! Bagaimana pikiran kalian jika aku mempunyai bukti) bukti yang jelas (dari Rabbku dan diberi-Nya aku rahmat daripada-Nya?) kenabian (Maka siapakah yang akan menolong aku) yang dapat memelihara diriku (dari Allah) maksudnya dari azab-Nya (jika aku mendurhakai-Nya. Sebab itu kalian tidak menambah apa pun kepadaku) dengan perintah kalian yang menyuruhku untuk melakukan hal tersebut (selain daripada kerugian.\") penyesatan.",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["أَرَءَيْتُمْ","Do you see"],["إِن","if"],["كُنتُ","I am"],["عَلَىٰ","on"],["بَيِّنَةٍۢ","a clear proof"],["مِّن","from"],["رَّبِّى","my Lord"],["وَءَاتَىٰنِى","and He has given me"],["مِنْهُ","from Him"],["رَحْمَةًۭ","a Mercy"],["فَمَن","then who"],["يَنصُرُنِى","(can) help me"],["مِنَ","against"],["ٱللَّهِ","Allah"],["إِنْ","if"],["عَصَيْتُهُۥ ۖ","I (were to) disobey Him"],["فَمَا","So not"],["تَزِيدُونَنِى","you would increase me"],["غَيْرَ","but"],["تَخْسِيرٍۢ","(in) loss"]]],"1537":["(\"Hai kaumku! Inilah unta betina dari Allah sebagai mukjizat yang menunjukkan kebenaran untuk kalian) lafal aayatan berkedudukan menjadi hal atau kata keterangan sedangkan yang menjadi amilnya adalah isim isyarah atau lafal haadzihii tadi (sebab itu biarkanlah dia makan di bumi Allah, dan janganlah kalian mengganggunya dengan gangguan apa pun) seperti menyembelihnya (yang akan menyebabkan kalian ditimpa azab yang dekat.\") jika kalian menyembelihnya.",[["وَيَـٰقَوْمِ","And O my people"],["هَـٰذِهِۦ","This"],["نَاقَةُ","she-camel"],["ٱللَّهِ","(of) Allah"],["لَكُمْ","(is) for you"],["ءَايَةًۭ","a Sign"],["فَذَرُوهَا","so leave her"],["تَأْكُلْ","to eat"],["فِىٓ","in"],["أَرْضِ","the earth"],["ٱللَّهِ","(of) Allah"],["وَلَا","and (do) not"],["تَمَسُّوهَا","touch her"],["بِسُوٓءٍۢ","with harm"],["فَيَأْخُذَكُمْ","lest will seize you"],["عَذَابٌۭ","a punishment"],["قَرِيبٌۭ","impending"]]],"1538":["(Maka mereka menyembelihnya) unta betina itu disembelih oleh seseorang yang kuat atas perintah mereka (maka ia berkata) Nabi Saleh (\"Bersuka-rialah kalian) bersenang-senanglah kalian (di rumah kalian selama tiga hari) kemudian kalian akan binasa (itu adalah janji yang tidak dapat didustakan.\") janji yang tidak diingkari lagi.",[["فَعَقَرُوهَا","But they hamstrung her"],["فَقَالَ","So he said"],["تَمَتَّعُوا۟","Enjoy (yourselves)"],["فِى","in"],["دَارِكُمْ","your home(s)"],["ثَلَـٰثَةَ","(for) three"],["أَيَّامٍۢ ۖ","days"],["ذَٰلِكَ","That"],["وَعْدٌ","(is) a promise"],["غَيْرُ","not"],["مَكْذُوبٍۢ","(to) be belied"]]],"1539":["(Maka tatkala datang perintah Kami) yang memerintahkan supaya mereka dibinasakan (Kami selamatkan Saleh beserta orang-orang yang beriman bersama dia) jumlah mereka ada empat ribu orang (dengan rahmat dari Kami dan) Kami selamatkan pula mereka (dari kehinaan di hari itu) kalau dibaca yaumi-idzin dianggap sebagai isim yang mu`rab dan kalau dibaca yaumaidzin dianggap sebagai isim yang mabni karena diidhafatkan kepada isim yang mabni pula; demikianlah menurut pendapat kebanyakan ahli nahwu. (Sesungguhnya Rabbmu Dialah Yang Maha Kuasa lagi Maha Perkasa) Maha Menang.",[["فَلَمَّا","So when"],["جَآءَ","came"],["أَمْرُنَا","Our command"],["نَجَّيْنَا","We saved"],["صَـٰلِحًۭا","Salih"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believed"],["مَعَهُۥ","with him"],["بِرَحْمَةٍۢ","by a Mercy"],["مِّنَّا","from Us"],["وَمِنْ","and from"],["خِزْىِ","(the) disgrace"],["يَوْمِئِذٍ ۗ","(of) that Day"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["هُوَ","He"],["ٱلْقَوِىُّ","(is) All-Strong"],["ٱلْعَزِيزُ","All-Mighty"]]],"1540":["(Dan satu suara yang keras yang mengguntur menimpa orang-orang yang lalim itu lalu mereka mati bergelimpangan di tempat tinggal mereka) dalam keadaan bersimpuh pada lutut mereka padahal mereka telah mati semuanya.",[["وَأَخَذَ","And seized"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["ٱلصَّيْحَةُ","the thunderous blast"],["فَأَصْبَحُوا۟","then they became"],["فِى","in"],["دِيَـٰرِهِمْ","their homes"],["جَـٰثِمِينَ","fallen prone"]]],"1541":["(Seolah-olah) lafal ka-an adalah takhfif daripada ka-anna sedangkan isimnya tidak disebutkan, kepanjangannya adalah ka-annahum, artinya seolah-olah mereka (belum pernah berdiam) belum pernah tinggal (di tempat itu) di dalam rumah mereka. (Ingatlah, sesungguhnya kaum Tsamud mengingkari Tuhan mereka. Ingatlah, kebinasaanlah bagi kaum Tsamud) lafal tsamuud dapat ditanwinkan sehingga menjadi tsamuudan dan dapat pula dibaca tanpa memakai tanwin sehingga menjadi tsamuuda. Makna yang dimaksud ialah kabilahnya.",[["كَأَن","As if"],["لَّمْ","not"],["يَغْنَوْا۟","they (had) prospered"],["فِيهَآ ۗ","therein"],["أَلَآ","No doubt"],["إِنَّ","indeed"],["ثَمُودَا۟","Thamud"],["كَفَرُوا۟","disbelieved"],["رَبَّهُمْ ۗ","(in) their Lord"],["أَلَا","so"],["بُعْدًۭا","away"],["لِّثَمُودَ","with Thamud"]]],"1542":["(Dan sesungguhnya utusan-utusan Kami telah datang kepada Ibrahim dengan membaca kabar gembira) yaitu akan diberi anak bernama Ishak dan menyusul Yakub anak Ishak sesudah itu. (mereka mengucapkan, \"Selamat.\") lafal salaaman menjadi mashdar (Ibrahim menjawab, \"Selamatlah.\") atas kalian (Maka tidak lama kemudian Ibrahim menyuguhkan daging anak sapi yang dipanggang) daging panggang anak sapi.",[["وَلَقَدْ","And certainly"],["جَآءَتْ","came"],["رُسُلُنَآ","Our messengers"],["إِبْرَٰهِيمَ","(to) Ibrahim"],["بِٱلْبُشْرَىٰ","with glad tidings"],["قَالُوا۟","they said"],["سَلَـٰمًۭا ۖ","Peace"],["قَالَ","He said"],["سَلَـٰمٌۭ ۖ","Peace"],["فَمَا","and not he delayed"],["لَبِثَ","and not he delayed"],["أَن","to"],["جَآءَ","bring"],["بِعِجْلٍ","a calf"],["حَنِيذٍۢ","roasted"]]],"1543":["(Maka tatkala dilihatnya tangan mereka tidak menjamahnya, Ibrahim memandang aneh perbuatan mereka) merasa heran dengan kelakuan mereka itu (dan mulai timbul) memendam rasa di dalam hati (rasa takut terhadap mereka) ketakutan. (Malaikat itu berkata, \"Jangan kamu takut, sesungguhnya kami adalah malaikat-malaikat yang diutus kepada kaum Luth.\") untuk membinasakan mereka.",[["فَلَمَّا","But when"],["رَءَآ","he saw"],["أَيْدِيَهُمْ","their hands"],["لَا","not"],["تَصِلُ","reaching"],["إِلَيْهِ","to it"],["نَكِرَهُمْ","he felt unfamiliar of them"],["وَأَوْجَسَ","and felt apprehension"],["مِنْهُمْ","from them"],["خِيفَةًۭ ۚ","[a fear]"],["قَالُوا۟","They said"],["لَا","(Do) not"],["تَخَفْ","fear"],["إِنَّآ","Indeed, we"],["أُرْسِلْنَآ","[we] have been sent"],["إِلَىٰ","to"],["قَوْمِ","(the) people"],["لُوطٍۢ","(of) Lut"]]],"1544":["(Dan istrinya) yakni istri Nabi Ibrahim, yaitu Siti Sarah (berdiri) melayani mereka (lalu dia tersenyum) merasa gembira dengan akan dibinasakannya kaum Luth (maka Kami sampaikan kepadanya berita gembira tentang kelahiran Ishak dan menyusul sesudah) (Ishak Yakub) yaitu anak Nabi Ishak yang sempat melihat Nabi Ibrahim.",[["وَٱمْرَأَتُهُۥ","And his wife"],["قَآئِمَةٌۭ","(was) standing"],["فَضَحِكَتْ","and she laughed"],["فَبَشَّرْنَـٰهَا","Then We gave her glad tidings"],["بِإِسْحَـٰقَ","of Isaac"],["وَمِن","and after"],["وَرَآءِ","and after"],["إِسْحَـٰقَ","Isaac"],["يَعْقُوبَ","(of) Yaqub"]]],"1545":["(Istrinya berkata, \"Sungguh mengherankan) lafal wailataa ini merupakan kalimat yang biasa diucapkan di kala seseorang melihat perkara yang besar. Huruf ya yang ada padanya merupakan pergantian dari huruf alif (apakah aku akan melahirkan anak padahal aku adalah seorang perempuan tua) aku berumur sembilan puluh sembilan tahun (dan ini suamiku pun dalam keadaan yang sudah tua pula) Nabi Ibrahim pada saat itu berumur seratus atau seratus dua puluh tahun. Lafal syaikhan dinashabkan karena menjadi hal, sedangkan amilnya adalah isim isyarah yaitu lafal haadzaa tadi. (Sesungguhnya ini benar-benar suatu yang aneh\") kedua pasangan yang sama-sama telah tua dapat mempunyai anak.",[["قَالَتْ","She said"],["يَـٰوَيْلَتَىٰٓ","Woe to me"],["ءَأَلِدُ","Shall I bear a child"],["وَأَنَا۠","while I am"],["عَجُوزٌۭ","an old woman"],["وَهَـٰذَا","and this"],["بَعْلِى","my husband"],["شَيْخًا ۖ","(is) an old man"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَشَىْءٌ","(is) surely a thing"],["عَجِيبٌۭ","amazing"]]],"1546":["(Para malaikat itu berkata, \"Apakah kamu merasa heran tentang perintah Allah) yakni kekuasaan-Nya (itu adalah rahmat Allah dan keberkatan-Nya dicurahkan atas kalian) hai (ahlul bait) keluarga Nabi Ibrahim. (Sesungguhnya Allah Maha Terpuji) sangat terpuji (lagi Maha Pemurah\") Maha Pengasih.",[["قَالُوٓا۟","They said"],["أَتَعْجَبِينَ","Are you amazed"],["مِنْ","at"],["أَمْرِ","(the) decree of Allah"],["ٱللَّهِ ۖ","(the) decree of Allah"],["رَحْمَتُ","The Mercy of Allah"],["ٱللَّهِ","The Mercy of Allah"],["وَبَرَكَـٰتُهُۥ","and His blessings"],["عَلَيْكُمْ","(be) upon you"],["أَهْلَ","people"],["ٱلْبَيْتِ ۚ","(of) the house"],["إِنَّهُۥ","Indeed, He"],["حَمِيدٌۭ","(is) All-Praiseworthy"],["مَّجِيدٌۭ","All-Glorious"]]],"1547":["(Maka tatkala rasa takut hilang dari Ibrahim) perasaan takut telah lenyap dari hatinya (dan berita gembira telah datang kepadanya) yaitu memperoleh anak, mulailah (dia pun bersoal jawab dengan Kami) yakni dengan malaikat-malaikat utusan Kami (tentang) mengenai perihal (kaum Luth).",[["فَلَمَّا","And when"],["ذَهَبَ","(had) gone away"],["عَنْ","from"],["إِبْرَٰهِيمَ","Ibrahim"],["ٱلرَّوْعُ","the fright"],["وَجَآءَتْهُ","and had reached him"],["ٱلْبُشْرَىٰ","the glad tidings"],["يُجَـٰدِلُنَا","he argued with Us"],["فِى","concerning"],["قَوْمِ","the people"],["لُوطٍ","of Lut"]]],"1548":["(Sesungguhnya Ibrahim itu benar-benar penyantun) sangat sabar (lagi penghiba dan suka kembali kepada Allah) banyak istighfarnya atau ia banyak mengucapkan kalimat innaa lillaahi wa innaa ilaihi raaji`uuna. Maka Nabi Ibrahim berkata kepada para malaikat itu, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat tiga ratus orang beriman?\" Para malaikat menjawab, \"Tidak.\" Ia kembali bertanya, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat dua ratus orang yang beriman?\" Para malaikat menjawab, \"Tidak.\" Ia bertanya lagi, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat empat puluh orang yang beriman.\" Para malaikat menjawab, \"Tidak.\" Ia kembali bertanya, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat empat belas orang yang beriman?\" Mereka menjawab, \"Tidak.\" Nabi Ibrahim kembali bertanya, \"Bagaimana pendapat kalian jika di dalam sebuah kota terdapat hanya seorang yang beriman?\" Mereka menjawab, \"Tidak pula.\" Maka Nabi Ibrahim berkata kepada mereka, \"Sesungguhnya di dalam kota tersebut terdapat Nabi Luth.\" Mereka menjawab, \"Kami lebih mengetahui tentang orang-orang beriman yang terdapat di dalamnya",[["إِنَّ","Indeed"],["إِبْرَٰهِيمَ","Ibrahim"],["لَحَلِيمٌ","(was) certainly forbearing"],["أَوَّٰهٌۭ","imploring"],["مُّنِيبٌۭ","and oft-returning"]]],"1549":["Maka tatkala Nabi Ibrahim berkepanjangan di dalam bertanya jawab dengan mereka, lalu mereka mengatakan: (\"Hai Ibrahim! Tinggalkanlah soal jawab ini) perbantahan ini (sesungguhnya telah datang ketetapan Rabbmu) untuk membinasakan mereka (dan sesungguhnya mereka itu akan didatangi azab yang tidak dapat ditolak.\")",[["يَـٰٓإِبْرَٰهِيمُ","O Ibrahim"],["أَعْرِضْ","Turn away"],["عَنْ","from"],["هَـٰذَآ ۖ","this"],["إِنَّهُۥ","Indeed, it"],["قَدْ","certainly"],["جَآءَ","has come"],["أَمْرُ","(the) Command"],["رَبِّكَ ۖ","(of) your Lord"],["وَإِنَّهُمْ","and indeed, [they]"],["ءَاتِيهِمْ","(will) come (for) them"],["عَذَابٌ","a punishment"],["غَيْرُ","(which) cannot"],["مَرْدُودٍۢ","(be) repelled"]]],"1550":["(Dan tatkala datang utusan-utusan Kami itu kepada Luth, dia merasa susah) merasa repot dengan kedatangan mereka itu (dan merasa sempit dadanya karena kedatangan mereka) mereka datang dalam rupa yang tampan menyamar sebagai tamu-tamu. Hal inilah yang membuat Nabi Luth merasa takut terhadap kaumnya yang tentunya akan berlaku tidak senonoh terhadap tamu-tamunya ini (dan dia berkata, \"Ini adalah hari yang amat berat.\") hari yang sangat keras.",[["وَلَمَّا","And when"],["جَآءَتْ","came"],["رُسُلُنَا","Our messengers"],["لُوطًۭا","(to) Lut"],["سِىٓءَ","he was distressed"],["بِهِمْ","for them"],["وَضَاقَ","and felt straitened"],["بِهِمْ","for them"],["ذَرْعًۭا","(and) uneasy"],["وَقَالَ","and said"],["هَـٰذَا","This"],["يَوْمٌ","(is) a day"],["عَصِيبٌۭ","distressful"]]],"1551":["(Datanglah kepadanya kaumnya) ketika mereka mengetahui tentang tamu-tamunya itu (dengan bergegas-gegas) dengan segera (menuju kepadanya. Dan sejak dahulu) sebelum kedatangan para tetamu itu (mereka selalu mengerjakan perbuatan-perbuatan keji) yaitu menyetubuhi anus laki-laki. (Ia pernah berkata,) yakni Nabi Luth (\"Hai kaumku! Inilah putri-putriku) maka kawinilah mereka (mereka lebih suci bagi kalian, maka bertakwalah kepada Allah dan janganlah kalian membuat malu) mempermalukan diriku (terhadap tamuku ini) tamu-tamu ini. (Tidak adakah di antara kalian seorang yang berakal?\") yang memerintahkan kalian berbuat kebajikan dan melarang kalian melakukan perbuatan yang mungkar.",[["وَجَآءَهُۥ","And came (to) him"],["قَوْمُهُۥ","his people"],["يُهْرَعُونَ","rushing"],["إِلَيْهِ","to him"],["وَمِن","and before"],["قَبْلُ","and before"],["كَانُوا۟","they (had) been"],["يَعْمَلُونَ","doing"],["ٱلسَّيِّـَٔاتِ ۚ","the evil deeds"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["هَـٰٓؤُلَآءِ","These"],["بَنَاتِى","(are) my daughters"],["هُنَّ","they"],["أَطْهَرُ","(are) purer"],["لَكُمْ ۖ","for you"],["فَٱتَّقُوا۟","So fear"],["ٱللَّهَ","Allah"],["وَلَا","and (do) not"],["تُخْزُونِ","disgrace me"],["فِى","concerning"],["ضَيْفِىٓ ۖ","my guests"],["أَلَيْسَ","Is (there) not"],["مِنكُمْ","among you"],["رَجُلٌۭ","a man"],["رَّشِيدٌۭ","right-minded"]]],"1552":["(Mereka menjawab, \"Sesungguhnya kamu telah mengetahui bahwa kami tak mempunyai keinginan terhadap putri-putrimu itu) kami tidak membutuhkannya (dan sesungguhnya kamu tentu mengetahui apa yang sekiranya kami kehendaki.\") yaitu suka menyetubuhi anus laki-laki.",[["قَالُوا۟","They said"],["لَقَدْ","Verily"],["عَلِمْتَ","you know"],["مَا","(that) not"],["لَنَا","we have"],["فِى","concerning"],["بَنَاتِكَ","your daughters"],["مِنْ","any"],["حَقٍّۢ","right"],["وَإِنَّكَ","And indeed, you"],["لَتَعْلَمُ","surely know"],["مَا","what"],["نُرِيدُ","we want"]]],"1553":["(Luth berkata, \"Seandainya aku mempunyai kekuatan untuk menolak kalian) mempunyai kemampuan untuk menolak keinginan kalian (atau kalau aku dapat berlindung kepada keluarga yang kuat\") yakni keluarga yang mau menolongku, tentu aku akan menghajar kalian atas kekurangajaran kalian itu. Maka tatkala para malaikat itu melihat hal tersebut, lalu mereka mengatakan:",[["قَالَ","He said"],["لَوْ","If"],["أَنَّ","that"],["لِى","I had"],["بِكُمْ","over you"],["قُوَّةً","power"],["أَوْ","or"],["ءَاوِىٓ","I could take refuge"],["إِلَىٰ","in"],["رُكْنٍۢ","a support"],["شَدِيدٍۢ","strong"]]],"1554":["(Para utusan itu berkata, \"Hai Luth! Sesungguhnya kami adalah utusan-utusan Rabbmu, sekali-kali mereka tidak akan dapat mengganggu kamu) dengan berlaku jahat terhadap dirimu (sebab itu bawalah pergi keluarga dan pengikut-pengikut kamu di akhir) pada bagian yang terakhir dari (malam dan janganlah ada seorang pun di antara kalian yang tertinggal) supaya ia tidak melihat kengerian azab yang menimpa mereka (kecuali istrimu) dengan dibaca rafa`, yaitu imra-atuka, berkedudukan menjadi badal dari lafal ahadin. Menurut qiraat lain dibaca nashab, yaitu imra-ataka, berkedudukan menjadi istitsna dari lafal al-ahl. Artinya janganlah engkau membawa pergi dia. (Sesungguhnya dia akan ditimpa azab yang menimpa mereka) menurut suatu pendapat dikatakan bahwa Nabi Luth tidak membawa istrinya pergi. Akan tetapi menurut pendapat yang lain dikatakan bahwa Nabi Luth membawanya pergi. Hanya saja ia menoleh ke belakang seraya mengatakan, 'Aduh kaumku!' Lalu ia ditimpa oleh batu besar sehingga matilah dia.\" Nabi Luth bertanya kepada utusan tentang waktu pembinasaan kaumnya, maka para utusan itu berkata. (\"Sesungguhnya saat jatuhnya azab kepada mereka ialah di waktu subuh) Nabi Luth meminta, 'Aku minta supaya lebih disegerakan lagi.' Mereka menjawab ('Bukankah subuh itu sudah dekat?'\")",[["قَالُوا۟","They said"],["يَـٰلُوطُ","O Lut"],["إِنَّا","Indeed, we"],["رُسُلُ","(are) messengers"],["رَبِّكَ","(of) your Lord"],["لَن","never"],["يَصِلُوٓا۟","they will reach"],["إِلَيْكَ ۖ","you"],["فَأَسْرِ","So travel"],["بِأَهْلِكَ","with your family"],["بِقِطْعٍۢ","in a part"],["مِّنَ","of"],["ٱلَّيْلِ","the night"],["وَلَا","and (let) not"],["يَلْتَفِتْ","look back"],["مِنكُمْ","anyone of you"],["أَحَدٌ","anyone of you"],["إِلَّا","except"],["ٱمْرَأَتَكَ ۖ","your wife"],["إِنَّهُۥ","Indeed, it"],["مُصِيبُهَا","will strike her"],["مَآ","what"],["أَصَابَهُمْ ۚ","will strike them"],["إِنَّ","Indeed"],["مَوْعِدَهُمُ","their appointed time"],["ٱلصُّبْحُ ۚ","(is) morning"],["أَلَيْسَ","Is not"],["ٱلصُّبْحُ","the morning"],["بِقَرِيبٍۢ","near"]]],"1555":["(Maka tatkala datang perintah Kami) untuk membinasakan mereka (Kami jadikan bagian atas) dari negeri kaum Luth (ke bawah) artinya malaikat Jibril mengangkat negeri mereka ke atas kemudian menjatuhkannya ke bumi dalam keadaan terbalik (dan Kami hujani mereka dengan batu dari tanah yang terbakar) yaitu lumpur yang panas membara (dengan bertubi-tubi) secara terus-menerus.",[["فَلَمَّا","So when"],["جَآءَ","came"],["أَمْرُنَا","Our Command"],["جَعَلْنَا","We made"],["عَـٰلِيَهَا","its upside"],["سَافِلَهَا","its downside"],["وَأَمْطَرْنَا","and We rained"],["عَلَيْهَا","upon them"],["حِجَارَةًۭ","stones"],["مِّن","of"],["سِجِّيلٍۢ","baked clay"],["مَّنضُودٍۢ","(in) layers"]]],"1556":["(Yang diberi tanda) telah ditandai masing-masing tanah yang membara itu dengan nama orang yang dikenainya (oleh Rabbmu) menjadi zharaf bagi lafal mu`allamatan (dan hal itu) makna yang diisyaratkan di sini adalah azab yang berupa batu itu atau negeri mereka (dari orang-orang yang lalim) artinya penduduk Mekah (tidak jauh).",[["مُّسَوَّمَةً","Marked"],["عِندَ","from"],["رَبِّكَ ۖ","your Lord"],["وَمَا","And not"],["هِىَ","it"],["مِنَ","(is) from"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["بِبَعِيدٍۢ","far"]]],"1557":["(Dan) Kami utus (kepada penduduk Madyan saudara mereka Syuaib. Ia berkata, \"Hai kaumku! Sembahlah Allah) tauhidkanlah Dia (sekali-kali tiada Tuhan bagi kalian selain Dia. Dan janganlah kalian kurangi takaran dan timbangan, sesungguhnya aku melihat kalian dalam keadaan yang baik) kalian hidup dalam keadaan yang menyenangkan sehingga kalian tidak perlu melakukan pengurangan takaran dan timbangan (dan sesungguhnya aku) (khawatir terhadap kalian) jika kalian tidak mau beriman (akan azab hari yang membinasakan\") hari yang meliputi kalian dengan kebinasaan. Lafal yaum disifati dengan lafal muhith mengandung pengertian majaz, karena terjadinya azab itu pada hari tersebut.",[["۞ وَإِلَىٰ","And to"],["مَدْيَنَ","Madyan"],["أَخَاهُمْ","their brother"],["شُعَيْبًۭا ۚ","Shuaib"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["مَا","not"],["لَكُم","(is) for you"],["مِّنْ","any"],["إِلَـٰهٍ","god"],["غَيْرُهُۥ ۖ","other than Him"],["وَلَا","And (do) not"],["تَنقُصُوا۟","decrease"],["ٱلْمِكْيَالَ","(from) the measure"],["وَٱلْمِيزَانَ ۚ","and the scale"],["إِنِّىٓ","Indeed, I"],["أَرَىٰكُم","see you"],["بِخَيْرٍۢ","in prosperity"],["وَإِنِّىٓ","but indeed, I"],["أَخَافُ","fear"],["عَلَيْكُمْ","for you"],["عَذَابَ","punishment"],["يَوْمٍۢ","(of) a Day"],["مُّحِيطٍۢ","all-encompassing"]]],"1558":["(Dan Syuaib berkata, \"Hai kaumku!) (Cukupkanlah takaran dan timbungan) sempurnakanlah keduanya (dengan adil) secara tetap (dan janganlah kalian merugikan manusia terhadap hak-hak mereka) janganlah kalian mengurangi hak-hak mereka sedikit pun (dan janganlah kalian membuat kejahatan di muka bumi dengan membuat kerusakan) dengan melakukan pembunuhan dan kejahatan lainnya. Lafal ta'tsau berasal dari fi'il madhi `atsiya, artinya mengadakan kerusakan. Sedangkan lafal mufsidiina berkedudukan menjadi hal atau keterangan yang mengukuhkan makna amilnya yaitu ta'tsau.",[["وَيَـٰقَوْمِ","And O my people"],["أَوْفُوا۟","Give full"],["ٱلْمِكْيَالَ","measure"],["وَٱلْمِيزَانَ","and weight"],["بِٱلْقِسْطِ ۖ","in justice"],["وَلَا","and (do) not"],["تَبْخَسُوا۟","deprive"],["ٱلنَّاسَ","the people"],["أَشْيَآءَهُمْ","(of) their things"],["وَلَا","and (do) not"],["تَعْثَوْا۟","act wickedly"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["مُفْسِدِينَ","spreading corruption"]]],"1559":["(Sisa keuntungan dari Allah) yaitu rezeki yang masih tersisa bagi kalian sesudah kalian mencukupkan takaran dan timbangan (adalah lebih baik bagi kalian) daripada perbuatan mengurangi takaran dan timbangan (jika kalian orang-orang yang beriman. Dan aku bukanlah seorang penjaga atas diri kalian.\") aku bukanlah pengawas yang membalas kalian terhadap amal perbuatan kalian, akan tetapi sesungguhnya aku adalah orang yang diutus bagi kalian sebagai pembawa peringatan.",[["بَقِيَّتُ","(What) remains"],["ٱللَّهِ","(from) Allah"],["خَيْرٌۭ","(is) best"],["لَّكُمْ","for you"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ ۚ","believers"],["وَمَآ","And not"],["أَنَا۠","I am"],["عَلَيْكُم","over you"],["بِحَفِيظٍۢ","a guardian"]]],"1560":["(Mereka berkata) kepada Nabi Syuaib dengan nada mengejek (\"Hai Syuaib! Apakah salatmu menyuruhmu) membebankan kepadamu (agar kami meninggalkan apa yang disembah oleh bapak-bapak kami) yaitu berhala-berhala (atau) melarang kami (mencegah kami melakukan apa yang kami kehendaki tentang harta kami) maksudnya hal ini tidak benar sama sekali, tidak ada seorang pun yang menyeru kepada kebaikan. (Sesungguhnya kamu adalah orang yang sangat penyantun lagi berakal.\") mereka mengatakan demikian dengan nada mengejek dan mencemoohkan Nabi Syuaib.",[["قَالُوا۟","They said"],["يَـٰشُعَيْبُ","O Shuaib"],["أَصَلَوٰتُكَ","Does your prayer"],["تَأْمُرُكَ","command you"],["أَن","that"],["نَّتْرُكَ","we leave"],["مَا","what"],["يَعْبُدُ","worship"],["ءَابَآؤُنَآ","our forefathers"],["أَوْ","or"],["أَن","that"],["نَّفْعَلَ","we do"],["فِىٓ","concerning"],["أَمْوَٰلِنَا","our wealth"],["مَا","what"],["نَشَـٰٓؤُا۟ ۖ","we will"],["إِنَّكَ","Indeed you"],["لَأَنتَ","surely you"],["ٱلْحَلِيمُ","(are) the forbearing"],["ٱلرَّشِيدُ","the right-minded"]]],"1561":["(Syuaib berkata, \"Bagaimana pikiran kalian jika aku mempunyai bukti yang nyata dari Rabbku dan dianugerahi-Nya aku daripada-Nya rezeki yang baik) rezeki yang halal lalu apakah patut jika aku mencampurinya dengan barang yang haram hasil mengurangi takaran dan timbangan (Dan aku tidak berkehendak menyalahi kalian) melakukan (apa yang aku larang kalian daripadanya) kemudian aku mengerjakannya. (Aku tidak) aku tiada (bermaksud kecuali mendatangkan perbaikan) bagi kalian supaya menegakkan keadilan (selama aku masih berkesanggupan. Dan tidak ada taufik bagiku) berkemampuan untuk melakukan hal tersebut dan perkara ketaatan lainnya (melainkan dengan pertolongan Allah. Hanya kepada Allah aku bertawakal dan hanya kepada-Nyalah aku kembali.\") mengembalikan semua perkara.",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["أَرَءَيْتُمْ","Do you see"],["إِن","if"],["كُنتُ","I am"],["عَلَىٰ","on"],["بَيِّنَةٍۢ","a clear evidence"],["مِّن","from"],["رَّبِّى","my Lord"],["وَرَزَقَنِى","and He has provided me"],["مِنْهُ","from Himself"],["رِزْقًا","a good provision"],["حَسَنًۭا ۚ","a good provision"],["وَمَآ","And not"],["أُرِيدُ","I intend"],["أَنْ","that"],["أُخَالِفَكُمْ","I differ from you"],["إِلَىٰ","in"],["مَآ","what"],["أَنْهَىٰكُمْ","I forbid you"],["عَنْهُ ۚ","from it"],["إِنْ","Not"],["أُرِيدُ","I intend"],["إِلَّا","except"],["ٱلْإِصْلَـٰحَ","the reform"],["مَا","as much as I am able"],["ٱسْتَطَعْتُ ۚ","as much as I am able"],["وَمَا","And not"],["تَوْفِيقِىٓ","(is) my success"],["إِلَّا","except"],["بِٱللَّهِ ۚ","with Allah"],["عَلَيْهِ","Upon Him"],["تَوَكَّلْتُ","I trust"],["وَإِلَيْهِ","and to Him"],["أُنِيبُ","I turn"]]],"1562":["(\"Hai kaumku! Janganlah membuat kalian jahat) menyebabkan kalian melakukannya (adanya pertentangan dengan aku) pertentangan antara aku dan kalian. Lafal syiqaaqii menjadi fa'il atau subjek daripada fi'il yajrimannakum, dan lafal qaum yang terkandung di dalamnya berkedudukan menjadi maf'ul awwal atau objek pertama, sedangkan maf'ul yang kedua ialah (hingga kalian ditimpa azab seperti yang menimpa kaum Nuh atau kaum Hud atau kaum Saleh) ditimpa azab yang sama (sedangkan kaum Luth tidaklah) artinya tempat tinggal kaum Luth atau waktu mereka dibinasakan (jauh dari kalian) maka ambillah hal itu sebagai pelajaran buat kalian.",[["وَيَـٰقَوْمِ","And O my people"],["لَا","(Let) not cause you to sin"],["يَجْرِمَنَّكُمْ","(Let) not cause you to sin"],["شِقَاقِىٓ","my dissension"],["أَن","lest"],["يُصِيبَكُم","befalls you"],["مِّثْلُ","similar"],["مَآ","(to) what"],["أَصَابَ","befell"],["قَوْمَ","(the) people of Nuh"],["نُوحٍ","(the) people of Nuh"],["أَوْ","or"],["قَوْمَ","(the) people of Hud"],["هُودٍ","(the) people of Hud"],["أَوْ","or"],["قَوْمَ","people of Salih"],["صَـٰلِحٍۢ ۚ","people of Salih"],["وَمَا","And not"],["قَوْمُ","(are the) people of Lut"],["لُوطٍۢ","(are the) people of Lut"],["مِّنكُم","from you"],["بِبَعِيدٍۢ","far off"]]],"1563":["(Dan mohonlah ampun kepada Rabb kalian, kemudian bertobatlah kepada-Nya. Sesungguhnya Rabbku Maha Penyayang) terhadap orang-orang yang beriman (lagi Maha Pengasih.\") sangat mencintai orang-orang yang beriman.",[["وَٱسْتَغْفِرُوا۟","And ask forgiveness"],["رَبَّكُمْ","(of) your Lord"],["ثُمَّ","then"],["تُوبُوٓا۟","turn in repentance"],["إِلَيْهِ ۚ","to Him"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["رَحِيمٌۭ","(is) Most Merciful"],["وَدُودٌۭ","Most Loving"]]],"1564":["(Mereka berkata) dengan nada yang menunjukkan kurang perhatian mereka terhadap perkataan Nabi Syuaib (\"Hai Syuaib! Kami tidak mengerti) kurang memahami (banyak tentang apa yang kamu katakan itu dan sesungguhnya kami benar-benar melihat kamu seorang yang lemah di antara kami) maksudnya orang yang rendah (kalau tidaklah karena keluargamu) familimu (tentulah kami telah merajam kamu) dengan batu (sedangkan kamu pun bukanlah seorang yang berwibawa di sisi kami.\") bukan orang-orang tidak pantas untuk dihukum rajam; dan sesungguhnya hanya keluargamu sajalah orang-orang yang berwibawa itu.",[["قَالُوا۟","They said"],["يَـٰشُعَيْبُ","O Shuaib"],["مَا","Not"],["نَفْقَهُ","we understand"],["كَثِيرًۭا","much"],["مِّمَّا","of what"],["تَقُولُ","you say"],["وَإِنَّا","and indeed, we"],["لَنَرَىٰكَ","surely [we] see you"],["فِينَا","among us"],["ضَعِيفًۭا ۖ","weak"],["وَلَوْلَا","And if not"],["رَهْطُكَ","for your family"],["لَرَجَمْنَـٰكَ ۖ","surely we would have stoned you"],["وَمَآ","and you are not"],["أَنتَ","and you are not"],["عَلَيْنَا","against us"],["بِعَزِيزٍۢ","mighty"]]],"1565":["(Syuaib menjawab, \"Hai kaumku! Apakah keluargaku lebih terhormat menurut pandangan kalian daripada Allah) oleh sebab itu lalu kalian tidak mau membunuhku demi mereka dan kalian tidak mau membiarkan aku demi karena Allah (sedangkan kalian menjadikan Dia) yakni kalian menganggap Allah (sebagai sesuatu yang terbuang di belakang kalian) terasing di belakang kalian tanpa kalian hiraukan Dia. (Sesungguhnya Rabbku meliputi apa yang kalian kerjakan.\") Dia Maha Mengetahui kesemuanya; oleh karena itu kelak Dia akan membalas kalian.",[["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["أَرَهْطِىٓ","Is my family"],["أَعَزُّ","mightier"],["عَلَيْكُم","on you"],["مِّنَ","than"],["ٱللَّهِ","Allah"],["وَٱتَّخَذْتُمُوهُ","And you have taken Him"],["وَرَآءَكُمْ","behind your"],["ظِهْرِيًّا ۖ","backs"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["مُحِيطٌۭ","(is) All-Encompassing"]]],"1566":["(Dan dia berkata, \"Hai kaumku! Berbuatlah menurut kemampuan kalian) sesuai dengan keadaan kalian (sesungguhnya aku pun berbuat pula) sesuai dengan kedudukanku. (Kelak kalian akan mengetahui siapa) lafal man di sini adalah maushul yang berkedudukan menjadi maf'ul dari lafal ta'lamuuna (yang akan ditimpa azab yang menghinakannya dan siapa yang berdusta. Dan tunggulah) akibat daripada perbuatan kalian itu (sesungguhnya aku pun menunggu bersama kalian.\") ikut mengawasinya.",[["وَيَـٰقَوْمِ","And O my people"],["ٱعْمَلُوا۟","Work"],["عَلَىٰ","(according) to"],["مَكَانَتِكُمْ","your position"],["إِنِّى","indeed, I am"],["عَـٰمِلٌۭ ۖ","working"],["سَوْفَ","Soon"],["تَعْلَمُونَ","you will know"],["مَن","(on) whom"],["يَأْتِيهِ","will come"],["عَذَابٌۭ","a punishment"],["يُخْزِيهِ","(that will) disgrace him"],["وَمَنْ","and who"],["هُوَ","[he]"],["كَـٰذِبٌۭ ۖ","(is) a liar"],["وَٱرْتَقِبُوٓا۟","And watch"],["إِنِّى","indeed, I am"],["مَعَكُمْ","with you"],["رَقِيبٌۭ","a watcher"]]],"1567":["(Dan tatkala datang perintah Kami) yang memerintahkan supaya mereka dibinasakan (Kami selamatkan Syuaib dan orang-orang yang beriman bersama-sama dengan dia sebagai rahmat dari Kami, dan orang-orang yang lalim dibinasakan oleh suatu suara yang mengguntur) malaikat Jibril mengeluarkan suara yang mengguntur terhadap mereka (lalu jadilah mereka mati bergelimpangan di tempat tinggalnya) mereka mati dalam keadaan bersimpuh.",[["وَلَمَّا","And when"],["جَآءَ","came"],["أَمْرُنَا","Our Command"],["نَجَّيْنَا","We saved"],["شُعَيْبًۭا","Shuaib"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believed"],["مَعَهُۥ","with him"],["بِرَحْمَةٍۢ","by a Mercy"],["مِّنَّا","from Us"],["وَأَخَذَتِ","And seized"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["ٱلصَّيْحَةُ","the thunderous blast"],["فَأَصْبَحُوا۟","then they became"],["فِى","in"],["دِيَـٰرِهِمْ","their homes"],["جَـٰثِمِينَ","fallen prone"]]],"1568":["(Seolah-olah) mereka; lafal ka-an adalah bentuk takhfif daripada lafal ka-anna (belum pernah tinggal di tempat tinggalnya itu, di tempat mereka bermukim. Ingatlah, kebinasaanlah bagi penduduk Madyan sebagaimana kaum Tsamud telah binasa).",[["كَأَن","As if"],["لَّمْ","not"],["يَغْنَوْا۟","they (had) prospered"],["فِيهَآ ۗ","therein"],["أَلَا","So"],["بُعْدًۭا","away"],["لِّمَدْيَنَ","with Madyan"],["كَمَا","as"],["بَعِدَتْ","was taken away"],["ثَمُودُ","the Thamud"]]],"1569":["(Dan sesungguhnya Kami telah mengutus Musa dengan membawa tanda-tanda kekuasaan Kami dan mukjizat yang nyata) bukti yang jelas dan gamblang.",[["وَلَقَدْ","And certainly"],["أَرْسَلْنَا","We sent"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَا","with Our Signs"],["وَسُلْطَـٰنٍۢ","and an authority"],["مُّبِينٍ","clear"]]],"1570":["(Kepada Firaun dan pemimpin-pemimpin kaumnya, tetapi mereka mengikuti perintah Firaun, padahal perintah Firaun sekali-kali bukanlah perintah yang benar) perintah yang lurus.",[["إِلَىٰ","To"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","and his chiefs"],["فَٱتَّبَعُوٓا۟","but they followed"],["أَمْرَ","(the) command of Firaun"],["فِرْعَوْنَ ۖ","(the) command of Firaun"],["وَمَآ","and not"],["أَمْرُ","(the) command of Firaun"],["فِرْعَوْنَ","(the) command of Firaun"],["بِرَشِيدٍۢ","was right"]]],"1571":["(Ia berjalan di muka) berada paling depan (kaumnya di hari kiamat) sehingga para pengikutnya mengikutinya sebagaimana mereka mengikutinya sewaktu hidup di dunia (lalu memasukkan mereka) menjerumuskan mereka (ke dalam neraka. Neraka itu seburuk-buruk tempat yang didatangi.)",[["يَقْدُمُ","He will precede"],["قَوْمَهُۥ","his people"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["فَأَوْرَدَهُمُ","and lead them"],["ٱلنَّارَ ۖ","(into) the Fire"],["وَبِئْسَ","And wretched"],["ٱلْوِرْدُ","(is) the place"],["ٱلْمَوْرُودُ","to which (they are) led"]]],"1572":["(Dan mereka telah diikuti di dalam) dunia ini (oleh kutukan, dan begitu pula di hari kiamat) mereka dikutuk pula (seburuk-buruk pemberian) bantuan (adalah yang diberikan kepada mereka) kutukan yang diberikan kepada mereka.",[["وَأُتْبِعُوا۟","And they were followed"],["فِى","in"],["هَـٰذِهِۦ","this"],["لَعْنَةًۭ","(by) a curse"],["وَيَوْمَ","and (on the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) the Resurrection"],["بِئْسَ","Wretched"],["ٱلرِّفْدُ","(is) the gift"],["ٱلْمَرْفُودُ","which (will) be given"]]],"1573":["(Yang demikian itu) hal yang telah disebutkan tadi; lafal dzaalika berkedudukan menjadi mubtada sedangkan khabarnya ialah (adalah sebagian berita-berita negeri yang Kami ceritakan kepadamu) hai Muhammad (di antaranya) di antara negeri-negeri itu (ada yang masih kedapatan bekas-bekasnya) artinya penduduknya telah binasa tetapi bekas-bekasnya masih ada (dan) di antaranya ada pula (yang telah musnah) telah binasa berikut penduduknya, sehingga tidak ada bekasnya sama sekali. Perumpamaan mereka sama dengan tanaman yang dipanen dengan memakai sabit.",[["ذَٰلِكَ","That"],["مِنْ","(is) from"],["أَنۢبَآءِ","(the) news"],["ٱلْقُرَىٰ","(of) the cities"],["نَقُصُّهُۥ","(which) We relate"],["عَلَيْكَ ۖ","to you"],["مِنْهَا","of them"],["قَآئِمٌۭ","some are standing"],["وَحَصِيدٌۭ","and (some) mown"]]],"1574":["(Dan Kami tidak menganiaya mereka) dengan membinasakan mereka tanpa dosa (tetapi merekalah yang menganiaya dirinya sendiri) dengan melakukan perbuatan syirik (karena itu tiadalah bermanfaat) tidak ada gunanya (kepada diri mereka, sesembahan-sesembahan yang mereka seru) yang mereka sembah (selain Allah). Huruf min di sini zaidah atau tidak mengandung makna (sedikit pun, di waktu perintah Rabbmu datang) yaitu azab-Nya. (Dan sesembahan-sesembahan itu tidaklah menambah kepada mereka) penyembahan mereka terhadapnya itu tidak dapat memberikan kepada mereka (selain kerugian belaka) yaitu kebinasaan.",[["وَمَا","And not"],["ظَلَمْنَـٰهُمْ","We wronged them"],["وَلَـٰكِن","but"],["ظَلَمُوٓا۟","they wronged"],["أَنفُسَهُمْ ۖ","themselves"],["فَمَآ","So not"],["أَغْنَتْ","availed"],["عَنْهُمْ","them"],["ءَالِهَتُهُمُ","their gods"],["ٱلَّتِى","which"],["يَدْعُونَ","they invoked"],["مِن","other than Allah"],["دُونِ","other than Allah"],["ٱللَّهِ","other than Allah"],["مِن","any"],["شَىْءٍۢ","thing"],["لَّمَّا","when"],["جَآءَ","came"],["أَمْرُ","(the) command (of) your Lord"],["رَبِّكَ ۖ","(the) command (of) your Lord"],["وَمَا","And not"],["زَادُوهُمْ","they increased them"],["غَيْرَ","other than"],["تَتْبِيبٍۢ","ruin"]]],"1575":["(Dan begitulah) perumpamaan azab-Nya (azab Rabbmu apabila Dia mengazab penduduk negeri-negeri) yang dimaksud adalah penduduknya (yang berbuat lalim) dengan melakukan perbuatan-perbuatan dosa. Jelasnya tidak ada sesuatu pun yang dapat memberi manfaat kepada mereka bila azab Allah diturunkan kepada mereka. (Sesungguhnya azab-Nya itu adalah sangat pedih lagi keras) sehubungan dengan ayat ini Imam Bukhari dan Imam Muslim meriwayatkan sebuah hadis melalui Abu Musa Al-Asyari r.a. yang menceritakan bahwasanya Rasulullah saw. telah bersabda, \"Sesungguhnya Allah selalu mencatat semua perbuatan orang yang aniaya sehingga apabila Dia mengazabnya, maka ia tidak dapat luput daripada-Nya.\" Kemudian Rasulullah saw. membacakan firman-Nya, \"Dan begitulah azab Rabbmu..\" (Q.S. Hud 102)",[["وَكَذَٰلِكَ","And thus"],["أَخْذُ","(is) the seizure (of) your Lord"],["رَبِّكَ","(is) the seizure (of) your Lord"],["إِذَآ","when"],["أَخَذَ","He seizes"],["ٱلْقُرَىٰ","the cities"],["وَهِىَ","while they"],["ظَـٰلِمَةٌ ۚ","(are) doing wrong"],["إِنَّ","Indeed"],["أَخْذَهُۥٓ","His seizure"],["أَلِيمٌۭ","(is) painful"],["شَدِيدٌ","(and) severe"]]],"1576":["(Sesungguhnya pada yang demikian itu) pada kisah-kisah yang telah disebutkan tadi (benar-benar terdapat pelajaran) bahan pelajaran (bagi orang-orang yang takut kepada azab akhirat. Hari itu) yakni hari kiamat itu (adalah suatu hari yang dikumpulkan menghadap kepada-Nya) pada hari itu (semua manusia, dan hari itu adalah suatu hari yang disaksikan) artinya hari itu disaksikan oleh semua makhluk.",[["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَةًۭ","(is) surely a Sign"],["لِّمَنْ","for (those) who"],["خَافَ","fear"],["عَذَابَ","(the) punishment"],["ٱلْـَٔاخِرَةِ ۚ","(of) the Hereafter"],["ذَٰلِكَ","That"],["يَوْمٌۭ","(is) a Day"],["مَّجْمُوعٌۭ","(will) be gathered"],["لَّهُ","on it"],["ٱلنَّاسُ","the mankind"],["وَذَٰلِكَ","and that"],["يَوْمٌۭ","(is) a Day"],["مَّشْهُودٌۭ","witnessed"]]],"1577":["(Dan Kami tiadalah mengundur-undurkannya melainkan sampai waktu yang tertentu) waktu yang hanya diketahui oleh Allah.",[["وَمَا","And not"],["نُؤَخِّرُهُۥٓ","We delay it"],["إِلَّا","except"],["لِأَجَلٍۢ","for a term"],["مَّعْدُودٍۢ","limited"]]],"1578":["(Di kala datang hari itu) sudah tiba saatnya (tidak dapat berbicara) lafal takallama pada asalnya adalah tatakallama, kemudian salah satu huruf tanya dibuang sehingga jadilah ia takallama (seorang pun melainkan dengan izin-Nya) izin Allah swt. (maka di antara mereka) makhluk (ada yang celaka dan) yang lainnya (ada yang berbahagia) masing-masing telah dipastikan nasibnya di zaman azali.",[["يَوْمَ","(The) Day"],["يَأْتِ","(it) comes"],["لَا","not"],["تَكَلَّمُ","will speak"],["نَفْسٌ","a soul"],["إِلَّا","except"],["بِإِذْنِهِۦ ۚ","by His leave"],["فَمِنْهُمْ","Then among them"],["شَقِىٌّۭ","(will be the) wretched"],["وَسَعِيدٌۭ","and (the) glad"]]],"1579":["(Adapun orang-orang yang celaka) menurut pengetahuan Allah swt. (maka tempatnya di dalam neraka, di dalamnya mereka mengeluarkan jeritan) suara yang sangat keras (dan rintihan) suara yang lemah.",[["فَأَمَّا","As for"],["ٱلَّذِينَ","those who"],["شَقُوا۟","were wretched"],["فَفِى","then (they will be) in"],["ٱلنَّارِ","the Fire"],["لَهُمْ","For them"],["فِيهَا","therein"],["زَفِيرٌۭ","(is) sighing"],["وَشَهِيقٌ","and wailing"]]],"1580":["(Mereka kekal di dalamnya selama ada langit dan bumi) artinya selama keberadaan langit dan bumi di alam dunia (kecuali) melainkan (jika Rabbmu menghendaki yang lain) yaitu perpanjangan waktu yang melebihi umur langit dan bumi. Makna yang dimaksud adalah tidak terbatas; mereka kekal di dalamnya untuk selama-lamanya. (Sesungguhnya Rabbmu Maha Pelaksana terhadap apa yang Dia kehendaki.)",[["خَـٰلِدِينَ","(Will be) abiding"],["فِيهَا","therein"],["مَا","as long as remain"],["دَامَتِ","as long as remain"],["ٱلسَّمَـٰوَٰتُ","the heavens"],["وَٱلْأَرْضُ","and the earth"],["إِلَّا","except"],["مَا","what your Lord wills"],["شَآءَ","what your Lord wills"],["رَبُّكَ ۚ","what your Lord wills"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["فَعَّالٌۭ","(is) All-Accomplisher"],["لِّمَا","of what"],["يُرِيدُ","He intends"]]],"1581":["(Adapun orang-orang yang berbahagia) dapat dibaca sa`iduu atau su`iduu (maka tempatnya di dalam surga, mereka kekal di dalamnya selama ada langit dan bumi kecuali) melainkan (jika Rabbmu menghendaki) penafsirannya seperti apa yang telah dikemukakan pada ayat terdahulu yang hal ini ditunjukkan oleh firman selanjutnya, yaitu (sebagai karunia yang tiada putus-putusnya) tidak pernah terputus, dan penakwilan yang terdahulu itulah penakwilan yang paling kuat karena ia terlepas dari pengertian yang dipaksakan. Akhirnya hanya Allah jualah Yang Maha Mengetahui akan maksud-Nya.",[["۞ وَأَمَّا","And as for"],["ٱلَّذِينَ","those who"],["سُعِدُوا۟","were glad"],["فَفِى","then (they will be) in"],["ٱلْجَنَّةِ","Paradise"],["خَـٰلِدِينَ","(will be) abiding"],["فِيهَا","therein"],["مَا","as long as remains"],["دَامَتِ","as long as remains"],["ٱلسَّمَـٰوَٰتُ","the heavens"],["وَٱلْأَرْضُ","and the earth"],["إِلَّا","except"],["مَا","what your Lord wills "],["شَآءَ","what your Lord wills "],["رَبُّكَ ۖ","what your Lord wills "],["عَطَآءً","a bestowal"],["غَيْرَ","not"],["مَجْذُوذٍۢ","interrupted"]]],"1582":["(Maka janganlah kamu) hai Muhammad (berada dalam keraguan) menaruh syak (tentang apa yang disembah oleh mereka) yaitu berhala-berhala sesembahan mereka karena sesungguhnya Kami akan mengazab mereka sebagaimana Kami mengazab orang-orang sebelum mereka yang melakukan perbuatan yang sama. Ayat ini dimaksud sebagai penghibur hati Nabi saw. (Mereka tidak menyembah melainkan sebagaimana nenek moyang mereka menyembah) artinya sama dengan penyembahan mereka (dahulu) dan sungguh dahulu Kami telah mengazab mereka. (Dan sesungguhnya Kami pasti akan menunaikan terhadap mereka) sama dengan apa yang telah Kami tunaikan kepada nenek moyang mereka (bagian mereka) pembalasan azab mereka (dengan tidak dikurangi sedikit pun) artinya secukup-cukupnya.",[["فَلَا","So (do) not"],["تَكُ","be"],["فِى","in"],["مِرْيَةٍۢ","doubt"],["مِّمَّا","as to what"],["يَعْبُدُ","worship"],["هَـٰٓؤُلَآءِ ۚ","these (polytheists)"],["مَا","Not"],["يَعْبُدُونَ","they worship"],["إِلَّا","except"],["كَمَا","as what"],["يَعْبُدُ","worshipped"],["ءَابَآؤُهُم","their forefathers"],["مِّن","before"],["قَبْلُ ۚ","before"],["وَإِنَّا","And indeed, We"],["لَمُوَفُّوهُمْ","will surely pay them in full"],["نَصِيبَهُمْ","their share"],["غَيْرَ","without"],["مَنقُوصٍۢ","being diminished"]]],"1583":["(Dan sesungguhnya Kami telah memberikan Kitab kepada Musa) yaitu kitab Taurat (lalu diperselisihkan tentang Kitab itu) ada yang membenarkan dan ada yang mendustakan, sama halnya dengan nasib yang menimpa Alquran (Dan seandainya tidak ada ketetapan yang terdahulu dari Rabbmu) dengan ditangguhkannya penghisaban dan pembalasan terhadap semua makhluk hingga hari kiamat nanti (niscaya telah ditetapkan peradilan di antara mereka) di dunia tentang apa yang mereka perselisihkan mengenai masalah Kitab itu. (Dan sesungguhnya mereka) yaitu orang-orang yang mendustakannya (dalam keraguan yang menggelisahkan terhadap Alquran) mereka ragu terhadapnya.",[["وَلَقَدْ","And verily"],["ءَاتَيْنَا","We gave"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","the Book"],["فَٱخْتُلِفَ","but differences arose"],["فِيهِ ۚ","therein"],["وَلَوْلَا","And if not"],["كَلِمَةٌۭ","(for) a Word"],["سَبَقَتْ","(that) preceded"],["مِن","from"],["رَّبِّكَ","your Lord"],["لَقُضِىَ","surely would have been judged"],["بَيْنَهُمْ ۚ","between them"],["وَإِنَّهُمْ","And indeed, they"],["لَفِى","surely (are) in"],["شَكٍّۢ","doubt"],["مِّنْهُ","concerning it"],["مُرِيبٍۢ","suspicious"]]],"1584":["(Dan sesungguhnya) dapat dibaca wain dan wainna (kepada masing-masing) artinya kepada setiap makhluk (pasti) huruf maa adalah zaidah, sedangkan huruf lam adalah mauthiah atau pendahuluan bagi qasam atau sumpah, atau lam fariqah. Menurut qiraat yang lain lamaa dibaca tasydid sehingga menjadi lammaa yang maknanya sama dengan illaa sedangkan huruf in sebelumnya bermakna nafi (Rabbmu akan menyempurnakan dengan cukup amal perbuatan mereka) yakni pembalasannya. (Sesungguhnya Dia Maha Mengetahui apa yang mereka kerjakan) Dia Maha Mengetahui apa yang tersembunyi dan yang terlahirkan daripadanya.",[["وَإِنَّ","And indeed"],["كُلًّۭا","to each [when]"],["لَّمَّا","to each [when]"],["لَيُوَفِّيَنَّهُمْ","surely will pay them in full"],["رَبُّكَ","your Lord"],["أَعْمَـٰلَهُمْ ۚ","their deeds"],["إِنَّهُۥ","Indeed, He"],["بِمَا","of what"],["يَعْمَلُونَ","they do"],["خَبِيرٌۭ","(is) All-Aware"]]],"1585":["(Maka tetaplah kamu pada jalan yang benar) yaitu mengamalkan perintah Rabbmu dan menyembah kepada-Nya (sebagaimana diperintahkan kepadamu dan) juga tetaplah pada jalan yang benar (orang yang telah bertobat) yaitu orang yang telah beriman (beserta kamu dan janganlah kalian melampuai batas) melanggar batasan-batasan Allah. (Sesungguhnya Dia Maha Melihat apa yang kalian kerjakan) oleh sebab itu Dia membalas kalian.",[["فَٱسْتَقِمْ","So stand firm"],["كَمَآ","as"],["أُمِرْتَ","you are commanded"],["وَمَن","and (those) who"],["تَابَ","turn (in repentance)"],["مَعَكَ","with you"],["وَلَا","and (do) not"],["تَطْغَوْا۟ ۚ","transgress"],["إِنَّهُۥ","Indeed, He"],["بِمَا","of what"],["تَعْمَلُونَ","you do"],["بَصِيرٌۭ","(is) All-Seer"]]],"1586":["(Dan janganlah kalian cenderung) condong hati (kepada orang-orang yang lalim) dengan menyukai mereka atau berbasa-basi terhadap mereka atau menyenangi perbuatan mereka (yang menyebabkan kalian disentuh) kalian terkena (api neraka dan sekali-kali kalian tiada mempunyai selain daripada Allah) selain-Nya (seorang penolong pun) yang dapat memelihara diri kalian dari azab-Nya. Huruf min di sini zaidah (kemudian kalian tidak akan diberi pertolongan) sehingga kalian tidak dapat selamat dari azab-Nya.",[["وَلَا","And (do) not"],["تَرْكَنُوٓا۟","incline"],["إِلَى","to"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","do wrong"],["فَتَمَسَّكُمُ","lest touches you"],["ٱلنَّارُ","the Fire"],["وَمَا","and not"],["لَكُم","(is) for you"],["مِّن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["مِنْ","any"],["أَوْلِيَآءَ","protectors"],["ثُمَّ","then"],["لَا","not"],["تُنصَرُونَ","you will be helped"]]],"1587":["(Dan dirikanlah salat itu pada kedua tepi siang) yaitu di waktu pagi dan sore; yang dimaksud adalah salat subuh, zuhur dan asar (dan pada bagian permulaan) lafal zulafan adalah bentuk jamak dari kata tunggal zulfatan, artinya beberapa bagian (dari malam hari) yaitu salat isyak dan magrib. (Sesungguhnya perbuatan-perbuatan yang baik itu) seperti menjalankan salat lima waktu (menghapuskan perbuatan-perbuatan yang buruk) yakni dosa-dosa yang kecil. Ayat ini diturunkan berkenaan dengan seorang sahabat yang mencium perempuan bukan muhrimnya. Kemudian sahabat itu menceritakannya kepada Nabi saw. Maka Nabi saw. bersabda sampai dengan perkataannya berikut ini, \"... hal ini berlaku bagi umatku seluruhnya.\" Hadis ini diriwayatkan oleh Imam Bukhari dan Imam Muslim. (Itulah peringatan bagi orang-orang yang ingat) sebagai pelajaran bagi orang-orang yang mau mengambil pelajaran.",[["وَأَقِمِ","And establish"],["ٱلصَّلَوٰةَ","the prayer"],["طَرَفَىِ","(at the) two ends"],["ٱلنَّهَارِ","(of) the day"],["وَزُلَفًۭا","and (at) the approach"],["مِّنَ","of"],["ٱلَّيْلِ ۚ","the night"],["إِنَّ","Indeed"],["ٱلْحَسَنَـٰتِ","the good deeds"],["يُذْهِبْنَ","remove"],["ٱلسَّيِّـَٔاتِ ۚ","the evil deeds"],["ذَٰلِكَ","That"],["ذِكْرَىٰ","(is) a reminder"],["لِلذَّٰكِرِينَ","for those who remember"]]],"1588":["(Dan bersabarlah) hai Muhammad, di dalam menghadapi perlakuan kaummu yang menyakitkan itu; atau bersabarlah kamu di dalam menjalankan salat (karena sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat kebaikan) bersabar di dalam menjalankan ketaatan.",[["وَٱصْبِرْ","And be patient"],["فَإِنَّ","for indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يُضِيعُ","let go waste"],["أَجْرَ","(the) reward"],["ٱلْمُحْسِنِينَ","(of) the good-doers"]]],"1589":["(Maka mengapa tidak ada) mengapa tidak (dari umat-umat) dari bangsa-bangsa terdahulu (sebelum kamu orang-orang yang mempunyai keutamaan) orang-orang yang teguh dalam beragama dan memiliki keutamaan (yang melarang daripada mengerjakan kerusakan di muka bumi) makna yang dimaksud adalah meniadakan, artinya hal tersebut jelas tidak akan terjadi di kalangan mereka (kecuali) hanya (sebagian kecil di antara orang-orang yang telah Kami selamatkan di antara mereka) yang melakukan nahi mungkar sehingga selamatlah mereka. Huruf min di sini mengandung makna bayan atau penjelasan (dan orang-orang yang lalim hanya mementingkan) mereka tidak mau melakukan nahi mungkar dan selalu senang dengan perbuatan kerusakan (kenikmatan yang mewah yang ada pada mereka) mereka hanya bersenang-senang saja (dan mereka adalah orang-orang yang berdosa).",[["فَلَوْلَا","So why not"],["كَانَ","had been"],["مِنَ","of"],["ٱلْقُرُونِ","the generations"],["مِن","before you"],["قَبْلِكُمْ","before you"],["أُو۟لُوا۟","those possessing a remnant"],["بَقِيَّةٍۢ","those possessing a remnant"],["يَنْهَوْنَ","forbidding"],["عَنِ","from"],["ٱلْفَسَادِ","the corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["إِلَّا","except"],["قَلِيلًۭا","a few"],["مِّمَّنْ","of those"],["أَنجَيْنَا","We saved"],["مِنْهُمْ ۗ","among them"],["وَٱتَّبَعَ","But followed"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","did wrong"],["مَآ","what"],["أُتْرِفُوا۟","luxury they were given"],["فِيهِ","therein"],["وَكَانُوا۟","and they were"],["مُجْرِمِينَ","criminals"]]],"1590":["(Dan Rabbmu sekali-kali tidak akan membinasakan negeri-negeri secara lalim) dengan sesuka-Nya terhadap negeri-negeri tersebut (sedangkan penduduknya orang-orang yang berbuat kebaikan) orang-orang yang beriman.",[["وَمَا","And not"],["كَانَ","would"],["رَبُّكَ","your Lord"],["لِيُهْلِكَ","destroy"],["ٱلْقُرَىٰ","the cities"],["بِظُلْمٍۢ","unjustly"],["وَأَهْلُهَا","while its people"],["مُصْلِحُونَ","(were) reformers"]]],"1591":["(Jikalau Rabbmu menghendaki, tentu Dia menjadikan manusia umat yang satu) pemeluk agama yang satu (tetapi mereka senantiasa berselisih pendapat) dalam masalah agama.",[["وَلَوْ","And if"],["شَآءَ","your Lord (had) willed"],["رَبُّكَ","your Lord (had) willed"],["لَجَعَلَ","surely He (could) have made"],["ٱلنَّاسَ","the mankind"],["أُمَّةًۭ","one community"],["وَٰحِدَةًۭ ۖ","one community"],["وَلَا","but not"],["يَزَالُونَ","they will cease"],["مُخْتَلِفِينَ","to differ"]]],"1592":["(Kecuali orang-orang yang diberi rahmat oleh Rabbmu) artinya Allah telah menghendaki kebaikan bagi mereka sehingga mereka tidak berselisih pendapat tentangnya. (Dan untuk itulah Allah menciptakan mereka) sebagian di antara mereka ada yang suka berselisih dan sebagian yang lain ada yang diberi rahmat oleh-Nya sehingga mereka tidak berselisih mengenai agama. (Kalimat Rabbmu telah diputuskan) yaitu (sesungguhnya Aku akan memenuhi Jahanam dengan jin dan manusia semuanya.)",[["إِلَّا","Except"],["مَن","(on) whom"],["رَّحِمَ","your Lord has bestowed Mercy"],["رَبُّكَ ۚ","your Lord has bestowed Mercy"],["وَلِذَٰلِكَ","and for that"],["خَلَقَهُمْ ۗ","He created them"],["وَتَمَّتْ","And will be fulfilled"],["كَلِمَةُ","(the) Word of your Lord"],["رَبِّكَ","(the) Word of your Lord"],["لَأَمْلَأَنَّ","Surely I will fill"],["جَهَنَّمَ","Hell"],["مِنَ","with"],["ٱلْجِنَّةِ","the Jinn"],["وَٱلنَّاسِ","and the men"],["أَجْمَعِينَ","all together"]]],"1593":["(Dan setiap) lafal kullan ini dinashabkan dengan alamat naqsh sedangkan tanwinnya merupakan pergantian dari mudhaf ilaih, artinya semua kisah rasul-rasul yang diperlukan (Kami ceritakan kepadamu, yaitu kisah-kisah para rasul) lafal maa di sini menjadi badal daripada lafal kullan (yang dengannya Kami teguhkan) Kami tenangkan (hatimu) kalbumu (dan dalam surah ini telah datang kepadamu kebenaran) yang dimaksud adalah kisah-kisah para rasul ini atau ayat-ayat ini (serta pengajaran dan peringatan bagi orang-orang yang beriman) orang-orang yang beriman disebutkan di sini secara khusus, mengingat hanya merekalah yang dapat memanfaatkan adanya kisah-kisah atau ayat-ayat ini untuk mempertebal keimanan mereka, berbeda dengan orang-orang kafir.",[["وَكُلًّۭا","And each"],["نَّقُصُّ","We relate"],["عَلَيْكَ","to you"],["مِنْ","of"],["أَنۢبَآءِ","(the) news"],["ٱلرُّسُلِ","(of) the Messengers"],["مَا","(for) that"],["نُثَبِّتُ","We may make firm"],["بِهِۦ","with it"],["فُؤَادَكَ ۚ","your heart"],["وَجَآءَكَ","And has come to you"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلْحَقُّ","the truth"],["وَمَوْعِظَةٌۭ","and an admonition"],["وَذِكْرَىٰ","and a reminder"],["لِلْمُؤْمِنِينَ","for the believers"]]],"1594":["(Dan katakanlah kepada orang-orang yang tidak beriman, \"Berbuatlah menurut kemampuan kalian) sesuai dengan keadaan dan kondisi kalian (sesungguhnya Kami pun berbuat pula.\") sesuai dengan keadaan Kami; ungkapan ini dimaksud sebagai ancaman buat orang-orang yang tidak beriman.",[["وَقُل","And say"],["لِّلَّذِينَ","to those who"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"],["ٱعْمَلُوا۟","Work"],["عَلَىٰ","(according) to"],["مَكَانَتِكُمْ","your position"],["إِنَّا","indeed, we"],["عَـٰمِلُونَ","(are also) working"]]],"1595":["(\"Dan tunggulah) akibat perbuatan kalian (sesungguhnya kami pun menunggu pula.\") hal tersebut.",[["وَٱنتَظِرُوٓا۟","And wait"],["إِنَّا","indeed, we"],["مُنتَظِرُونَ","(are) ones who wait"]]],"1596":["(Dan kepunyaan Allahlah apa yang gaib di langit dan di bumi) artinya Allah mengetahui semua yang samar atau yang gaib di dalam keduanya (dan kepada-Nyalah dikembalikan) jika dibaca yarji'u artinya sama dengan lafal ya'uudu yaitu kembali. Jika dibaca yurja'u maka artinya sama dengan lafal yuraddu yaitu dikembalikan (urusan-urusan semuanya) oleh sebab itu Dia menghukum orang-orang yang durhaka terhadap-Nya (maka sembahlah Dia) artinya esakanlah Dia (dan bertawakallah kepada-Nya) artinya percayalah kepada-Nya karena sesungguhnya Dialah yang mencukupimu. (Dan sekali-kali Rabbmu tidak lalai dari apa yang mereka kerjakan) sesungguhnya Dia sengaja menangguhkan mereka hanya sampai pada saatnya nanti. Menurut suatu qiraat lafal ya'maluuna dibaca ta`maluuna, artinya yang kalian kerjakan.",[["وَلِلَّهِ","And for Allah"],["غَيْبُ","(is the) unseen"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَإِلَيْهِ","and to Him"],["يُرْجَعُ","will be returned"],["ٱلْأَمْرُ","the matter"],["كُلُّهُۥ","all (of) it"],["فَٱعْبُدْهُ","so worship Him"],["وَتَوَكَّلْ","and put your trust"],["عَلَيْهِ ۚ","upon Him"],["وَمَا","And your Lord is not"],["رَبُّكَ","And your Lord is not"],["بِغَـٰفِلٍ","unaware"],["عَمَّا","of what"],["تَعْمَلُونَ","you do"]]],"1597":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya (ini) ayat-ayat ini (adalah ayat-ayat Kitab) yakni Alquran; idhafat di sini mengandung makna min, artinya bagian daripada Alquran (yang jelas) yang membedakan perkara hak daripada perkara yang batil.",[["الٓر ۚ","Alif Laam Ra"],["تِلْكَ","These"],["ءَايَـٰتُ","(are the) Verses"],["ٱلْكِتَـٰبِ","(of) the Book"],["ٱلْمُبِينِ","[the] clear"]]],"1598":["(Sesungguhnya Kami menurunkannya berupa Alquran dengan berbahasa Arab) dengan memakai bahasa Arab (agar kalian) hai penduduk Mekah (memahaminya) memahami makna-maknanya.",[["إِنَّآ","Indeed, We"],["أَنزَلْنَـٰهُ","We have sent it down"],["قُرْءَٰنًا","(as) a Quran in Arabic"],["عَرَبِيًّۭا","(as) a Quran in Arabic"],["لَّعَلَّكُمْ","so that you may"],["تَعْقِلُونَ","understand"]]],"1599":["(Kami menceritakan kepadamu kisah yang paling baik dengan mewahyukan) melalui apa yang Kami wahyukan (Alquran ini kepadamu dan sesungguhnya) lafal in merupakan takhfif daripada lafal inna (kamu sebelumnya adalah termasuk orang-orang yang belum mengetahui).",[["نَحْنُ","We"],["نَقُصُّ","relate"],["عَلَيْكَ","to you"],["أَحْسَنَ","the best"],["ٱلْقَصَصِ","of the narrations"],["بِمَآ","in what"],["أَوْحَيْنَآ","We have revealed"],["إِلَيْكَ","to you"],["هَـٰذَا","(of) this"],["ٱلْقُرْءَانَ","the Quran"],["وَإِن","although"],["كُنتَ","you were"],["مِن","before it"],["قَبْلِهِۦ","before it"],["لَمِنَ","surely among"],["ٱلْغَـٰفِلِينَ","the unaware"]]],"1600":["Ingatlah (Ketika Yusuf berkata kepada ayahnya) Nabi Yakub (\"Wahai ayahku!) dibaca kasrah, yaitu abati untuk menunjukkan adanya ya idhafat yang tidak disebutkan. Sedangkan bila dibaca fatah, maka menunjukkan adanya huruf alif yang tidak disebutkan, yaitu abata, kemudian alif ditukar dengan ya (Sesungguhnya aku telah melihat) di dalam tidurku, yakni bermimpi (sebelas buah bintang dan matahari serta bulan, kulihat semuanya) lafal ra-aytuhum berkedudukan menjadi taukid atau pengukuh dari lafal ra-aytu di muka tadi (sujud kepadaku.\") lafal saajidiina adalah bentuk jamak, yang alamat i'rabnya memakai ya dan nun karena menggambarkan keadaan sujud, hal ini merupakan ciri khas daripada makhluk yang berakal.",[["إِذْ","When"],["قَالَ","said"],["يُوسُفُ","Yusuf"],["لِأَبِيهِ","to his father"],["يَـٰٓأَبَتِ","O my father"],["إِنِّى","Indeed, I"],["رَأَيْتُ","I saw"],["أَحَدَ","eleven"],["عَشَرَ","eleven"],["كَوْكَبًۭا","stars"],["وَٱلشَّمْسَ","and the sun"],["وَٱلْقَمَرَ","and the moon"],["رَأَيْتُهُمْ","I saw them"],["لِى","to me"],["سَـٰجِدِينَ","prostrating"]]],"1601":["(Ayahnya berkata, \"Hai anakku! Janganlah kamu ceritakan mimpimu itu kepada saudara-audaramu, maka mereka membuat makar kepadamu) maksudnya mereka pasti akan membuat tipu muslihat guna membinasakanmu, karena terdorong oleh rasa dengki mereka kepadamu. Tentu mereka menakwilkan impianmu itu, bahwa bintang-bintang itu adalah mereka sendiri dan matahari itu adalah ibumu, sedangkan bulan adalah ayahmu. (Sesungguhnya setan itu adalah musuh yang nyata bagi manusia.\") jelas permusuhannya.",[["قَالَ","He said"],["يَـٰبُنَىَّ","O my son"],["لَا","(Do) not"],["تَقْصُصْ","relate"],["رُءْيَاكَ","your vision"],["عَلَىٰٓ","to"],["إِخْوَتِكَ","your brothers"],["فَيَكِيدُوا۟","lest they plan"],["لَكَ","against you"],["كَيْدًا ۖ","a plot"],["إِنَّ","Indeed"],["ٱلشَّيْطَـٰنَ","the Shaitaan"],["لِلْإِنسَـٰنِ","(is) to man"],["عَدُوٌّۭ","an enemy"],["مُّبِينٌۭ","open"]]],"1602":["(Dan demikianlah) seperti apa yang kamu lihat dalam mimpimu itu (telah memilih kamu) telah mengangkatmu (Rabbmu dan diajarkan-Nya kepadamu sebagian dari takwil-takwil mimpi) makna mimpi (dan disempurnakan-Nya kepadamu nikmat-Nya) yaitu kenabian (dan kepada keluarga Yakub) yakni anak-anaknya (sebagaimana Dia telah menyempurnakan nikmat-Nya) yaitu nikmat kenabian (kepada kedua orang tuamu sebelum itu, yaitu Ibrahim dan Ishak. Sesungguhnya Rabbmu Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam memperlakukan mereka.",[["وَكَذَٰلِكَ","And thus"],["يَجْتَبِيكَ","will choose you"],["رَبُّكَ","your Lord"],["وَيُعَلِّمُكَ","and will teach you"],["مِن","of"],["تَأْوِيلِ","(the) interpretation"],["ٱلْأَحَادِيثِ","(of) the narratives"],["وَيُتِمُّ","and complete"],["نِعْمَتَهُۥ","His Favor"],["عَلَيْكَ","on you"],["وَعَلَىٰٓ","and on"],["ءَالِ","(the) family"],["يَعْقُوبَ","(of) Yaqub"],["كَمَآ","as"],["أَتَمَّهَا","He completed it"],["عَلَىٰٓ","on"],["أَبَوَيْكَ","your two forefathers"],["مِن","before "],["قَبْلُ","before "],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ ۚ","and Isaac"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"1603":["(Sesungguhnya telah ada pada) kisah (Yusuf dan saudara-saudaranya) jumlah mereka ada sebelas orang (tanda-tanda) bahan-bahan pelajaran (bagi orang-orang yang bertanya).",[["۞ لَّقَدْ","Certainly"],["كَانَ","were"],["فِى","in"],["يُوسُفَ","Yusuf"],["وَإِخْوَتِهِۦٓ","and his brothers"],["ءَايَـٰتٌۭ","signs"],["لِّلسَّآئِلِينَ","for those who ask"]]],"1604":["Ingatlah (ketika mereka berkata) yaitu sebagian saudara-saudara Nabi Yusuf kepada sebagian yang lain (\"Sesungguhnya Yusuf) lafal Yusuf berkedudukan menjadi mubtada (dan saudaranya) yang sekandung yaitu Bunyamin (lebih dicintai) menjadi khabar dari lafal Yusuf tadi (oleh ayah kita daripada kita sendiri, padahal kita ini adalah satu golongan) kelompok yang kuat. (Sesungguhnya ayah kita adalah dalam kesesatan) kekeliruan (yang nyata) kekeliruan yang jelas dikarenakan ia lebih menyayangi Yusuf dan saudara sekandungnya daripada kita.",[["إِذْ","When"],["قَالُوا۟","they said"],["لَيُوسُفُ","Surely Yusuf"],["وَأَخُوهُ","and his brother"],["أَحَبُّ","(are) more beloved"],["إِلَىٰٓ","to"],["أَبِينَا","our father"],["مِنَّا","than we"],["وَنَحْنُ","while we"],["عُصْبَةٌ","(are) a group"],["إِنَّ","Indeed"],["أَبَانَا","our father"],["لَفِى","(is) surely in"],["ضَلَـٰلٍۢ","an error"],["مُّبِينٍ","clear"]]],"1605":["(Bunuhlah Yusuf atau buanglah dia ke suatu daerah) ke tempat yang jauh dan belum dikenal (supaya perhatian ayah kalian tertumpah kepada kalian) sehingga beliau hanya memperhatikan kalian dan tidak kepada yang lainnya (dan sesudah itu hendaklah kalian) sesudah membunuh Yusuf atau membuangnya (menjadi orang-orang yang baik.\") dengan jalan bertobat.",[["ٱقْتُلُوا۟","Kill"],["يُوسُفَ","Yusuf"],["أَوِ","or"],["ٱطْرَحُوهُ","cast him"],["أَرْضًۭا","(to) a land"],["يَخْلُ","so will be free"],["لَكُمْ","for you"],["وَجْهُ","(the) face"],["أَبِيكُمْ","(of) your father"],["وَتَكُونُوا۟","and you will be"],["مِنۢ","after that"],["بَعْدِهِۦ","after that"],["قَوْمًۭا","a people"],["صَـٰلِحِينَ","righteous"]]],"1606":["(Seorang di antara mereka berkata,) yaitu Yahudza (\"Janganlah kalian bunuh Yusuf, tetapi lemparkanlah dia) masukkanlah dia (ke dasar sumur) yang gelap sekali. Menurut qiraat lafal al-jub dibaca dalam bentuk jamak (supaya dia dipungut oleh beberapa orang musafir) orang-orang yang sedang melakukan perjalanan (jika kalian hendak berbuat.\") apa yang kalian kehendaki, yaitu ingin memisahkan antara Yusuf dan ayahnya, maka cukuplah dengan cara tersebut.",[["قَالَ","Said"],["قَآئِلٌۭ","a speaker"],["مِّنْهُمْ","among them"],["لَا","(Do) not"],["تَقْتُلُوا۟","kill"],["يُوسُفَ","Yusuf"],["وَأَلْقُوهُ","but throw him"],["فِى","in"],["غَيَـٰبَتِ","the bottom"],["ٱلْجُبِّ","(of) the well"],["يَلْتَقِطْهُ","will pick him"],["بَعْضُ","some"],["ٱلسَّيَّارَةِ","[the] caravan"],["إِن","if"],["كُنتُمْ","you are"],["فَـٰعِلِينَ","doing"]]],"1607":["(Mereka berkata, \"Wahai ayah kami! Apa sebabnya engkau tidak mempercayai kami terhadap Yusuf, padahal sesungguhnya kami adalah orang-orang yang menginginkan kebaikan baginya.\") orang-orang yang bersedia mengurusi semua kepentingan-kepentingannya.",[["قَالُوا۟","They said"],["يَـٰٓأَبَانَا","O our father"],["مَا","Why"],["لَكَ","(do) you"],["لَا","not"],["تَأْمَ۫نَّا","trust us"],["عَلَىٰ","with"],["يُوسُفَ","Yusuf"],["وَإِنَّا","while indeed, we"],["لَهُۥ","(are) for him"],["لَنَـٰصِحُونَ","surely well-wishers"]]],"1608":["(\"Biarkanlah dia pergi bersama kami besok pagi) ke padang sahara (agar dia dapat bersenang-senang dan bermain-main) dapat dibaca yarta' dan yal'ab, atau narta' dan nal`ab; artinya supaya dia atau kami dapat semangat yang baru dan pikiran yang segar (dan sesungguhnya kami pasti menjaganya\").",[["أَرْسِلْهُ","Send him"],["مَعَنَا","with us"],["غَدًۭا","tomorrow"],["يَرْتَعْ","(to) enjoy"],["وَيَلْعَبْ","and play"],["وَإِنَّا","And indeed, we"],["لَهُۥ","for him"],["لَحَـٰفِظُونَ","(will) surely (be) guardians"]]],"1609":["(Berkata Yakub, \"Sesungguhnya amat menyedihkan aku kepergian kalian) bila kalian pergi (bersama Yusuf) karena merasa berat berpisah dengannya (dan aku khawatir kalau-kalau dia dimakan serigala) makna yang dimaksud adalah jenis, yaitu mencakup semua binatang buas. Tersebutlah bahwa daerah tempat tinggal mereka terkenal banyak hewan buasnya (sedangkan kalian lengah daripadanya.\") lalai daripadanya.",[["قَالَ","He said"],["إِنِّى","Indeed, [I]"],["لَيَحْزُنُنِىٓ","it surely saddens me"],["أَن","that"],["تَذْهَبُوا۟","you should take him"],["بِهِۦ","you should take him"],["وَأَخَافُ","and I fear"],["أَن","that"],["يَأْكُلَهُ","would eat him"],["ٱلذِّئْبُ","a wolf"],["وَأَنتُمْ","while you"],["عَنْهُ","of him"],["غَـٰفِلُونَ","(are) unaware"]]],"1610":["(Mereka berkata, \"Jika benar-benar) lam di sini bermakna qasam atau sumpah (ia dimakan oleh serigala sedangkan kami adalah golongan yang kuat) kelompok yang kuat (sesungguhnya kami kalau demikian adalah orang-orang yang merugi.\") orang-orang yang tidak mampu membela diri. Kemudian setelah itu Nabi Yakub mengizinkan kepergian mereka membawa Nabi Yusuf.",[["قَالُوا۟","They said"],["لَئِنْ","If"],["أَكَلَهُ","eats him"],["ٱلذِّئْبُ","the wolf"],["وَنَحْنُ","while we"],["عُصْبَةٌ","(are) a group"],["إِنَّآ","indeed, we"],["إِذًۭا","then"],["لَّخَـٰسِرُونَ","surely (would be) losers"]]],"1611":["(Maka tatkala mereka membawanya dan sepakat) telah bertekad bulat (untuk memasukkannya ke dalam sumur) jawab dari lafal lammaa tidak disebutkan, yaitu maka mereka melakukan niatnya itu. Untuk itu mereka melepas baju Nabi Yusuf setelah terlebih dahulu dipukuli dan dicaci maki, kemudian mereka mengulurkan tali timba ke dalam sumur tersebut sedangkan Nabi Yusuf diikatkan padanya. Ketika tali timba mencapai setengah kedalaman sumur, lalu mereka melepaskannya, supaya Nabi Yusuf jatuh ke bawah lalu mati. Akan tetapi Nabi Yusuf jatuh di air, kemudian ia duduk di atas batu besar yang ada dalam sumur itu. Lalu saudara-saudaranya menyerunya, dan Nabi Yusuf menjawab seruan mereka; akan tetapi mereka menganggap bahwa Nabi Yusuf meminta pertolongan kepada mereka. Mereka bermaksud untuk menimpakan batu besar kepadanya, akan tetapi mereka dicegah oleh Yahudza. (Dan Kami wahyukan kepadanya) sewaktu ia berada di dalam sumur. Nabi Yusuf hidup di dalam sumur selama tujuh belas tahun atau kurang daripadanya. Allah memberikan wahyu kepadanya sebagai penenang hatinya (\"Sesungguhnya kamu akan menceritakan kepada mereka) sesudah peristiwa ini (tentang perbuatan mereka ini) tentang perlakuan mereka ini (sedangkan mereka tiada ingat lagi.\") terhadap dirimu sewaktu kamu bercerita kepada mereka.",[["فَلَمَّا","So when"],["ذَهَبُوا۟","they took him"],["بِهِۦ","they took him"],["وَأَجْمَعُوٓا۟","and agreed"],["أَن","that"],["يَجْعَلُوهُ","they put him"],["فِى","in"],["غَيَـٰبَتِ","(the) bottom"],["ٱلْجُبِّ ۚ","(of) the well"],["وَأَوْحَيْنَآ","But We inspired"],["إِلَيْهِ","to him"],["لَتُنَبِّئَنَّهُم","Surely, you will inform them"],["بِأَمْرِهِمْ","about this affair"],["هَـٰذَا","about this affair"],["وَهُمْ","while they"],["لَا","(do) not"],["يَشْعُرُونَ","perceive"]]],"1612":["(Kemudian mereka datang kepada ayah mereka di sore hari) pada waktu sore (sambil menangis).",[["وَجَآءُوٓ","And they came"],["أَبَاهُمْ","(to) their father"],["عِشَآءًۭ","early at night"],["يَبْكُونَ","weeping"]]],"1613":["(Mereka berkata, \"Wahai ayah kami! Sesungguhnya kami pergi berlomba-lomba) memanah (dan kami tinggalkan Yusuf di dekat barang-barang kami) yakni pakaian-pakaian kami (lalu dia dimakan oleh serigala dan engkau sekali-kali tidak akan percaya) mempercayai (kepada kami sekali pun kami adalah orang-orang yang benar.\") terhadapmu. Pasti engkau akan menuduh kami dengan tuduhan yang bukan-bukan sehubungan dengan perihal Yusuf ini karena kecintaanmu terhadapnya. Mengapa sampai sedemikian buruknya persangkaanmu terhadap diri kami?",[["قَالُوا۟","They said"],["يَـٰٓأَبَانَآ","O our father"],["إِنَّا","Indeed, we"],["ذَهَبْنَا","[we] went"],["نَسْتَبِقُ","racing each other"],["وَتَرَكْنَا","and we left"],["يُوسُفَ","Yusuf"],["عِندَ","with"],["مَتَـٰعِنَا","our possessions"],["فَأَكَلَهُ","and ate him"],["ٱلذِّئْبُ ۖ","the wolf"],["وَمَآ","But not"],["أَنتَ","you"],["بِمُؤْمِنٍۢ","(will) believe"],["لَّنَا","us"],["وَلَوْ","even if"],["كُنَّا","we are"],["صَـٰدِقِينَ","truthful"]]],"1614":["(Mereka datang membawa baju gamisnya) lafal `alaa qamiishihi beri'rab mahal nashab karena menjadi zharaf. Artinya yang berlumuran padanya (dengan darah palsu) darah yang bukan darah Nabi Yusuf; hal ini mereka lakukan dengan menyembelih seekor kambing, kemudian mereka lumurkan darahnya pada baju gamis Nabi Yusuf, akan tetapi mereka lupa merobek-robeknya. Lalu mereka menghadap kepada ayahnya seraya berkata, \"Sesungguhnya ini adalah darah Yusuf.\" (Yakub berkata) sewaktu ia melihat baju Yusuf dalam keadaan utuh dan ia mengetahui bahwa mereka berdusta dalam hal ini (\"Sebenarnya telah menghiasi) menganggap baik (diri kalian suatu perbuatan yang buruk) kemudian kalian mengerjakannya (maka kesabaran yang baik itulah kesabaranku) kesabaran yang tidak disertai rasa kaget dan gelisah. Lafal fashabrun jamiil ini adalah mubtada sedangkan khabarnya tidak disebutkan, yaitu amri yang artinya adalah kesabaranku. (Dan Allah sajalah yang dimohon pertolongan-Nya) hanya Allahlah yang diminta pertolongan-Nya (terhadap apa yang kalian ceritakan.\") apa yang kalian kisahkan tentang perkara Yusuf ini.",[["وَجَآءُو","And they brought"],["عَلَىٰ","upon"],["قَمِيصِهِۦ","his shirt"],["بِدَمٍۢ","with false blood"],["كَذِبٍۢ ۚ","with false blood"],["قَالَ","He said"],["بَلْ","Nay"],["سَوَّلَتْ","has enticed you"],["لَكُمْ","has enticed you"],["أَنفُسُكُمْ","your souls"],["أَمْرًۭا ۖ","(to) a matter"],["فَصَبْرٌۭ","so patience"],["جَمِيلٌۭ ۖ","(is) beautiful"],["وَٱللَّهُ","And Allah"],["ٱلْمُسْتَعَانُ","(is) the One sought for help"],["عَلَىٰ","against"],["مَا","what"],["تَصِفُونَ","you describe"]]],"1615":["(Kemudian datanglah kelompok orang-orang musafir) rombongan orang-orang yang melakukan perjalanan dari Madyan ke Mesir, lalu mereka istirahat di dekat sumur Nabi Yusuf (lalu mereka menyuruh seorang pengambil air) yang khusus untuk mencari air buat minum rombongan musafir (maka dia menurunkan) melepaskan (timbanya) ke dalam sumur kemudian Nabi Yusuf bergantung ke tali timba, sehingga keluarlah Nabi Yusuf dari dalam sumur itu. Ketika pengambil air melihat Nabi Yusuf (dia berkata, \"Oh, kabar gembira) menurut suatu qiraat dibaca busyraaya seruan di sini mengandung makna majaz, artinya cepatlah ini sudah masanya bagimu (ini seorang anak muda.\") maka hal itu diketahui oleh teman-teman penimba air, lalu mereka mendatanginya. (Kemudian mereka menyembunyikan dia) artinya, mereka merahasiakan perkara Nabi Yusuf ini, dengan maksud untuk menjadikannya (sebagai barang dagangan) seumpamanya mereka menganggapnya sebagai budak yang telah minggat kemudian ditemukan lagi. Sedangkan Nabi Yusuf diam saja karena ia merasa khawatir akan dibunuh oleh mereka. (Dan Allah Maha Mengetahui apa yang mereka kerjakan.)",[["وَجَآءَتْ","And there came"],["سَيَّارَةٌۭ","a caravan"],["فَأَرْسَلُوا۟","and they sent"],["وَارِدَهُمْ","their water drawer"],["فَأَدْلَىٰ","then he let down"],["دَلْوَهُۥ ۖ","his bucket"],["قَالَ","He said"],["يَـٰبُشْرَىٰ","O good news"],["هَـٰذَا","This"],["غُلَـٰمٌۭ ۚ","(is) a boy"],["وَأَسَرُّوهُ","And they hid him"],["بِضَـٰعَةًۭ ۚ","(as) a merchandise"],["وَٱللَّهُ","And Allah"],["عَلِيمٌۢ","(is) All-Knower"],["بِمَا","of what"],["يَعْمَلُونَ","they do"]]],"1616":["(Dan mereka menjual Yusuf) orang-orang musafir itu membelinya dari tangan penimba air dan teman-temannya (dengan harga yang murah) kurang dari semestinya (yaitu hanya beberapa dirham saja) sekitar dua puluh atau dua puluh dua dirham saja (dan mereka) yakni saudara-saudara penimba air itu (merasa tidak tertarik hatinya kepada Yusuf) kemudian rombongan musafir itu membawa Yusuf ke negeri Mesir selanjutnya Nabi Yusuf dijual oleh orang yang membelinya dengan harga dua puluh dinar, dua pasang terompah dan dua buah baju.",[["وَشَرَوْهُ","And they sold him"],["بِثَمَنٍۭ","for a price"],["بَخْسٍۢ","very low"],["دَرَٰهِمَ","dirhams"],["مَعْدُودَةٍۢ","few"],["وَكَانُوا۟","and they were"],["فِيهِ","about him"],["مِنَ","of"],["ٱلزَّٰهِدِينَ","those keen to give up"]]],"1617":["(Dan orang Mesir yang membelinya berkata) dia bernama Qithfir Al-Aziz (kepada istrinya) yaitu Zulaikha (\"Berikanlah kepadanya tempat dan layanan yang baik) muliakanlah dia di antara kita (boleh jadi dia bermanfaat bagi kita atau kita pungut dia sebagai anak.\") disebutkan bahwa Qithfir Al-Aziz tidak mempunyai anak atau impoten. (Dan demikian pulalah) artinya sebagaimana Kami selamatkan dia dari pembunuhan dan sewaktu di dalam sumur serta Kami jadikan hati Al-Aziz merasa sayang kepadanya (Kami memberikan kedudukan yang baik kepada Yusuf di muka bumi) negeri Mesir sehingga sampai pada waktunya (dan agar Kami ajarkan kepadanya takwil mimpi) makna mimpi; lafal linu`allimahu diathafkan kepada fi`il yang keberadaannya diperkirakan dan berta`alluq kepada lafal makkannaa; artinya Kami ajarkan kepadanya makna mimpi sehingga ia menguasainya. Atau huruf wawu yang sebelum linu`allimahu ini adalah huruf tambahan. (Dan Allah berkuasa terhadap urusan-Nya) tidak ada sesuatu pun yang dapat menghalang-halangi-Nya (tetapi kebanyakan manusia) yang dimaksud adalah orang-orang kafir (tidak mengetahui) hal tersebut.",[["وَقَالَ","And said"],["ٱلَّذِى","the one who"],["ٱشْتَرَىٰهُ","bought him"],["مِن","of"],["مِّصْرَ","Egypt"],["لِٱمْرَأَتِهِۦٓ","to his wife"],["أَكْرِمِى","Make comfortable"],["مَثْوَىٰهُ","his stay"],["عَسَىٰٓ","Perhaps"],["أَن","that"],["يَنفَعَنَآ","(he) will benefit us"],["أَوْ","or"],["نَتَّخِذَهُۥ","we will take him"],["وَلَدًۭا ۚ","(as) a son"],["وَكَذَٰلِكَ","And thus"],["مَكَّنَّا","We established"],["لِيُوسُفَ","Yusuf"],["فِى","in"],["ٱلْأَرْضِ","the land"],["وَلِنُعَلِّمَهُۥ","that We might teach him"],["مِن","(the) interpretation of"],["تَأْوِيلِ","(the) interpretation of"],["ٱلْأَحَادِيثِ ۚ","the events"],["وَٱللَّهُ","And Allah"],["غَالِبٌ","(is) Predominant"],["عَلَىٰٓ","over"],["أَمْرِهِۦ","His affairs"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1618":["(Dan tatkala dia cukup dewasa) yaitu mencapai umur tiga puluh tahun atau tiga puluh tiga tahun (Kami berikan kepadanya hikmah) kebijaksanaan (dan ilmu) pengetahuan agama sebelum ia diangkat menjadi nabi. (Demikianlah) sebagaimana Kami berikan imbalan kepadanya (Kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri.",[["وَلَمَّا","And when"],["بَلَغَ","he reached"],["أَشُدَّهُۥٓ","his maturity"],["ءَاتَيْنَـٰهُ","We gave him"],["حُكْمًۭا","wisdom"],["وَعِلْمًۭا ۚ","and knowledge"],["وَكَذَٰلِكَ","And thus"],["نَجْزِى","We reward"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"1619":["(Dan wanita, yang Yusuf tinggal di rumahnya menggoda Yusuf) yaitu Zulaikha (untuk menundukkan dirinya kepadanya) yakni ia meminta kepada Yusuf supaya mau memenuhi kehendaknya (dan dia menutup pintu-pintu) rumah (seraya berkata) kepada Yusuf (\"Marilah ke sini.\") artinya kemarilah; huruf lam dari lafal haitalak bermakna tabyin atau untuk menjelaskan. Menurut qiraat dibaca dengan dikasrahkan huruf ha-nya, sehingga bacaannya menjadi hiitalak. Sedangkan menurut qiraat lainnya dapat dibaca haytulak dengan mendamahkan huruf ta-nya. (Yusuf berkata, \"Aku berlindung kepada Allah) artinya aku berlindung kepada Allah dari perbuatan itu (sesungguhnya dia) artinya orang yang telah membelinya (adalah tuanku) majikanku (telah memperlakukan aku dengan baik) telah berlaku baik terhadap diriku maka aku tidak akan mengkhianatinya dengan berlaku tidak baik terhadap istrinya (sesungguhnya) pada kenyataannya (orang-orang yang lalim tiada akan beruntung) yang dimaksud adalah orang-orang yang suka berzina.",[["وَرَٰوَدَتْهُ","And sought to seduce him"],["ٱلَّتِى","she who"],["هُوَ","he (was)"],["فِى","in"],["بَيْتِهَا","her house"],["عَن","from"],["نَّفْسِهِۦ","his self"],["وَغَلَّقَتِ","And she closed"],["ٱلْأَبْوَٰبَ","the doors"],["وَقَالَتْ","and she said"],["هَيْتَ","Come on"],["لَكَ ۚ","you"],["قَالَ","He said"],["مَعَاذَ","I seek refuge in Allah"],["ٱللَّهِ ۖ","I seek refuge in Allah"],["إِنَّهُۥ","Indeed, he"],["رَبِّىٓ","(is) my lord"],["أَحْسَنَ","(who has) made good"],["مَثْوَاىَ ۖ","my stay"],["إِنَّهُۥ","Indeed"],["لَا","not"],["يُفْلِحُ","will succeed"],["ٱلظَّـٰلِمُونَ","the wrongdoers"]]],"1620":["(Sesungguhnya wanita itu telah mempunyai maksud terhadap Yusuf) artinya dia telah bermaksud terhadap Nabi Yusuf supaya menyetubuhinya (dan Yusuf pun bermaksud melakukannya pula dengan wanita itu) artinya Yusuf pun mempunyai keinginan yang sama (andaikata dia tidak melihat tanda dari Rabbnya) menurut Ibnu Abbas r.a. bahwa pada saat yang kritis itu tiba-tiba Nabi Yakub atau ayahnya tampak di hadapannya, lalu memukul dadanya sehingga keluarlah nafsu syahwat yang telah membara itu dari semua ujung-ujung jarinya. Jawab dari lafal laulaa ialah lajaama`ahaa; artinya niscaya Yusuf menyetubuhinya. (Demikianlah) Kami perlihatkan tanda kekuasaan-Ku kepadanya (agar Kami memalingkan daripadanya kemungkaran) perbuatan khianat (dan kekejian) perbuatan zina. (Sesungguhnya Yusuf itu termasuk hamba-hamba Kami yang terikhlas) dalam hal ketaatan. Menurut suatu qiraat dibaca mukhlishiin dengan dikasrahkan huruf lam-nya; artinya sama dengan lafal al-mukhtaariina atau orang-orang yang terpilih.",[["وَلَقَدْ","And certainly"],["هَمَّتْ","she did desire"],["بِهِۦ ۖ","him"],["وَهَمَّ","and he would have desired"],["بِهَا","her"],["لَوْلَآ","if not"],["أَن","that"],["رَّءَا","he saw"],["بُرْهَـٰنَ","the proof"],["رَبِّهِۦ ۚ","(of) his Lord"],["كَذَٰلِكَ","Thus"],["لِنَصْرِفَ","that We might avert"],["عَنْهُ","from him"],["ٱلسُّوٓءَ","the evil"],["وَٱلْفَحْشَآءَ ۚ","and the immorality"],["إِنَّهُۥ","Indeed, he"],["مِنْ","(was) of"],["عِبَادِنَا","Our slaves"],["ٱلْمُخْلَصِينَ","the sincere"]]],"1621":["(Dan keduanya berlomba-lomba menuju pintu) Yusuf segera lari menuju ke pintu rumah untuk melepaskan diri daripadanya. Sedangkan Zulaikha yang sudah kerasukan nafsu syahwatnya memegang baju bagian belakang Yusuf kemudian berupaya menariknya (dan robeklah) menjadi sobek (baju gamis Yusuf dari arah belakangnya dan kedua-duanya mendapati) menemukan (suami wanita itu) suami Zulaikha (di muka pintu) maka secara spontan Zulaikha membersihkan dirinya selanjutnya. (Wanita itu berkata, \"Tiadalah pembalasan terhadap orang yang bermaksud berbuat serong dengan istrimu) yakni berzina (selain dipenjarakan) ditahan di dalam penjara (atau dihukum dengan siksaan yang pedih?\") siksaan yang menyakitkan, dipukuli umpamanya.",[["وَٱسْتَبَقَا","And they both raced"],["ٱلْبَابَ","(to) the door"],["وَقَدَّتْ","and she tore"],["قَمِيصَهُۥ","his shirt"],["مِن","from"],["دُبُرٍۢ","the back"],["وَأَلْفَيَا","and they both found"],["سَيِّدَهَا","her husband"],["لَدَا","at"],["ٱلْبَابِ ۚ","the door"],["قَالَتْ","She said"],["مَا","What"],["جَزَآءُ","(is) the recompense"],["مَنْ","(of one) who"],["أَرَادَ","intended"],["بِأَهْلِكَ","for your wife"],["سُوٓءًا","evil"],["إِلَّآ","except"],["أَن","that"],["يُسْجَنَ","he be imprisoned"],["أَوْ","or"],["عَذَابٌ","a punishment"],["أَلِيمٌۭ","painful"]]],"1622":["(Yusuf berkata) membela dirinya (\"Dia menggodaku untuk menundukkan diriku kepadanya,\" dan seorang saksi dari keluarga wanita itu memberikan kesaksiannya) sepupu Zulaikha. Tetapi menurut suatu riwayat disebutkan, bahwa saksi itu adalah bayi yang masih dalam ayunan. Kemudian saksi itu mengatakan (\"Jika baju gamisnya koyak di muka) pada bagian muka Yusuf (maka wanita itu benar dan Yusuf termasuk orang-orang yang dusta.\").",[["قَالَ","He said"],["هِىَ","She"],["رَٰوَدَتْنِى","sought to seduce me"],["عَن","about"],["نَّفْسِى ۚ","myself"],["وَشَهِدَ","And testified"],["شَاهِدٌۭ","a witness"],["مِّنْ","of"],["أَهْلِهَآ","her family"],["إِن","If"],["كَانَ","[is]"],["قَمِيصُهُۥ","his shirt"],["قُدَّ","(is) torn"],["مِن","from"],["قُبُلٍۢ","the front"],["فَصَدَقَتْ","then she has spoken the truth"],["وَهُوَ","and he"],["مِنَ","(is) of"],["ٱلْكَـٰذِبِينَ","the liars"]]],"1623":["(\"Dan jika baju gamisnya koyak di belakangnya) pada bagian belakang Yusuf (maka wanita itulah yang dusta dan Yusuf termasuk orang-orang yang benar.\")",[["وَإِن","But if"],["كَانَ","[is]"],["قَمِيصُهُۥ","his shirt"],["قُدَّ","(is) torn"],["مِن","from"],["دُبُرٍۢ","(the) back"],["فَكَذَبَتْ","then she has lied"],["وَهُوَ","and he"],["مِنَ","(is) of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1624":["(Maka tatkala suami wanita itu melihat) suami Zulaikha (baju gamis Yusuf koyak di belakang berkatalah dia, \"Sesungguhnya kejadian itu) yang kamu katakan, apakah pembalasan terhadap orang yang bermaksud memperkosa istrimu (adalah di antara tipu daya kalian) hai kaum wanita (sesungguhnya tipu daya kalian adalah besar.\").",[["فَلَمَّا","So when"],["رَءَا","he saw"],["قَمِيصَهُۥ","his shirt"],["قُدَّ","torn"],["مِن","from"],["دُبُرٍۢ","(the) back"],["قَالَ","he said"],["إِنَّهُۥ","Indeed, it"],["مِن","(is) of"],["كَيْدِكُنَّ ۖ","your plot"],["إِنَّ","Indeed"],["كَيْدَكُنَّ","your plot"],["عَظِيمٌۭ","(is) great"]]],"1625":["Selanjutnya suami wanita itu berkata, \"Hai (Yusuf! Berpalinglah dari ini) dari peristiwa ini, lupakanlah supaya jangan tersiar beritanya (dan kamu mohon ampunlah) hai Zulaikha istriku (atas dosamu itu, karena kamu sesungguhnya termasuk orang-orang yang berbuat salah.\") yakni orang-orang yang telah berbuat dosa. Akan tetapi peristiwa itu beritanya tidak dapat disembunyikan lalu tersiarlah di kalangan masyarakat.",[["يُوسُفُ","Yusuf"],["أَعْرِضْ","turn away"],["عَنْ","from"],["هَـٰذَا ۚ","this"],["وَٱسْتَغْفِرِى","And ask forgiveness"],["لِذَنۢبِكِ ۖ","for your sin"],["إِنَّكِ","Indeed, you"],["كُنتِ","are"],["مِنَ","of"],["ٱلْخَاطِـِٔينَ","the sinful"]]],"1626":["(Dan wanita-wanita di kota berkata) yaitu kota Mesir (\"Istri Aziz menggoda bujangnya) yaitu hamba sahaya lakinya (untuk menundukkan dirinya menuruti kemauannya, sesungguhnya cintanya kepada bujangnya itu adalah sangat mendalam) lafal hubban berkedudukan menjadi tamyiz; artinya cinta Zulaikha terhadap Yusuf telah merasup ke dalam lubuk hatinya. (Sesungguhnya kami memandangnya dalam kesesatan yang nyata.\") jelas sesat karena mencintai hambanya sendiri.",[["۞ وَقَالَ","And said"],["نِسْوَةٌۭ","women"],["فِى","in"],["ٱلْمَدِينَةِ","the city"],["ٱمْرَأَتُ","The wife of"],["ٱلْعَزِيزِ","Aziz"],["تُرَٰوِدُ","(is) seeking to seduce"],["فَتَىٰهَا","her slave boy"],["عَن","about"],["نَّفْسِهِۦ ۖ","himself"],["قَدْ","indeed"],["شَغَفَهَا","he has impassioned her"],["حُبًّا ۖ","(with) love"],["إِنَّا","Indeed, we"],["لَنَرَىٰهَا","[we] surely see her"],["فِى","in"],["ضَلَـٰلٍۢ","an error"],["مُّبِينٍۢ","clear"]]],"1627":["(Maka tatkala wanita itu mendengar cercaan mereka) pergunjingan mereka terhadap dirinya (diundangnyalah wanita-wanita itu dan disediakannya) Zulaikha mempersiapkan (bagi mereka makanan) yang harus dipotong terlebih dahulu dengan pisau dan beralaskan pada talenan (dan diberikannya) Zulaikha memberikan (kepada masing-masing mereka sebuah pisau, kemudian dia berkata) kepada Yusuf (\"Keluarlah kepada mereka.\" Maka tatkala wanita-wanita itu melihatnya, mereka merasa kagum terhadapnya) kepada ketampanan dan keelokan rupanya (dan mereka melukai jari tangannya) dengan pisau-pisau yang mereka pegang itu tanpa mereka sadari dan tanpa merasa sakit karena kekaguman mereka terhadap ketampanan Yusuf (dan berkatalah mereka, \"Maha Sempurna Allah) dimaksud sebagai ungkapan memahasucikan Allah swt. (ini bukanlah) artinya Nabi Yusuf ini (manusia tetapi) melainkan (ia adalah malaikat yang mulia.\") mengingat ketampanan dan keelokan rupanya hal ini tidak akan ditemui pada manusia. Di dalam sebuah hadis disebutkan bahwasanya Nabi Yusuf telah dianugerahi separuh dari ketampanan dan keelokan rupa.",[["فَلَمَّا","So when"],["سَمِعَتْ","she heard"],["بِمَكْرِهِنَّ","of their scheming"],["أَرْسَلَتْ","she sent"],["إِلَيْهِنَّ","for them"],["وَأَعْتَدَتْ","and she prepared"],["لَهُنَّ","for them"],["مُتَّكَـًۭٔا","a banquet"],["وَءَاتَتْ","and she gave"],["كُلَّ","each"],["وَٰحِدَةٍۢ","one"],["مِّنْهُنَّ","of them"],["سِكِّينًۭا","a knife"],["وَقَالَتِ","and she said"],["ٱخْرُجْ","Come out"],["عَلَيْهِنَّ ۖ","before them"],["فَلَمَّا","Then when"],["رَأَيْنَهُۥٓ","they saw him"],["أَكْبَرْنَهُۥ","they greatly admired him"],["وَقَطَّعْنَ","and cut"],["أَيْدِيَهُنَّ","their hands"],["وَقُلْنَ","they said"],["حَـٰشَ","Forbid"],["لِلَّهِ","Allah"],["مَا","not"],["هَـٰذَا","(is) this"],["بَشَرًا","a man"],["إِنْ","not"],["هَـٰذَآ","(is) this"],["إِلَّا","but"],["مَلَكٌۭ","an angel"],["كَرِيمٌۭ","noble"]]],"1628":["(Wanita itu berkata) yang dimaksud adalah istri Al-Aziz sewaktu ia melihat apa yang terjadi pada diri mereka (\"Itulah dia) dialah (orangnya yang kalian cela aku karena tertarik kepadanya) karena aku mencintainya. Kalimat ini merupakan penjelasan tentang alasan Zulaikha (dan sesungguhnya aku telah menggoda dia untuk menundukkan dirinya kepadaku akan tetapi ia mempertahankan dirinya) menolak. (Dan sesungguhnya jika dia tidak menaati apa yang aku perintahkan kepadanya) untuk dilakukannya (niscaya dia akan dipenjarakan dan dia akan termasuk golongan orang-orang yang hina\") orang-orang yang tidak terpandang. Maka wanita-wanita itu berkata kepada Yusuf, \"Turutilah kemauan tuan wanitamu ini.\"",[["قَالَتْ","She said"],["فَذَٰلِكُنَّ","That"],["ٱلَّذِى","(is) the one"],["لُمْتُنَّنِى","you blamed me"],["فِيهِ ۖ","about him"],["وَلَقَدْ","And certainly"],["رَٰوَدتُّهُۥ","I sought to seduce him"],["عَن","[from]"],["نَّفْسِهِۦ","[himself]"],["فَٱسْتَعْصَمَ ۖ","but he saved himself"],["وَلَئِن","and if"],["لَّمْ","not"],["يَفْعَلْ","he does"],["مَآ","what"],["ءَامُرُهُۥ","I order him"],["لَيُسْجَنَنَّ","surely, he will be imprisoned"],["وَلَيَكُونًۭا","and certainly will be"],["مِّنَ","of"],["ٱلصَّـٰغِرِينَ","those who are disgraced"]]],"1629":["(Yusuf berkata, \"Wahai Rabbku! Penjara lebih aku sukai daripada memenuhi ajakan mereka kepadaku. Dan jika tidak Engkau hindarkan aku dari tipu daya mereka, tentu aku akan cenderung untuk) memenuhi (kemauan mereka dan tentulah aku) menjadi (termasuk orang-orang yang bodoh\") yakni orang-orang yang berbuat dosa. Makna yang dimaksud adalah berdoa. Pada ayat selanjutnya Allah berfirman:",[["قَالَ","He said"],["رَبِّ","My Lord"],["ٱلسِّجْنُ","the prison"],["أَحَبُّ","(is) dearer"],["إِلَىَّ","to me"],["مِمَّا","than what"],["يَدْعُونَنِىٓ","they invite me"],["إِلَيْهِ ۖ","to it"],["وَإِلَّا","And unless"],["تَصْرِفْ","You turn away"],["عَنِّى","from me"],["كَيْدَهُنَّ","their plot"],["أَصْبُ","I might incline"],["إِلَيْهِنَّ","towards them"],["وَأَكُن","and [I] be"],["مِّنَ","of"],["ٱلْجَـٰهِلِينَ","the ignorant"]]],"1630":["(Maka Rabbnya memperkenankan doa Yusuf) permintaannya (dan Dia menghindarkan Yusuf dari tipu daya mereka. Sesungguhnya Dialah Yang Maha Mendengar) semua pembicaraan (lagi Maha Mengetahui) semua pekerjaan.",[["فَٱسْتَجَابَ","So responded"],["لَهُۥ","to him"],["رَبُّهُۥ","his Lord"],["فَصَرَفَ","and turned away"],["عَنْهُ","from him"],["كَيْدَهُنَّ ۚ","their plot"],["إِنَّهُۥ","Indeed, [He]"],["هُوَ","He"],["ٱلسَّمِيعُ","(is) All-Hearer"],["ٱلْعَلِيمُ","All-Knower"]]],"1631":["(Kemudian timbul pikiran) tampak nyata (pada mereka setelah melihat tanda-tanda) yang menunjukkan kebersihan diri Nabi Yusuf, yaitu memenjarakannya. Hal ini terbukti dengan adanya penjelasan pada ayat selanjutnya (bahwa mereka harus memenjarakannya sampai) hingga (sesuatu waktu) semua yang hadir setuju dengan pendapat ini akhirnya Nabi Yusuf dipenjarakan.",[["ثُمَّ","Then"],["بَدَا","(it) appeared"],["لَهُم","to them"],["مِّنۢ","after"],["بَعْدِ","after"],["مَا","[what]"],["رَأَوُا۟","they had seen"],["ٱلْـَٔايَـٰتِ","the signs"],["لَيَسْجُنُنَّهُۥ","surely they should imprison him"],["حَتَّىٰ","until"],["حِينٍۢ","a time"]]],"1632":["(Dan bersama dengan dia masuk pula ke dalam penjara dua orang pemuda) dua orang pelayan raja; salah seorang di antaranya bekas atau mantan penyuguh minumannya dan yang seorang lainnya mantan penyuguh makanannya. Kemudian mereka berdua melihat bahwa Nabi Yusuf pandai menakwilkan arti mimpi lalu keduanya sepakat untuk mengujinya. (Berkatalah salah seorang di antara keduanya) yaitu mantan penyuguh minuman raja (\"Sesungguhnya aku bermimpi bahwa aku memeras khamar.\") yang dimaksud adalah memeras anggur (Dan yang lainnya berkata) yaitu mantan penyuguh hidangan raja (\"Sesungguhnya aku bermimpi bahwa aku membawa roti di atas kepalaku, sebagiannya dimakan burung. Berikanlah kepada kami) ceritakanlah kepada kami (takbirnya) arti impian itu (sesungguhnya kami memandang kamu termasuk orang-orang yang pandai menakwilkan mimpi.\").",[["وَدَخَلَ","And entered"],["مَعَهُ","with him"],["ٱلسِّجْنَ","(in) the prison"],["فَتَيَانِ ۖ","two young men"],["قَالَ","Said"],["أَحَدُهُمَآ","one of them"],["إِنِّىٓ","Indeed, I"],["أَرَىٰنِىٓ","[I] see myself"],["أَعْصِرُ","pressing"],["خَمْرًۭا ۖ","wine"],["وَقَالَ","And said"],["ٱلْـَٔاخَرُ","the other"],["إِنِّىٓ","Indeed, I"],["أَرَىٰنِىٓ","[I] see myself"],["أَحْمِلُ","[I am] carrying"],["فَوْقَ","over"],["رَأْسِى","my head"],["خُبْزًۭا","bread"],["تَأْكُلُ","(were) eating"],["ٱلطَّيْرُ","the birds"],["مِنْهُ ۖ","from it"],["نَبِّئْنَا","Inform us"],["بِتَأْوِيلِهِۦٓ ۖ","of its interpretation"],["إِنَّا","indeed, we"],["نَرَىٰكَ","[we] see you"],["مِنَ","of"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"1633":["(Yusuf berkata) kepada kedua pemuda itu seraya menegaskan, bahwa dirinya pandai di dalam menakbirkan arti mimpi (\"Tidak disampaikan kepada kamu berdua makanan yang akan diberikan kepadamu) di dalam mimpi kamu berdua (melainkan aku telah dapat menerangkan takwilnya) apa yang akan terjadi di alam kenyataan (sebelum makanan itu sampai kepada kamu berdua) sebelum kenyataan mimpi itu menimpa kalian berdua. (Yang demikian itu adalah sebagian dari apa yang diajarkan kepadaku oleh Rabbku) di dalam ungkapan ini terkandung pengertian yang menganjurkan supaya mereka berdua beriman kepada Allah. Selanjutnya hal ini diperkuat oleh perkataannya lagi, yaitu: (Sesungguhnya aku telah meninggalkan tuntunan) agama (orang-orang yang tidak beriman kepada Allah sedangkan mereka terhadap hari kiamat benar-benar) sungguh (ingkar\").",[["قَالَ","He said"],["لَا","Not"],["يَأْتِيكُمَا","(will) come to both of you"],["طَعَامٌۭ","food"],["تُرْزَقَانِهِۦٓ","you are provided with"],["إِلَّا","but"],["نَبَّأْتُكُمَا","I will inform both of you"],["بِتَأْوِيلِهِۦ","of its interpretation"],["قَبْلَ","before"],["أَن","[that]"],["يَأْتِيَكُمَا ۚ","[it] comes to both of you"],["ذَٰلِكُمَا","That"],["مِمَّا","(is) of what"],["عَلَّمَنِى","has taught me"],["رَبِّىٓ ۚ","my Lord"],["إِنِّى","Indeed, I"],["تَرَكْتُ","[I] abandon"],["مِلَّةَ","(the) religion"],["قَوْمٍۢ","(of) a people"],["لَّا","not"],["يُؤْمِنُونَ","they believe"],["بِٱللَّهِ","in Allah"],["وَهُم","and they"],["بِٱلْـَٔاخِرَةِ","in the Hereafter"],["هُمْ","[they]"],["كَـٰفِرُونَ","(are) disbelievers"]]],"1634":["(\"Dan aku mengikuti agama bapak-bapakku, yaitu Ibrahim, Ishak dan Yakub. Tiadalah patut) tidak pantas (bagi kami mempersekutukan Allah dengan) huruf min di sini zaidah (sesuatu pun) karena kami selalu memelihara (yang demikian itu) yakni ajaran tauhid (adalah karunia Allah kepada kami dan kepada manusia seluruhnya tetapi kebanyakan manusia itu) dimaksud adalah orang-orang kafir (tidak mensyukuri.\") terhadap Allah; lalu mereka menyekutukan-Nya. Kemudian Nabi Yusuf menjelaskan ajakannya kepada mereka berdua agar keduanya beriman seraya berkata:",[["وَٱتَّبَعْتُ","And I follow"],["مِلَّةَ","(the) religion"],["ءَابَآءِىٓ","(of) my forefathers"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ","and Isaac"],["وَيَعْقُوبَ ۚ","and Yaqub"],["مَا","Not"],["كَانَ","was"],["لَنَآ","for us"],["أَن","that"],["نُّشْرِكَ","we associate"],["بِٱللَّهِ","with Allah"],["مِن","any"],["شَىْءٍۢ ۚ","thing"],["ذَٰلِكَ","That"],["مِن","(is) from"],["فَضْلِ","(the) Grace"],["ٱللَّهِ","(of) Allah"],["عَلَيْنَا","upon us"],["وَعَلَى","and upon"],["ٱلنَّاسِ","the mankind"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the men"],["لَا","(are) not"],["يَشْكُرُونَ","grateful"]]],"1635":["(\"Hai kedua temanku) yang satu tempat tinggal (dalam penjara! Manakah yang baik tuhan yang bermacam-macam itu ataukah Allah Yang Maha Esa lagi Maha Perkasa?\") pilihlah! Istifham atau kata tanya di sini mengandung pengertian taqrir atau menetapkan.",[["يَـٰصَـٰحِبَىِ","O my two companions"],["ٱلسِّجْنِ","(of) the prison"],["ءَأَرْبَابٌۭ","Are lords"],["مُّتَفَرِّقُونَ","separate"],["خَيْرٌ","better"],["أَمِ","or"],["ٱللَّهُ","Allah"],["ٱلْوَٰحِدُ","the One"],["ٱلْقَهَّارُ","the Irresistible"]]],"1636":["(\"Kamu berdua tidak menyembah yang selain-Nya) selain Allah (melainkan hanya menyembah nama-nama yang dibuat-buat) yaitu kalian namakan mereka berhala-berhala (oleh kalian dan nenek moyang kalian sendiri, Allah tidak menurunkan tentang nama-nama itu) untuk disembah (suatu keterangan pun) hujah dan argumentasi. (Tiada lain) tiadalah (keputusan itu) kepastian itu (hanya kepunyaan Allah) semata (Dia telah memerintahkan agar kalian tidak menyembah selain Dia. Itulah) yakni agama tauhid itulah (agama yang lurus) agama yang mustaqim (tetapi kebanyakan manusia) orang-orang kafir (tidak mengetahui.\") apa yang bakal menimpa mereka, yaitu berupa azab; mereka benar-benar orang-orang yang menyekutukan-Nya.",[["مَا","Not"],["تَعْبُدُونَ","you worship"],["مِن","besides Him"],["دُونِهِۦٓ","besides Him"],["إِلَّآ","but"],["أَسْمَآءًۭ","names"],["سَمَّيْتُمُوهَآ","which you have named them"],["أَنتُمْ","you"],["وَءَابَآؤُكُم","and your forefathers"],["مَّآ","not"],["أَنزَلَ","(has) sent down"],["ٱللَّهُ","Allah"],["بِهَا","for it"],["مِن","any"],["سُلْطَـٰنٍ ۚ","authority"],["إِنِ","Not"],["ٱلْحُكْمُ","(is) the command"],["إِلَّا","but"],["لِلَّهِ ۚ","for Allah"],["أَمَرَ","He has commanded"],["أَلَّا","that not"],["تَعْبُدُوٓا۟","you worship"],["إِلَّآ","but"],["إِيَّاهُ ۚ","Him Alone"],["ذَٰلِكَ","That"],["ٱلدِّينُ","(is) the religion"],["ٱلْقَيِّمُ","the right"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","[the] men"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1637":["(\"Hai kedua temanku dalam penjara! Adapun salah seorang di antara kamu berdua) yang dimaksud adalah mantan penyuguh minuman raja; maka setelah tiga hari kemudian ia akan keluar dari penjara ini (akan memberi minum tuannya) rajanya (dengan khamar) sebagaimana biasa (dan adapun yang seorang lain) ia bakal keluar dari penjara ini setelah tiga hari (maka ia akan disalib, lalu burung memakan sebagian dari kepalanya) itulah makna mimpi kalian berdua. Kemudian keduanya menjawab, \"Kami sebenarnya tidak bermimpi melihat apa-apa.\" Nabi Yusuf berkata: (\"Telah diputuskan perkara yang kamu berdua menanyakannya.\") yang kamu berdua telah menanyakan perihalnya, apakah kamu berdua mempercayainya atau tidak, itu terserah.",[["يَـٰصَـٰحِبَىِ","O my two companions"],["ٱلسِّجْنِ","(of) the prison"],["أَمَّآ","As for"],["أَحَدُكُمَا","one of you"],["فَيَسْقِى","he will give drink"],["رَبَّهُۥ","(to) his master"],["خَمْرًۭا ۖ","wine"],["وَأَمَّا","and as for"],["ٱلْـَٔاخَرُ","the other"],["فَيُصْلَبُ","he will be crucified"],["فَتَأْكُلُ","and will eat"],["ٱلطَّيْرُ","the birds"],["مِن","from"],["رَّأْسِهِۦ ۚ","his head"],["قُضِىَ","Has been decreed"],["ٱلْأَمْرُ","the matter"],["ٱلَّذِى","about which"],["فِيهِ","about which"],["تَسْتَفْتِيَانِ","you both inquire"]]],"1638":["(Dan Yusuf berkata kepada orang yang diketahuinya) yang telah ia yakini (akan selamat di antara mereka berdua) yaitu mantan penyuguh minum raja (\"Jelaskanlah keadaanku kepada tuanmu\") yaitu kepada rajamu, bahwa sesungguhnya di dalam penjara ini terdapat seorang pemuda yang ditahan secara lalim, kemudian penyuguh minuman itu dikeluarkan dari penjara. (Maka ia dijadikan lupa) orang yang dimaksud adalah mantan penyuguh minuman (oleh setan menceritakan) tentang Nabi Yusuf (kepada tuannya. Karena itu tetaplah dia) Nabi Yusuf tetap tinggal (dalam penjara beberapa tahun lamanya) menurut suatu pendapat tujuh tahun dan menurut pendapat yang lain dua belas tahun.",[["وَقَالَ","And he said"],["لِلَّذِى","to the one whom"],["ظَنَّ","he thought"],["أَنَّهُۥ","that he"],["نَاجٍۢ","(would be) saved"],["مِّنْهُمَا","of both of them"],["ٱذْكُرْنِى","Mention me"],["عِندَ","to"],["رَبِّكَ","your master"],["فَأَنسَىٰهُ","But made him forget"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["ذِكْرَ","(the) mention"],["رَبِّهِۦ","(to) his master"],["فَلَبِثَ","so he remained"],["فِى","in"],["ٱلسِّجْنِ","the prison"],["بِضْعَ","several"],["سِنِينَ","years"]]],"1639":["(Raja berkata) raja negeri Mesir, yaitu Ar-Rayyan bin Walid (\"Sesungguhnya aku bermimpi melihat) fi'il mudhari' di sini bermakna fi'il madhi (tujuh ekor sapi betina yang gemuk-gemuk dimakan oleh) ditelan oleh (tujuh ekor) sapi (sapi betina yang kurus-kurus) lafal `ijaaf adalah bentuk jamak dari kata tunggal `ajfau, artinya sapi betina yang kurus (dan tujuh bulir gandum yang hijau dan yang lainnya) yakni tujuh bulir pula (kering) telah melingkar pada tujuh bulir yang hijau itu dan menutupinya. (Hai orang-orang yang terkemuka, terangkanlah kepadaku tentang takbir mimpiku itu) jelaskanlah kepadaku makna mimpiku itu (jika kalian dapat menakbirkan mimpi.\") ceritakanlah maknanya kepadaku sekarang juga.",[["وَقَالَ","And said"],["ٱلْمَلِكُ","the king"],["إِنِّىٓ","Indeed, I"],["أَرَىٰ","[I] have seen"],["سَبْعَ","seven"],["بَقَرَٰتٍۢ","cows"],["سِمَانٍۢ","fat"],["يَأْكُلُهُنَّ","eating them"],["سَبْعٌ","seven"],["عِجَافٌۭ","lean ones"],["وَسَبْعَ","and seven"],["سُنۢبُلَـٰتٍ","ears (of corn)"],["خُضْرٍۢ","green"],["وَأُخَرَ","and others"],["يَابِسَـٰتٍۢ ۖ","dry"],["يَـٰٓأَيُّهَا","O"],["ٱلْمَلَأُ","chiefs"],["أَفْتُونِى","Explain to me"],["فِى","about"],["رُءْيَـٰىَ","my vision"],["إِن","if"],["كُنتُمْ","you can"],["لِلرُّءْيَا","of visions"],["تَعْبُرُونَ","interpret"]]],"1640":["(Mereka menjawab,) \"itu (adalah mimpi-mimpi yang kosong) mimpi yang tidak ada artinya (dan kami sekali-kali tidak mengetahui tentang mentakwilkan mimpi.\")",[["قَالُوٓا۟","They said"],["أَضْغَـٰثُ","Confused"],["أَحْلَـٰمٍۢ ۖ","dreams"],["وَمَا","and not"],["نَحْنُ","we"],["بِتَأْوِيلِ","(are) in the interpretation"],["ٱلْأَحْلَـٰمِ","(of) the dreams"],["بِعَـٰلِمِينَ","learned"]]],"1641":["(Dan berkatalah orang yang selamat di antara mereka berdua) yaitu salah satu di antara kedua teman sepenjara Nabi Yusuf, mantan penyuguh minuman raja (dan ia teringat) kepada Nabi Yusuf. Lafal waddakara pada asalnya ialah tadzakkara, kemudian huruf ta diganti dal, selanjutnya huruf dzal asal diidghamkan kepada dal sehingga jadilah iddakara, artinya sama dengan lafal tadzakkara, yaitu ingat (sesudah beberapa waktu lamanya) setelah Nabi Yusuf tinggal beberapa lama di penjara, lalu mantan penyuguh minuman raja itu berkata (\"Aku akan memberitahukan kepada kalian tentang orang yang pandai menakwilkan mimpi itu, maka utuslah aku kepadanya.\") lalu mereka mengirimkan orang itu kepada orang yang dimaksudnya; kemudian orang itu mendatangi Nabi Yusuf seraya berkata kepadanya:",[["وَقَالَ","But said"],["ٱلَّذِى","the one who"],["نَجَا","was saved"],["مِنْهُمَا","of the two"],["وَٱدَّكَرَ","and remembered"],["بَعْدَ","after"],["أُمَّةٍ","a period"],["أَنَا۠","I"],["أُنَبِّئُكُم","[I] will inform you"],["بِتَأْوِيلِهِۦ","of its interpretation"],["فَأَرْسِلُونِ","so send me forth"]]],"1642":["\"Hai (Yusuf, hai orang yang amat dipercaya!) artinya orang yang jujur (Terangkanlah kepada kami tentang tujuh ekor sapi betina yang gemuk-gemuk yang dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir gandum yang hijau dan tujuh lainnya yang kering agar aku kembali kepada orang-orang itu) yaitu raja dan pembantu-pembantunya (agar mereka mengetahui\") takwil mimpi itu.",[["يُوسُفُ","Yusuf"],["أَيُّهَا","O"],["ٱلصِّدِّيقُ","the truthful one"],["أَفْتِنَا","Explain to us"],["فِى","about"],["سَبْعِ","(the) seven"],["بَقَرَٰتٍۢ","cows"],["سِمَانٍۢ","fat"],["يَأْكُلُهُنَّ","eating them"],["سَبْعٌ","seven"],["عِجَافٌۭ","lean ones"],["وَسَبْعِ","and seven"],["سُنۢبُلَـٰتٍ","ears (of corn)"],["خُضْرٍۢ","green"],["وَأُخَرَ","and other"],["يَابِسَـٰتٍۢ","dry"],["لَّعَلِّىٓ","that I may"],["أَرْجِعُ","return"],["إِلَى","to"],["ٱلنَّاسِ","the people"],["لَعَلَّهُمْ","so that they may"],["يَعْلَمُونَ","know"]]],"1643":["(Yusuf berkata, \"Supaya kalian bertanam) artinya tanamlah oleh kalian (tujuh tahun lamanya sebagaimana biasa) yakni secara terus-menerus; hal ini merupakan takbir daripada tujuh ekor sapi betina yang gemuk-gemuk (maka apa yang kalian panen hendaklah kalian biarkan) biarkanlah ia (dibulirnya) supaya jangan rusak (kecuali sedikit untuk kalian makan) maka boleh kalian menumbuknya.",[["قَالَ","He said"],["تَزْرَعُونَ","You will sow"],["سَبْعَ","(for) seven"],["سِنِينَ","years"],["دَأَبًۭا","as usual"],["فَمَا","and that which"],["حَصَدتُّمْ","you reap"],["فَذَرُوهُ","so leave it"],["فِى","in"],["سُنۢبُلِهِۦٓ","its ears"],["إِلَّا","except"],["قَلِيلًۭا","a little"],["مِّمَّا","from which"],["تَأْكُلُونَ","you (will) eat"]]],"1644":["(Kemudian sesudah itu akan datang) artinya sesudah tujuh musim yang subur-subur itu (tujuh tahun yang amat sulit) kekeringan dan masa sulit; hal ini merupakan takbir daripada tujuh ekor sapi betina yang kurus-kurus (yang menghabiskan apa yang kalian simpan untuk menghadapinya) akan memakan semua biji-bijian dari hasil panen yang selama tujuh tahun yang subur itu; dimaksud kalian memakannya selama tujuh tahun paceklik itu (kecuali sedikit dari yang kalian simpan) artinya simpanan yang sedikit itu jadikanlah sebagai bibit.",[["ثُمَّ","Then"],["يَأْتِى","will come"],["مِنۢ","after"],["بَعْدِ","after"],["ذَٰلِكَ","that"],["سَبْعٌۭ","seven"],["شِدَادٌۭ","hard (years)"],["يَأْكُلْنَ","(which will) consume"],["مَا","what"],["قَدَّمْتُمْ","you advanced"],["لَهُنَّ","for them"],["إِلَّا","except"],["قَلِيلًۭا","a little"],["مِّمَّا","of what"],["تُحْصِنُونَ","you (will) store"]]],"1645":["(Kemudian setelah itu akan datang) yaitu sesudah tujuh tahun musim paceklik itu (tahun yang padanya manusia diberi hujan) yakni hujan yang cukup (dan di masa itu mereka memeras anggur.\") dapat memeras anggur dan buah-buahan lainnya karena suburnya musim.",[["ثُمَّ","Then"],["يَأْتِى","will come"],["مِنۢ","after"],["بَعْدِ","after"],["ذَٰلِكَ","that"],["عَامٌۭ","a year"],["فِيهِ","in it"],["يُغَاثُ","will be given abundant rain"],["ٱلنَّاسُ","the people"],["وَفِيهِ","and in it"],["يَعْصِرُونَ","they will press"]]],"1646":["(Raja berkata) ketika utusannya datang dan mengisahkan kepadanya tentang takbir mimpinya itu (\"Bawalah dia kepadaku.\") bawalah orang yang telah menakbirkannya itu. (Maka tatkala datang kepadanya) kepada Nabi Yusuf (utusan raja itu) kemudian utusan itu meminta kepadanya supaya keluar dari penjara (berkatalah Yusuf) dengan maksud untuk membersihkan dirinya (\"Kembalilah kepada tuanmu dan tanyakanlah kepadanya) dimaksud supaya utusan raja itu menanyakan kepada raja (bagaimana) halnya (dengan wanita-wanita yang telah melukai tangannya. Sesungguhnya Rabbku) Tuhanku (Maha Mengetahui tipu daya mereka.\") kemudian utusan itu kembali, lalu ia menceritakan semuanya kepada sang raja, maka sang raja mengumpulkan wanita-wanita itu.",[["وَقَالَ","And said"],["ٱلْمَلِكُ","the king"],["ٱئْتُونِى","Bring him to me"],["بِهِۦ ۖ","Bring him to me"],["فَلَمَّا","But when"],["جَآءَهُ","came to him"],["ٱلرَّسُولُ","the messenger"],["قَالَ","he said"],["ٱرْجِعْ","Return"],["إِلَىٰ","to"],["رَبِّكَ","your lord"],["فَسْـَٔلْهُ","and ask him"],["مَا","what"],["بَالُ","(is the) case"],["ٱلنِّسْوَةِ","(of) the women"],["ٱلَّـٰتِى","who"],["قَطَّعْنَ","cut"],["أَيْدِيَهُنَّ ۚ","their hands"],["إِنَّ","Indeed"],["رَبِّى","my Lord"],["بِكَيْدِهِنَّ","of their plot"],["عَلِيمٌۭ","(is) All-Knower"]]],"1647":["(Raja berkata, \"Bagaimana keadaan kalian) bagaimana perihal kalian (ketika kalian menggoda Yusuf untuk menundukkan dirinya kepada kemauan kalian?\") apakah kalian memandang Yusuf mempunyai kecenderungan pada permintaan kalian itu? (Mereka berkata, \"Maha Sempurna Allah, kami tiada mengetahui sesuatu keburukan daripadanya.\" Berkatalah istri Al-Aziz, \"Sekarang jelaslah) menjadi gamblanglah (kebenaran itu, akulah yang menggodanya untuk menundukkan dirinya kepada kemauanku, dan sesungguhnya dia termasuk orang-orang yang benar.\") di dalam pengakuannya, sewaktu ia mengatakan dialah yang menggodaku untuk menundukkan diriku kepada kemauannya. Setelah itu sang raja memberitahukan pengakuan itu kepada Nabi Yusuf dan setelah mendengar hal tersebut, lalu Nabi Yusuf berkata:",[["قَالَ","He said"],["مَا","What"],["خَطْبُكُنَّ","(was) your affair"],["إِذْ","when"],["رَٰوَدتُّنَّ","you sought to seduce"],["يُوسُفَ","Yusuf"],["عَن","from"],["نَّفْسِهِۦ ۚ","himself"],["قُلْنَ","They said"],["حَـٰشَ","Allah forbid"],["لِلَّهِ","Allah forbid"],["مَا","Not"],["عَلِمْنَا","we know"],["عَلَيْهِ","about him"],["مِن","any"],["سُوٓءٍۢ ۚ","evil"],["قَالَتِ","Said"],["ٱمْرَأَتُ","(the) wife"],["ٱلْعَزِيزِ","(of) Aziz"],["ٱلْـَٔـٰنَ","Now"],["حَصْحَصَ","(is) manifest"],["ٱلْحَقُّ","the truth"],["أَنَا۠","I"],["رَٰوَدتُّهُۥ","sought to seduce him"],["عَن","from"],["نَّفْسِهِۦ","himself"],["وَإِنَّهُۥ","and indeed, he"],["لَمِنَ","(is) surely of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1648":["(\"Yang demikian itu) yang diisyaratkan adalah permintaan bersih diri (agar dia mengetahui) yang dimaksud adalah Al-Aziz (bahwa sesungguhnya aku tidak berkhianat kepadanya) terhadap istrinya (di belakangnya) lafal bil-gaib berkedudukan sebagai hal atau kata keterangan keadaan (dan bahwasanya Allah tidak meridai tipu daya orang-orang yang berkhianat.\") kemudian Nabi Yusuf bertawadhu` atau merendahkan diri terhadap Allah seraya mengatakan:",[["ذَٰلِكَ","That"],["لِيَعْلَمَ","he may know"],["أَنِّى","that I"],["لَمْ","not"],["أَخُنْهُ","[I] betray him"],["بِٱلْغَيْبِ","in secret"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["كَيْدَ","(the) plan"],["ٱلْخَآئِنِينَ","(of) the betrayers"]]]});